  所有历史名人.push({id:3,_code:6003,名称:"李斯",家族:"李",跳:3,统帅:23,武力:48,智力:97,政治:99,魅力:78,清廉:88,野心:12,性别:0,文化:8,介绍:"字通古。秦代著名政治家、文学家、书法家。曾辅佐秦始皇，始皇死后，他与赵高合谋伪造遗诏，立胡亥为二世皇帝。后为赵高所忌，被腰斩于咸阳闹市。"});
  所有历史名人.push({id:4,_code:6004,名称:"张巡",家族:"张",跳:4,统帅:78,武力:90,智力:58,政治:71,魅力:70,清廉:80,野心:30,性别:0,文化:8,介绍:"在睢阳保卫战中，在内无粮草，外无援兵的情况下死守睢阳，杀伤敌军数万，有效阻遏了叛军南犯之势、遮蔽了江淮，为唐朝战死。死后追封通真三太子。"});
