  所有历史名人.push({id:10,_code:6010,名称:"曾国藩",家族:"曾",跳:10,统帅:88,武力:54,智力:90,政治:96,魅力:84,清廉:96,野心:50,性别:0,文化:8,介绍:"初名子城，字伯涵，号涤生，宗圣曾子七十世孙。中国近代政治家、战略家、理学家、文学家，湘军的创立者和统帅。与李鸿章、左宗棠、张之洞并称“晚清四大名臣”。"});
  所有历史名人.push({id:11,_code:6011,名称:"王安石",家族:"王",跳:11,统帅:34,武力:77,智力:96,政治:98,魅力:62,清廉:94,野心:16,性别:0,文化:8,介绍:"字介甫，号半山，北宋著名的思想家、政治家、文学家、改革家。 促进宋代疑经变古学风的形成 ，其散文论点鲜明、逻辑严密，短文简洁峻切、短小精悍，名列“唐宋八大家”。"});
