  所有历史名人.push({id:14,_code:6014,名称:"吕玲绮",家族:"吕",跳:14,统帅:10,武力:80,智力:71,政治:71,魅力:80,清廉:67,野心:30,性别:1,文化:8,介绍:"游戏《三国志战记2》中的虚构人物，人物原型为汉末群雄吕布与正妻（演义为严夫人）之女，以继承其父的武勇而自豪。"});
  所有历史名人.push({id:15,_code:6015,名称:"班超",家族:"班",跳:15,统帅:95,武力:95,智力:88,政治:75,魅力:78,清廉:76,野心:25,性别:0,文化:8,介绍:"字仲升。东汉时期著名军事家、外交家。投笔从戎，随窦固出击北匈奴，又奉命出使西域，为西域回归、促进民族融合，做出了巨大贡献。"});
  所有历史名人.push({id:16,_code:6016,名称:"郑子产",家族:"郑",跳:16,统帅:55,武力:46,智力:93,政治:88,魅力:81,清廉:92,野心:35,性别:0,文化:8,介绍:"中国春秋时期政治家、思想家。姓公孙，名侨，字子产，号成子。他既维护公室的利益，又限制贵族的特权，进行了自上而下的改革。实行学而后入政、择能而使之的用人制度。"});
  所有历史名人.push({id:17,_code:6017,名称:"韩信",家族:"韩",跳:17,统帅:99,武力:80,智力:89,政治:75,魅力:82,清廉:77,野心:17,性别:0,文化:8,介绍:"西汉开国功臣，中国历史上杰出的军事家，与萧何、张良并列为汉初三杰。 汉朝建立后解除兵权，徙为楚王。 后吕后与萧何合谋将其骗入长乐宫中，斩于钟室，夷其三族。"});
