  所有历史名人.push({id:37,_code:6037,名称:"屈原",家族:"屈",跳:37,统帅:45,武力:36,智力:90,政治:88,魅力:65,清廉:88,野心:5,性别:0,文化:8,介绍:"名正则，字灵均，一名平，字原。是我国浪漫主义诗歌的奠基人，我国第一位伟大的爱国主义诗人，世界四大文化名人之一。"});
