  所有历史名人.push({id:39,_code:6039,名称:"霍去病",家族:"霍",跳:39,统帅:98,武力:95,智力:85,政治:50,魅力:90,清廉:82,野心:7,性别:0,文化:8,介绍:"西汉名将、军事家，官至大司马骠骑将军，封冠军侯。善骑射，用兵灵活，注重方略，不拘古法，勇猛果断，善于长途奔袭、闪电战和大迂回、大穿插作战。"});
  所有历史名人.push({id:40,_code:6040,名称:"孙策",家族:"孙",跳:40,统帅:77,武力:90,智力:76,政治:67,魅力:89,清廉:83,野心:40,性别:0,文化:8,介绍:"字伯符，孙坚长子，孙权长兄。东汉末年割据江东一带的军阀，汉末群雄之一，三国时期吴国的奠基者之一。《三国演义》中绰号“小霸王”。"});
  所有历史名人.push({id:41,_code:6041,名称:"庞涓",家族:"庞",跳:41,统帅:97,武力:74,智力:90,政治:96,魅力:77,清廉:67,野心:13,性别:0,文化:8,介绍:"战国初期魏国名将，孙庞斗智故事的主角之一。相传与孙膑同拜于隐士鬼谷子门下，因嫉妒孙膑的才能，恐其贤于己，因而设计把他的膝盖骨刮去。"});
  所有历史名人.push({id:42,_code:6042,名称:"典韦",家族:"典",跳:42,统帅:68,武力:98,智力:49,政治:31,魅力:69,清廉:98,野心:10,性别:0,文化:8,介绍:"陈留己吾（今河南商丘市宁陵县己吾城村）人。东汉末年曹操部将，相貌魁梧，膂力过人。本属张邈，后归曹操。曹操征讨吕布时被募为陷陈，表现英勇，被拜为校尉，宿卫曹操。建安二年（公元197年），张绣背叛曹操，典韦为保护曹操而独挡叛军，击杀多人，但最终因寡不敌众而战死。"});
  所有历史名人.push({id:43,_code:6043,名称:"王玄策",家族:"王",跳:43,统帅:88,武力:90,智力:85,政治:78,魅力:55,清廉:85,野心:23,性别:0,文化:8,介绍:"与当时高僧玄奘同乡。唐初贞观十七年至龙朔元年（643～661）间三次出使印度（一说四赴印度）的使节。曾为融州黄水县令，后升为朝散大夫。"});
  所有历史名人.push({id:44,_code:6044,名称:"刘仁轨",家族:"刘",跳:44,统帅:77,武力:90,智力:84,政治:78,魅力:56,清廉:85,野心:20,性别:0,文化:8,介绍:"字正则，唐朝名将。唐高祖、唐高宗年间，历任给事中、青州刺史。因救援新罗，在白江口之战大败日本、百济联军而名震天下。"});
  所有历史名人.push({id:45,_code:6045,名称:"苏定方",家族:"苏",跳:45,统帅:87,武力:93,智力:66,政治:40,魅力:57,清廉:70,野心:36,性别:0,文化:8,介绍:"名烈，字定方，以字行世，唐朝杰出的军事家。 破东突厥、灭西突厥、平葱岭之乱，夷百济、伐高句丽、败吐蕃。"});
  所有历史名人.push({id:46,_code:6046,名称:"狄青",家族:"狄",跳:46,统帅:87,武力:96,智力:89,政治:76,魅力:68,清廉:85,野心:15,性别:0,文化:8,介绍:"字汉臣，面有刺字，善骑射，人称“面涅将军”。勇而善谋，在宋夏战争中，他每战披头散发，戴铜面具，冲锋陷阵，立下了卓越的战功。"});
  所有历史名人.push({id:47,_code:6047,名称:"司马光",家族:"司马",跳:47,统帅:21,武力:28,智力:91,政治:88,魅力:70,清廉:88,野心:8,性别:0,文化:8,介绍:"字君实，号迂叟，世称涑水先生，北宋政治家、史学家、文学家。卒赠太师、温国公，谥文正，为人温良谦恭、刚正不阿；做事用功刻苦、勤奋。"});
  所有历史名人.push({id:48,_code:6048,名称:"岳飞",家族:"岳",跳:48,统帅:94,武力:97,智力:90,政治:65,魅力:75,清廉:86,野心:0,性别:0,文化:8,介绍:"字鹏举，中国历史上著名的军事家、战略家、民族英雄，位列南宋中兴四将之首。 他于北宋末年投军，十余年间，率领岳家军同金军进行了大小数百次战斗，“位至将相”"});
  所有历史名人.push({id:49,_code:6049,名称:"文天祥",家族:"文",跳:49,统帅:53,武力:61,智力:93,政治:95,魅力:66,清廉:92,野心:7,性别:0,文化:8,介绍:"初名云孙，字宋瑞，一字履善。宋末政治家、文学家，爱国诗人，抗元名臣，民族英雄，与陆秀夫、张世杰并称为“宋末三杰”。于五坡岭兵败被俘，宁死不降。"});
