  所有历史名人.push({id:51,_code:6051,名称:"常遇春",家族:"常",跳:51,统帅:66,武力:89,智力:52,政治:39,魅力:64,清廉:58,野心:53,性别:0,文化:8,介绍:"字伯仁，元末红巾军杰出将领，明朝开国名将。元顺帝至正十五年归附朱元璋，自请为前锋，力战克敌，尝自言能将十万众，横行天下，军中称常十万。"});
  所有历史名人.push({id:52,_code:6052,名称:"林则徐",家族:"林",跳:52,统帅:43,武力:40,智力:89,政治:96,魅力:63,清廉:96,野心:7,性别:0,文化:8,介绍:"字元抚，又字少穆、石麟，是清朝时期的政治家、思想家和诗人，两次受命钦差大臣；因其主张严禁鸦片，在中国有“民族英雄”之誉。"});
  所有历史名人.push({id:53,_code:6053,名称:"方孝孺",家族:"方",跳:53,统帅:46,武力:52,智力:90,政治:92,魅力:62,清廉:95,野心:13,性别:0,文化:8,介绍:"明朝大臣、学者、文学家、散文家、思想家，字希直，一字希古，号逊志，曾以“逊志”名其书斋，因其故里旧属缑城里，故称“缑城先生”"});
  所有历史名人.push({id:54,_code:6054,名称:"戚继光",家族:"戚",跳:54,统帅:88,武力:92,智力:88,政治:82,魅力:56,清廉:85,野心:11,性别:0,文化:8,介绍:"字元敬，号南塘，晚号孟诸，卒谥武毅。汉族，祖籍河南卫辉，后迁安徽定远，生于山东微山。明朝杰出的军事家、书法家、诗人、民族英雄。"});
