  所有历史名人.push({id:56,_code:6056,名称:"王阳明",家族:"王",跳:56,统帅:93,武力:70,智力:92,政治:88,魅力:78,清廉:86,野心:26,性别:0,文化:8,介绍:"幼名云，字伯安，别号阳明。因曾筑室于会稽山阳明洞，自号阳明子，学者称之为阳明先生，亦称王阳明。明代著名的思想家、文学家、哲学家和军事家"});
