  所有历史名人.push({id:58,_code:6058,名称:"秦桧",家族:"秦",跳:58,统帅:12,武力:44,智力:90,政治:88,魅力:31,清廉:23,野心:90,性别:0,文化:8,介绍:"字会之，南宋著名奸臣。宋徽宗政和五年登第，补密州教授，曾任太学学正。因力主对金议和，善于察言观色，颇受宋高宗赵构宠爱。"});
  所有历史名人.push({id:59,_code:6059,名称:"史可法",家族:"史",跳:59,统帅:77,武力:92,智力:88,政治:94,魅力:72,清廉:90,野心:22,性别:0,文化:8,介绍:"字宪之，又字道邻，明末抗清名将、民族英雄。早年考中进士，步入仕途。后转平各地叛乱。北京城被攻陷后，史可法拥立明福王，继续与清军作战。"});
  所有历史名人.push({id:60,_code:6060,名称:"包拯",家族:"包",跳:60,统帅:56,武力:35,智力:95,政治:95,魅力:54,清廉:96,野心:8,性别:0,文化:8,介绍:"字希仁，北宋官员，以清廉公正闻名于世。 其廉洁公正、不攀附权贵，故有“包青天”及“包公”之名。"});
