  所有历史名人.push({id:62,_code:6062,名称:"比干",家族:"比",跳:62,统帅:78,武力:54,智力:88,政治:90,魅力:63,清廉:96,野心:0,性别:0,文化:8,介绍:"子姓，商朝帝王太丁的次子，20岁就以太师高位辅佐商王帝乙，又受托孤重辅帝辛。从政40多年，主张鼓励发展农牧业生产，提倡冶炼铸造，富国强兵。"});
  所有历史名人.push({id:63,_code:6063,名称:"周公",家族:"姬",跳:63,统帅:56,武力:71,智力:96,政治:83,魅力:65,清廉:94,野心:16,性别:0,文化:8,介绍:"姓姬名旦，是周文王第四子，武王的弟弟，因其采邑在周，爵为上公，故称周公。他是西周初期杰出的政治家、军事家、思想家、教育家，被尊为“元圣”和儒学先驱。"});
  所有历史名人.push({id:64,_code:6064,名称:"孔丘",家族:"孔",跳:64,统帅:46,武力:32,智力:99,政治:94,魅力:70,清廉:92,野心:10,性别:0,文化:8,介绍:"字仲尼，春秋时期鲁国陬邑人；祖籍宋国夏邑中国著名的大思想家、大教育家、政治家。孔子开创了私人讲学的风气，是儒家学派的创始人。"});
  所有历史名人.push({id:65,_code:6065,名称:"康有为",家族:"康",跳:65,统帅:76,武力:21,智力:89,政治:78,魅力:75,清廉:88,野心:24,性别:0,文化:8,介绍:"原名祖诒，字广厦。 康有为是中国近代史上政治家、教育家和文学艺术家，资产阶级改良主义的代表人物，在倡导维新运动时，体现了历史前进的方向。"});
  所有历史名人.push({id:66,_code:6066,名称:"李耳",家族:"李",跳:66,统帅:66,武力:44,智力:90,政治:79,魅力:75,清廉:88,野心:6,性别:0,文化:8,介绍:"姓李名耳，字聃，一字或曰谥伯阳。主张无为而治，其学说对中国哲学发展具有深刻影响。在道教中，老子被尊为道教始祖。老子与后世的庄子并称老庄。"});
  所有历史名人.push({id:67,_code:6067,名称:"孙膑",家族:"孙",跳:67,统帅:98,武力:67,智力:90,政治:84,魅力:34,清廉:81,野心:26,性别:0,文化:8,介绍:"中国战国初期军事家，兵家代表人物。 辅佐齐国大将田忌两次击败庞涓 取得桂陵、马陵之战的胜利，并著有《孙膑兵法》"});
  所有历史名人.push({id:68,_code:6068,名称:"韩非",家族:"韩",跳:68,统帅:78,武力:33,智力:91,政治:88,魅力:56,清廉:86,野心:23,性别:0,文化:8,介绍:"战国末期著名思想家，法家代表人物。尊称韩非子或韩子。韩王（战国末期韩国君主）之子，荀子的学生。 代表作品：《韩非子》并主张以法治国。"});
  所有历史名人.push({id:69,_code:6069,名称:"墨翟",家族:"墨",跳:69,统帅:72,武力:56,智力:93,政治:86,魅力:67,清廉:82,野心:34,性别:0,文化:8,介绍:"东周春秋末期战国初期宋国人 ，墨子是宋国贵族目夷的后代，生前担任宋国大夫。他是墨家学派的创始人，也是战国时期著名的思想家、教育家、科学家、军事家。"});
  所有历史名人.push({id:70,_code:6070,名称:"白起",家族:"白",跳:70,统帅:90,武力:90,智力:84,政治:73,魅力:78,清廉:68,野心:36,性别:0,文化:8,介绍:"又称公孙起，中国古代著名的将领、军事家。白起为秦昭王征战六国，为秦国统一中国做出了巨大的贡献。 与廉颇、李牧、王翦并称为战国四大名将，位列战国四大名将之首。"});
  所有历史名人.push({id:71,_code:6071,名称:"王翦",家族:"王",跳:71,统帅:90,武力:91,智力:88,政治:69,魅力:78,清廉:82,野心:37,性别:0,文化:8,介绍:"战国时期秦国名将，秦代杰出的军事家，主要战绩有破赵国都城邯郸，消灭燕、赵；以秦国绝大部分兵力消灭楚国。与其子王贲一并成为秦始皇兼灭六国的最大功臣。"});
  所有历史名人.push({id:72,_code:6072,名称:"廉颇",家族:"廉",跳:72,统帅:90,武力:95,智力:79,政治:64,魅力:67,清廉:90,野心:8,性别:0,文化:8,介绍:"嬴姓，廉氏，名颇，战国末期赵国的名将，与白起、王翦、李牧并称“战国四大名将”。曾率兵讨伐齐国，夺取了晋阳，赵王封他为上卿。廉颇因为勇猛果敢而闻名于诸侯各国。"});
  所有历史名人.push({id:73,_code:6073,名称:"李牧",家族:"李",跳:73,统帅:90,武力:91,智力:90,政治:65,魅力:76,清廉:86,野心:14,性别:0,文化:8,介绍:"嬴姓，李氏，名牧，战国时期的赵国军事家，曾败匈奴、灭襜褴、破东胡，连却秦军。 与白起、王翦、廉颇并称“战国四大名将”。"});
  所有历史名人.push({id:74,_code:6074,名称:"吕不韦",家族:"吕",跳:74,统帅:78,武力:14,智力:89,政治:93,魅力:80,清廉:29,野心:84,性别:0,文化:8,介绍:"姜姓，吕氏，名不韦，战国末年著名商人、政治家、思想家，官至秦国丞相。 扶立秦庄襄王，任秦国相邦，灭东周国，主持编纂《吕氏春秋》"});
  所有历史名人.push({id:75,_code:6075,名称:"蒙恬",家族:"蒙",跳:75,统帅:90,武力:92,智力:75,政治:65,魅力:73,清廉:78,野心:29,性别:0,文化:8,介绍:"姬姓，蒙氏，名恬，秦朝著名将领。曾 收复河套地区，开发宁夏，修筑长城，防御匈奴，改良毛笔、改良古筝。"});
  所有历史名人.push({id:76,_code:6076,名称:"李广",家族:"李",跳:76,统帅:90,武力:90,智力:68,政治:45,魅力:72,清廉:74,野心:34,性别:0,文化:8,介绍:"中国西汉时期的名将。 参与平定七国之乱，率领汉军与匈奴作战。匈奴畏服，称之为飞将军，数年不敢来犯。"});
  所有历史名人.push({id:77,_code:6077,名称:"焦赞",家族:"焦",跳:77,统帅:95,武力:93,智力:71,政治:34,魅力:80,清廉:87,野心:32,性别:0,文化:8,介绍:"北宋后期富弼部下，也是抵抗辽军的北军将领，焦赞墓在今天河北雄县。在杨家将演义中，焦赞是追随杨延昭的猛将，同孟良并称，抗辽有战功，久镇瓦桥关（河北雄县一带），也就是镇雄州（雄县），名望颇高。他和孟良等是杨家将的左右臂，是一位名闻河北的抗辽勇将。"});
  所有历史名人.push({id:78,_code:6078,名称:"田单",家族:"田",跳:78,统帅:33,武力:68,智力:91,政治:88,魅力:65,清廉:78,野心:44,性别:0,文化:8,介绍:"妫姓，田氏，名单，齐国危亡之际，田单坚守即墨，以火牛阵击破燕军，收复七十余城，因功被任为相国，并得到安平君的封号。"});
  所有历史名人.push({id:79,_code:6079,名称:"刘备",家族:"刘",跳:79,统帅:64,武力:78,智力:77,政治:80,魅力:95,清廉:98,野心:12,性别:0,文化:8,介绍:"字玄德，西汉中山靖王刘胜的后代，三国时期蜀汉开国皇帝，政治家，史家又称他为先主。 公元221年，刘备在成都称帝，国号汉，年号章武，史称蜀或蜀汉。"});
  所有历史名人.push({id:80,_code:6080,名称:"曹操",家族:"曹",跳:80,统帅:90,武力:77,智力:95,政治:98,魅力:80,清廉:90,野心:90,性别:0,文化:8,介绍:"孟德，一名吉利，小字阿瞒，东汉末年杰出的政治家、军事家、文学家、书法家。三国中曹魏政权的缔造者， 奠定了曹魏立国的基础。"});
  所有历史名人.push({id:81,_code:6081,名称:"张辽",家族:"张",跳:81,统帅:90,武力:96,智力:88,政治:56,魅力:72,清廉:89,野心:15,性别:0,文化:8,介绍:"字文远，三国时期曹魏著名将领。随曹操征讨，战功累累。后世将其与乐进、于禁、张郃、徐晃并称为曹魏“五子良将”。"});
  所有历史名人.push({id:82,_code:6082,名称:"司马懿",家族:"司马",跳:82,统帅:94,武力:56,智力:96,政治:98,魅力:82,清廉:80,野心:95,性别:0,文化:8,介绍:"字仲达，三国时期魏国杰出的政治家、军事家，西晋王朝的奠基人。对屯田、水利等农耕经济发展有重要贡献。"});
  所有历史名人.push({id:83,_code:6083,名称:"吕布",家族:"吕",跳:83,统帅:99,武力:98,智力:54,政治:21,魅力:80,清廉:23,野心:86,性别:0,文化:8,介绍:"字奉先，东汉末年名将，汉末群雄之一。由于《三国演义》及各种民间艺术的演绎，吕布向来是以“三国第一猛将”的形象存在于人们的心目之中。"});
  所有历史名人.push({id:84,_code:6084,名称:"关羽",家族:"关",跳:84,统帅:99,武力:98,智力:89,政治:54,魅力:74,清廉:79,野心:17,性别:0,文化:8,介绍:"字云长，东汉末年名将。早期跟随刘备辗转各地，曾被曹操生擒，于白马坡斩杀袁绍大将颜良，与张飞一同被称为万人敌。"});
  所有历史名人.push({id:85,_code:6085,名称:"张飞",家族:"张",跳:85,统帅:78,武力:96,智力:30,政治:12,魅力:41,清廉:49,野心:16,性别:0,文化:8,介绍:"字益德，三国时期蜀汉名将。在中国传统文化中，张飞以其勇猛、鲁莽、嫉恶如仇而著称，对蜀汉贡献极大。"});
  所有历史名人.push({id:86,_code:6086,名称:"周瑜",家族:"周",跳:86,统帅:99,武力:75,智力:95,政治:98,魅力:95,清廉:80,野心:23,性别:0,文化:8,介绍:"字公瑾，汉末名将，长壮有姿貌、精音律，江东有“曲有误，周郎顾”之语。曾率江东孙氏集团军队与刘备军队联合，赤壁之战大败曹军，由此奠定了三分天下的基础。"});
  所有历史名人.push({id:87,_code:6087,名称:"秦叔宝",家族:"秦",跳:87,统帅:90,武力:90,智力:69,政治:45,魅力:54,清廉:82,野心:24,性别:0,文化:8,介绍:"隋末唐初名将，因勇武过人而远近闻名。是一个能在万众之取敌将首级的勇将。"});
  所有历史名人.push({id:88,_code:6088,名称:"尉迟恭",家族:"尉迟",跳:88,统帅:90,武力:91,智力:52,政治:36,魅力:76,清廉:61,野心:36,性别:0,文化:8,介绍:"唐初大将，有远见的卓识，敬德纯朴忠厚，从无二心，正因如此，后人才将他做为门神，画图流传至今。"});
  所有历史名人.push({id:89,_code:6089,名称:"李密",家族:"李",跳:89,统帅:78,武力:78,智力:90,政治:90,魅力:72,清廉:86,野心:40,性别:0,文化:8,介绍:"字令伯，一名虔，幼年丧父，母何氏改嫁，由祖母抚养成人。后李密以对祖母孝敬甚笃而名扬于乡里。师事著名学者谯周，博览五经，著有《陈情表》。"});
  所有历史名人.push({id:90,_code:6090,名称:"韩愈",家族:"韩",跳:90,统帅:43,武力:67,智力:90,政治:90,魅力:71,清廉:94,野心:27,性别:0,文化:8,介绍:"字退之，唐代杰出的文学家、哲学家、思想家，他提出的文道合一、气盛言宜、务去陈言、文从字顺等散文的写作理论，对后人很有指导意义。被后人尊为“唐宋八大家”之首。"});
  所有历史名人.push({id:91,_code:6091,名称:"庞德",家族:"庞",跳:91,统帅:80,武力:89,智力:75,政治:55,魅力:78,清廉:85,野心:29,性别:0,文化:8,介绍:"字令明，约在初平年间，投奔马腾帐下，在平定羌民的征伐中屡立战功。建安年间，庞德跟随马超征战平阳，抵御袁将郭援、高干，在马上亲斩郭援首级。张白骑在弘农反叛时，庞德也参与战斗。每次出征常冲锋陷阵，勇冠凉州三军。后几经辗转，随张鲁归降于曹操麾下，被授官立义将军，封关内亭侯，食邑三百户。"});
  所有历史名人.push({id:92,_code:6092,名称:"郑成功",家族:"郑",跳:92,统帅:88,武力:90,智力:74,政治:83,魅力:79,清廉:92,野心:21,性别:0,文化:8,介绍:"本名森，又名福松，字明俨、大木。1661年率军横渡台湾海峡，翌年击败荷兰东印度公司在台湾大员的驻军，收复台湾，开启郑氏在台湾的统治。"});
  所有历史名人.push({id:93,_code:6093,名称:"袁崇焕",家族:"袁",跳:93,统帅:88,武力:90,智力:78,政治:76,魅力:56,清廉:88,野心:29,性别:0,文化:8,介绍:"字元素，通过自荐的方式在边关任职，得到孙承宗的器重镇守宁远。后魏忠贤余党以“擅杀岛帅”、“与清廷议和”等罪名弹劾袁崇焕，最终被朱由检以通敌叛国罪处以凌迟。"});
  所有历史名人.push({id:94,_code:6094,名称:"宇文拓",家族:"宇文",跳:94,统帅:79,武力:90,智力:82,政治:44,魅力:90,清廉:80,野心:20,性别:0,文化:8,介绍:"宇文拓，是国产单机游戏《轩辕剑叁外传：天之痕》重要角色。为十大神器昆仑镜转世。"});
  所有历史名人.push({id:95,_code:6095,名称:"太史慈",家族:"太史",跳:95,统帅:88,武力:91,智力:71,政治:45,魅力:75,清廉:80,野心:33,性别:0,文化:8,介绍:"太史慈（166年－206年），字子义，东汉末年武将，官至建昌都尉。弓马熟练，箭法精良。原为刘繇部下，后被孙策收降，自此太史慈为孙氏大将，助其扫荡江东。孙权统事后，因太史慈能制刘磐，便将管理南方的要务委托给他。建安十一年（206年）太史慈逝世，年四十一岁。"});
  所有历史名人.push({id:96,_code:6096,名称:"和绅",家族:"钮祜禄",跳:96,统帅:12,武力:47,智力:90,政治:99,魅力:95,清廉:1,野心:70,性别:0,文化:18,介绍:"钮祜禄氏，原名善保，字致斋，自号嘉乐堂、十笏园、绿野亭主人，利用职务之便，结党营私，聚敛钱财，打击政敌。"});
  所有历史名人.push({id:97,_code:6097,名称:"庞籍",家族:"庞",跳:97,统帅:10,武力:20,智力:95,政治:96,魅力:55,清廉:92,野心:10,性别:0,文化:8,介绍:"庞籍（988年—1063年），字醇之，单州成武（今山东成武县）人，大中祥符八年（1015年）进士及第后，任黄州司理参军，深得知州夏竦的赞许，认为庞籍极具宰相之才，他日必成大器。不久庞籍又先后升任为江州军事判官，开封府司法参军，刑部详复官，群牧判官，大理寺丞，殿中侍御史，累迁至枢密副使、枢密使，太子太保等，封颖国公。 庞籍还是韩琦、范仲淹等人的好友，司马光、狄青等人的恩师。"});
  所有历史名人.push({id:98,_code:6098,名称:"张居正",家族:"张",跳:98,统帅:34,武力:47,智力:95,政治:92,魅力:66,清廉:88,野心:70,性别:0,文化:8,介绍:"字叔大，号太岳，汉族，幼名张白圭。，时人又称张江陵。明朝中后期政治家、改革家，万历时期的内阁首辅，辅佐万历皇帝朱翊钧开创了“万历新政”。"});
  所有历史名人.push({id:99,_code:6099,名称:"海瑞",家族:"海",跳:99,统帅:10,武力:20,智力:85,政治:96,魅力:55,清廉:99,野心:10,性别:0,文化:8,介绍:"字汝贤，号刚峰，明朝著名清官。他打击豪强，疏浚河道，修筑水利工程，力主严惩贪官污吏，禁止循私受贿，强令贪官污吏退田还民，遂有“海青天”之誉。"});
  所有历史名人.push({id:100,_code:6100,名称:"高湛",家族:"高",跳:100,统帅:34,武力:70,智力:84,政治:88,魅力:56,清廉:75,野心:50,性别:0,文化:8,介绍:"字子澄，东魏将领，能诗文。累官镇军将军，南荆州刺史。除大都督，行广州事。东魏孝静帝元象元年去世，终年43岁。曾著《养生论》，亦有诗作传世。"});
  所有历史名人.push({id:101,_code:6101,名称:"杨复",家族:"杨",跳:101,统帅:78,武力:90,智力:80,政治:82,魅力:57,清廉:80,野心:10,性别:0,文化:8,介绍:"民国藏书家。字剑星，一作见心。浙江杭州人。杨文莹之子，官中书舍人。"});
  所有历史名人.push({id:102,_code:6102,名称:"王元宝",家族:"王",跳:102,统帅:2,武力:59,智力:59,政治:68,魅力:58,清廉:59,野心:59,性别:0,文化:8,介绍:"唐朝开元间人，富可敌国，靠贩运琉璃发家。王元宝的许多生活习惯如正月初五拜财神，吃发菜等等对于民间民风民俗有深刻的影响，流传至今。"});
  所有历史名人.push({id:103,_code:6103,名称:"乐毅",家族:"乐",跳:103,统帅:78,武力:50,智力:92,政治:93,魅力:60,清廉:50,野心:50,性别:0,文化:8,介绍:"子姓，乐氏，名毅，字永霸。战国后期杰出的军事家，魏将乐羊后裔，拜燕上将军，受封昌国君，辅佐燕昭王振兴燕国。"});
  所有历史名人.push({id:104,_code:6104,名称:"范增",家族:"范",跳:104,统帅:88,武力:55,智力:95,政治:90,魅力:61,清廉:90,野心:20,性别:0,文化:8,介绍:"秦末农民战争中为项羽主要谋士，被项羽尊为“亚父”。后在鸿门宴上多次示意项羽杀刘邦，又使项庄舞剑，意欲借机行刺，终未获成功。"});
  所有历史名人.push({id:105,_code:6105,名称:"纪晓岚",家族:"纪",跳:105,统帅:27,武力:32,智力:92,政治:93,魅力:62,清廉:85,野心:24,性别:0,文化:8,介绍:"又字春帆，晚号石云，又号观弈道人、孤石老人、河间才子，谥号文达，在文学作品、通俗评论中，常被称为纪晓岚。"});
  所有历史名人.push({id:106,_code:6106,名称:"李逵",家族:"李",跳:106,统帅:28,武力:92,智力:1,政治:1,魅力:12,清廉:70,野心:60,性别:0,文化:8,介绍:"是中国古典小说《水浒传》中的重要人物，也是元杂剧“水浒戏”中最重要的角色之一。生得粗壮黝黑，绰号“黑旋风”。"});
  所有历史名人.push({id:107,_code:6107,名称:"李元霸",家族:"李",跳:107,统帅:78,武力:92,智力:60,政治:75,魅力:70,清廉:70,野心:60,性别:0,文化:8,介绍:"是清代小说《说唐》虚构的人物，其历史原型为李玄霸，字大德，唐高祖李渊第三子。"});
  所有历史名人.push({id:108,_code:6108,名称:"裴元庆",家族:"裴",跳:108,统帅:77,武力:89,智力:60,政治:54,魅力:56,清廉:70,野心:60,性别:0,文化:8,介绍:"古典小说《说唐全传》、评书《兴唐传》《隋唐演义传》等书中人物。隋朝第三条好汉，裴仁基之子，手持一对银锤，年少却不失骁勇。"});
  所有历史名人.push({id:109,_code:6109,名称:"宇文成都",家族:"宇文",跳:109,统帅:78,武力:92,智力:75,政治:80,魅力:78,清廉:70,野心:60,性别:0,文化:8,介绍:"小说《说唐》《忠义响马传》《兴唐传》中人物，隋朝大将，为大隋丞相宇文化及之子。被隋炀帝封为无敌大将军。号称天宝大将，是大隋王朝的支柱。"});
  所有历史名人.push({id:110,_code:6110,名称:"罗成",家族:"罗",跳:110,统帅:85,武力:90,智力:60,政治:48,魅力:80,清廉:70,野心:60,性别:0,文化:8,介绍:"《隋史遗文》、《隋唐演义》、《大唐秦王词话》、《说唐》中的人物，《说唐》中是第七条好汉，因皮肤白皙面容俊俏但却不苟言笑，人送绰号“冷面寒枪俏罗成”"});
  所有历史名人.push({id:111,_code:6111,名称:"单雄信",家族:"单",跳:111,统帅:66,武力:89,智力:60,政治:48,魅力:67,清廉:70,野心:60,性别:0,文化:8,介绍:"曹州济阴人。勇武过人，与徐世勣关系友好，誓同生死。隋末与徐世勣一起加入翟让的瓦岗义军反隋。"});
