  所有历史名人.push({id:177,_code:6177,名称:"辛宪英",家族:"辛",跳:177,统帅:35,武力:11,智力:93,政治:93,魅力:80,清廉:99,野心:30,性别:1,文化:8,介绍:"魏晋时期才女，生平见载于《晋书·卷九十六·列女传·羊耽妻辛氏传》。其外孙夏侯湛亦为其撰写传记《羊太常辛夫人传》，裴松之注《三国志》时曾于《辛毗传》中加以引用。"});
  所有历史名人.push({id:178,_code:6178,名称:"孙尚香",家族:"孙",跳:178,统帅:32,武力:80,智力:67,政治:67,魅力:90,清廉:67,野心:30,性别:1,文化:8,介绍:"吴郡富春（今浙江富阳）人，东汉末年讨虏将军孙权之妹，左将军刘备夫人。"});
