  所有历史名人.push({id:180,_code:6180,名称:"关银屏",家族:"关",跳:180,统帅:10,武力:80,智力:71,政治:71,魅力:80,清廉:67,野心:30,性别:1,文化:8,介绍:"东汉末年名将关羽之女，又称关凤，是三国时期刘备手下名将关羽之女在民间传说中的名字。该名不见史书记载，仅在民间传说中出现。"});
  所有历史名人.push({id:181,_code:6181,名称:"蒋琬",家族:"蒋",跳:181,统帅:82,武力:53,智力:91,政治:93,魅力:78,清廉:91,野心:33,性别:0,文化:8,介绍:"蒋琬，字公琰。零陵湘乡人。诸葛亮逝世后，蒋琬执政。拜尚书令，又加行都护，假节，领益州刺史，再迁大将军，录尚书事，封安阳亭侯，并被受命开府，后加大司马，总揽蜀汉军朝。"});
  所有历史名人.push({id:182,_code:6182,名称:"吕尚",家族:"姜",跳:182,统帅:97,武力:92,智力:98,政治:92,魅力:84,清廉:88,野心:50,性别:0,文化:8,介绍:"先后辅佐了六位周王，因是齐国始祖而称“太公望”，俗称姜太公。西周初年，被周文王封为“太师”，被尊为“师尚父”，辅佐文王，与谋“翦商”。后辅佐周武王灭商。因功封于齐，成为周代齐国的始祖。"});
  所有历史名人.push({id:183,_code:6183,名称:"费祎",家族:"费",跳:183,统帅:82,武力:32,智力:80,政治:92,魅力:54,清廉:88,野心:30,性别:0,文化:8,介绍:"费祎，字文伟，荆州江夏鄳县人，三国时蜀汉名臣，深得诸葛亮所器重，曾出使东吴，孙权、诸葛恪、羊茞等人以辞锋论难，而费祎据理以答，辞义兼至，始终不为所屈。诸葛亮死后，初为后军师，再为尚书令，再迁大将军，执行休养生息的政策，为蜀汉的发展尽心竭力。"});
  所有历史名人.push({id:184,_code:6184,名称:"董允",家族:"董",跳:184,统帅:67,武力:22,智力:80,政治:92,魅力:54,清廉:88,野心:40,性别:0,文化:8,介绍:"董允，字休昭，泸县嘉明镇人，三国时期蜀汉重臣，掌军中郎将董和之子。为人正直、是非分明，处理事务为防制为主，经常敢于匡正刘禅的不当行为，后主宠信宦佞黄皓时，亦因董允每每厉色匡谏得以使其收敛。"});
  所有历史名人.push({id:185,_code:6185,名称:"张世杰",家族:"张",跳:185,统帅:92,武力:64,智力:91,政治:82,魅力:87,清廉:88,野心:5,性别:0,文化:8,介绍:"张世杰，涿州范阳人。宋末抗元名将，民族英雄。太傅，枢密副使，封越国公。先后拥立南宋二帝，誓不降元，最终兵败崖山海战，因飓风毁船，溺死于平章山下。"});
  所有历史名人.push({id:186,_code:6186,名称:"陆秀夫",家族:"陆",跳:186,统帅:51,武力:43,智力:93,政治:93,魅力:84,清廉:88,野心:1,性别:0,文化:8,介绍:"陆秀夫，字君实，一字宴翁，别号东江，楚州盐城长建里人。南宋左丞相，抗元名臣。崖山海战兵败，南宋灭国，陆秀夫背着少帝赵昺，投海自尽，许多忠臣追随其后，十万军民跳海殉国。"});
  所有历史名人.push({id:187,_code:6187,名称:"王粲",家族:"王",跳:187,统帅:12,武力:11,智力:89,政治:72,魅力:64,清廉:77,野心:12,性别:0,文化:8,介绍:"王粲字仲宣。东汉末文学家。山阳高平人，“建安七子”之一，年少即有才名，曾任曹魏侍中，从曹操南征孙权时于北还途中病卒，终年四十一岁。王粲善属文，其诗赋为建安七子之冠。"});
  所有历史名人.push({id:188,_code:6188,名称:"徐干",家族:"徐",跳:188,统帅:11,武力:9,智力:90,政治:54,魅力:84,清廉:91,野心:5,性别:0,文化:8,介绍:"徐干，字伟长，北海人，建安七子之一。少年勤学，潜心典籍。汉灵帝末，世族子弟结党权门，竞相追逐荣名，徐干闭门自守，穷处陋巷，不随流俗。建安初，曹操召授司空军师祭酒掾属，又转五官将文学。数年后，因病辞职，曹操特加旌命表彰。"});
  所有历史名人.push({id:189,_code:6189,名称:"阮瑀",家族:"阮",跳:189,统帅:11,武力:12,智力:88,政治:80,魅力:84,清廉:88,野心:13,性别:0,文化:8,介绍:"阮瑀，字元瑜，陈留尉氏人，建安七子之一。擅作章表书记，当时军国书檄文字，多为阮瑀与陈琳所拟。后徙为丞相仓曹掾属。诗歌语言朴素，往往能反映出一般的社会问题。诗有《驾出北郭门行》。阮瑀的音乐修养颇高，儿子阮籍，孙子阮咸皆是当时名人，位列“竹林七贤”，妙于音律。"});
  所有历史名人.push({id:190,_code:6190,名称:"应玚",家族:"应",跳:190,统帅:11,武力:12,智力:84,政治:32,魅力:84,清廉:88,野心:10,性别:0,文化:8,介绍:"应玚，字德琏，东汉汝南南顿县人，建安七子之一。擅长作赋，代表性诗作《侍五官中郎将建章台集诗》。初被魏王曹操任命为丞相掾属，后转为平原侯庶子。曹丕任五官中郎将时，玚为将军府文学，著文赋数十篇。诗歌亦见长。"});
  所有历史名人.push({id:191,_code:6191,名称:"孔融",家族:"孔",跳:191,统帅:32,武力:43,智力:88,政治:87,魅力:77,清廉:81,野心:26,性别:0,文化:8,介绍:"孔融，字文举。鲁国人。东汉末年文学家，“建安七子”之一，家学渊源，是孔子的二十世孙，太山都尉孔宙之子。"});
  所有历史名人.push({id:192,_code:6192,名称:"陈琳",家族:"陈",跳:192,统帅:11,武力:12,智力:84,政治:62,魅力:84,清廉:78,野心:20,性别:0,文化:8,介绍:"陈琳，字孔璋，广陵射阳人。东汉末年著名文学家，“建安七子”之一。"});
  所有历史名人.push({id:193,_code:6193,名称:"刘桢",家族:"刘",跳:193,统帅:11,武力:12,智力:84,政治:52,魅力:77,清廉:67,野心:45,性别:0,文化:8,介绍:"刘桢，东汉名士，建安七子之一。字公干，东平。博学有才，与魏文帝友善。后以不敬罪被刑，刑后署吏。所作五言诗，风格遒劲，语言质朴，重名于世，今有《刘公干集》。"});
  所有历史名人.push({id:194,_code:6194,名称:"邓禹",家族:"邓",跳:194,统帅:89,武力:72,智力:91,政治:53,魅力:78,清廉:87,野心:23,性别:0,文化:8,介绍:"邓禹，字仲华，南阳新野人，东汉初年军事家，云台二十八将第一位。邓禹年轻时曾在长安学习，与刘秀交好。更始元年，刘秀巡行河北，邓禹前往追随，提出“延揽英雄，务悦民心，立高祖之业，救万民之命”的方略，被刘秀“恃之以为萧何”。"});
  所有历史名人.push({id:195,_code:6195,名称:"吴汉",家族:"吴",跳:195,统帅:91,武力:87,智力:81,政治:72,魅力:67,清廉:81,野心:23,性别:0,文化:8,介绍:"吴汉，字子颜，汉族，南阳宛县人，东汉开国名将、军事家，云台二十八将第二位。吴汉曾任新朝宛县亭长，后在渔阳郡贩马为业。更始元年，被任命为安乐令。后归顺刘秀，封偏将军、建策侯。此后，吴汉斩杀苗曾、谢躬，平定铜马、青犊等农民军，协助刘秀建立东汉。"});
  所有历史名人.push({id:196,_code:6196,名称:"贾复",家族:"贾",跳:196,统帅:89,武力:93,智力:89,政治:87,魅力:79,清廉:77,野心:23,性别:0,文化:8,介绍:"贾复，字君文，汉族，南阳冠军人，东汉名将，云台二十八将第三位。贾复儒生出身，新朝末年聚众加入绿林军。归顺刘秀后，随其击信都、攻邯鄣、战真定、破邺城、平定郾城、召陵、新息等地，战功赫赫。"});
  所有历史名人.push({id:197,_code:6197,名称:"耿弇",家族:"耿",跳:197,统帅:93,武力:83,智力:81,政治:62,魅力:78,清廉:77,野心:34,性别:0,文化:8,介绍:"耿弇，字伯昭，汉族，挟风茂陵人，东汉开国名将、军事家，云台二十八将第四位。耿弇自幼喜好兵事，后劝父投奔刘秀，被任命为偏将军，跟随刘秀平定河北。刘秀称帝后，耿弇封建威大将军、好畤侯。"});
  所有历史名人.push({id:198,_code:6198,名称:"寇恂",家族:"寇",跳:198,统帅:81,武力:89,智力:82,政治:82,魅力:83,清廉:82,野心:14,性别:0,文化:8,介绍:"寇恂，云台二十八将第五位。出身世家大族，原是新朝上谷功曹，后与耿弇一起投奔刘秀，被任命为偏将军、承义侯。此后，寇恂镇守河内，治理颍川、汝南，协助刘秀建立东汉。刘秀称帝后，寇恂任执金吾，封雍奴侯。建武十二年病逝，谥号威侯。"});
  所有历史名人.push({id:199,_code:6199,名称:"岑彭",家族:"岑",跳:199,统帅:89,武力:95,智力:62,政治:51,魅力:51,清廉:76,野心:43,性别:0,文化:8,介绍:"岑彭，字君然，东汉初年军事家，汉族，南阳棘阳人，云台二十八将第六位。"});
  所有历史名人.push({id:200,_code:6200,名称:"冯异",家族:"冯",跳:200,统帅:87,武力:72,智力:89,政治:71,魅力:54,清廉:86,野心:35,性别:0,文化:8,介绍:"冯异，字公孙，汉族，颍川父城人，东汉开国名将、军事家，云台二十八将第七位。冯异原为新朝颍川郡掾，后归顺刘秀，随之征战，大破赤眉、平定关中。协助刘秀建立东汉。刘秀称帝后，冯异被封为征西大将军、阳夏侯。建武十年病逝于在军中，谥曰节侯。"});
  所有历史名人.push({id:201,_code:6201,名称:"朱佑",家族:"朱",跳:201,统帅:81,武力:89,智力:76,政治:72,魅力:73,清廉:89,野心:11,性别:0,文化:8,介绍:"朱佑，字仲先，汉族，南阳郡宛人。朱佑自幼与刘秀相识，关系极好，自刘秀起兵就一直跟随左右，虽曾被俘没有影响刘秀对他的信任，历任护军、偏将军、建义大将军，先后封为安阳侯、堵阳侯、鬲侯。"});
  所有历史名人.push({id:202,_code:6202,名称:"祭遵",家族:"祭",跳:202,统帅:83,武力:81,智力:79,政治:80,魅力:79,清廉:81,野心:15,性别:0,文化:8,介绍:"祭遵，字弟孙，汉族，颍川颍阳人。祭遵少爱读书，后为县吏，投奔刘秀后，平定渔阳，讨伐陇蜀，协助刘秀建立东汉，是东汉中兴名将，“云台二十八将”中排名第九。刘秀称帝后，任征虏将军，封颖阳侯。"});
  所有历史名人.push({id:203,_code:6203,名称:"景丹",家族:"景",跳:203,统帅:81,武力:86,智力:79,政治:62,魅力:83,清廉:76,野心:46,性别:0,文化:8,介绍:"景丹，字孙卿，冯翊栎阳人，东汉开国名将，云台二十八将第十位。景丹在王莽政权时期担任过固德侯国的相国、朔调连率副贰，更始政权建立之后被任命为上谷郡长史。"});
  所有历史名人.push({id:204,_code:6204,名称:"盖延",家族:"盖",跳:204,统帅:71,武力:93,智力:62,政治:51,魅力:77,清廉:77,野心:46,性别:0,文化:8,介绍:"盖延，字巨卿，东汉初年将领。汉族，渔阳要阳人。盖延力大能挽硬弓，以勇力闻名边疆，原为彭宠部下，后与吴汉共投刘秀，久经战阵，协助刘秀建立东汉，是东汉中兴名将，“云台二十八将”中排名第十一。"});
  所有历史名人.push({id:205,_code:6205,名称:"铫期",家族:"铫",跳:205,统帅:83,武力:81,智力:45,政治:56,魅力:54,清廉:81,野心:6,性别:0,文化:8,介绍:"铫期，字次况，汉族，颍川郡郏县人。东汉大将，云台二十八将第十二位。铫期在冯异的举荐下投到刘秀门下，成为刘秀落难洛阳之时少数心腹之一，后来随刘秀平定河北，消灭了王郎及铜马、青犊等流民军，并长期镇守魏郡，为建立东汉立下赫赫功劳。"});
  所有历史名人.push({id:206,_code:6206,名称:"耿纯",家族:"耿",跳:206,统帅:88,武力:71,智力:81,政治:79,魅力:67,清廉:67,野心:34,性别:0,文化:8,介绍:"耿纯，字伯山。汉族，钜鹿宋子傅家庄人。耿氏为巨鹿大姓，耿纯曾先后担任过王莽、刘玄政权的官员，后投奔刘秀，参与消灭王郎、刘永等割据势力，镇压铜马、赤眉等农民军，协助刘秀建立东汉，是东汉中兴名将，“云台二十八将”中排名第十三。"});
  所有历史名人.push({id:207,_code:6207,名称:"臧宫",家族:"臧",跳:207,统帅:81,武力:83,智力:63,政治:58,魅力:43,清廉:67,野心:28,性别:0,文化:8,介绍:"臧宫，字君翁，颍川郏县人，东汉中兴名将、云台二十八将之一。臧宫原为小吏，参加农民军后得以追随刘秀，南征北战，屡立战功，是平定蜀地的主将之一。先后受封为成安侯、期思侯、酂侯、朗陵侯。永元元年，臧宫去世，谥号愍侯。"});
  所有历史名人.push({id:208,_code:6208,名称:"马武",家族:"马",跳:208,统帅:69,武力:94,智力:61,政治:60,魅力:57,清廉:70,野心:34,性别:0,文化:8,介绍:"马武，字子张，东汉初年将领。南阳湖阳人。马武少年时为避仇家，客居江夏。后入绿林军，为新市兵将领。更始二年归顺刘秀，随其南征北战、平定四方。协助刘秀建立东汉，是东汉中兴名将，“云台二十八将”中排名第十五。刘秀称帝后，任捕虏将军，封杨虚侯。"});
  所有历史名人.push({id:209,_code:6209,名称:"刘隆",家族:"刘",跳:209,统帅:72,武力:83,智力:79,政治:80,魅力:89,清廉:81,野心:30,性别:0,文化:8,介绍:"刘隆，字元伯，汉族，南阳人，汉朝安众侯的宗室，因父亲参加反王莽活动，被灭族，刘隆仅以身免。 长大后参加反对王莽政权的活动，后投奔刘秀，久经战阵，协助刘秀建立东汉，是东汉中兴名将，“云台二十八将”中排名第十六。"});
  所有历史名人.push({id:210,_code:6210,名称:"马成",家族:"马",跳:210,统帅:85,武力:77,智力:73,政治:72,魅力:61,清廉:70,野心:40,性别:0,文化:8,介绍:"马成，字君迁。汉族，南阳郡棘阳人。马成原是王莽政权的县吏，投奔刘秀后，久经战阵，参与 消灭王郎、刘永、李宪、隗嚣、公孙述等割据势力，协助刘秀建立东汉，是东汉中兴名将，“云台二十八将”中排名第十七。"});
  所有历史名人.push({id:211,_code:6211,名称:"王梁",家族:"王",跳:211,统帅:70,武力:83,智力:69,政治:56,魅力:61,清廉:70,野心:35,性别:0,文化:8,介绍:"王梁，字君严，渔阳要阳人。东汉云台二十八将第十八位。原为渔阳郡狐奴令，后投奔刘秀，被拜为偏将军。刘秀占领邯郸后，封王梁为关内侯。"});
  所有历史名人.push({id:212,_code:6212,名称:"陈俊",家族:"陈",跳:212,统帅:79,武力:82,智力:81,政治:66,魅力:73,清廉:71,野心:28,性别:0,文化:8,介绍:"陈俊，字子昭，南阳郡西鄂县人。东汉大将，云台二十八将之一。一开始跟随刘嘉，后经刘嘉推荐投奔刘秀。参加了剿灭河北农民军、平定关东刘永、董宪、张步等割据势力的作战。历任强弩将军、强弩大将军、太山太守、琅邪太守。"});
  所有历史名人.push({id:213,_code:6213,名称:"杜茂",家族:"杜",跳:213,统帅:81,武力:77,智力:71,政治:69,魅力:67,清廉:81,野心:23,性别:0,文化:8,介绍:"杜茂，字诸公，汉族，南阳郡冠军县人，在刘秀平定河北时投奔，随刘秀平定河北，剿灭五校农民军，消灭刘永余部，辅佐刘秀建立东汉王朝。在云台二十八将排第20位。"});
  所有历史名人.push({id:214,_code:6214,名称:"傅俊",家族:"傅",跳:214,统帅:82,武力:81,智力:61,政治:53,魅力:63,清廉:78,野心:9,性别:0,文化:8,介绍:"傅俊，字子卫，颍川郡襄城人，“云台二十八将”中排名第二十一。原为襄城的亭长，刘秀起兵之后，投奔刘秀，因此被灭族。傅俊随刘秀参加了昆阳大战、平定河北之战、讨伐董欣、邓奉、秦丰、田戎的南征之战，还独自领军平定了江东六郡。"});
  所有历史名人.push({id:215,_code:6215,名称:"坚镡",家族:"坚",跳:215,统帅:71,武力:86,智力:68,政治:62,魅力:5,清廉:89,野心:14,性别:0,文化:8,介绍:"坚镡字子伋，颍川襄城人。原为王莽政权官吏，后投奔刘秀，随刘秀平定河北，镇压大枪等农民军，协助刘秀建立东汉，是东汉中兴名将，“云台二十八将”中排名第二十二。"});
  所有历史名人.push({id:216,_code:6216,名称:"王霸",家族:"王",跳:216,统帅:81,武力:73,智力:79,政治:82,魅力:51,清廉:79,野心:22,性别:0,文化:8,介绍:"王霸，字元伯，汉族，颍川颍阳人，东汉将领，云台二十八将第二十三位。王霸生性喜欢法律，初为监狱官。光武帝路过颖阳时，王霸归附光武帝，和匈奴、乌桓大小几十上百次交战，很熟悉边疆军事，多次上书说应与匈奴结亲讲和，又建议由温水漕运运输，省去陆路运输辛劳，建议都得到实行。"});
  所有历史名人.push({id:217,_code:6217,名称:"任光",家族:"任",跳:217,统帅:73,武力:79,智力:83,政治:79,魅力:73,清廉:81,野心:15,性别:0,文化:8,介绍:"任光，字伯卿，南阳宛城人。云台二十八将第二十四位。原为宛城小吏，后加入绿林军，曾随刘秀参加了昆阳之战。刘玄称帝后封他为信都郡太守。王郎起兵之后，他据城迎接刘秀，使刘秀有了反攻的基地。"});
  所有历史名人.push({id:218,_code:6218,名称:"李忠",家族:"李",跳:218,统帅:73,武力:67,智力:81,政治:89,魅力:71,清廉:89,野心:43,性别:0,文化:8,介绍:"李忠，字仲都，东莱黄县人。东汉开国名将，云台二十八将第二十五位。公元24年，李忠和任光、万修迎接刘秀入信都。被拜为右大将军、封武固侯。随刘秀灭王郎、平河北。刘秀称帝后，李忠任五官中郎将，被封为中水侯。此后又参加平定庞萌、董宪的战争。"});
  所有历史名人.push({id:219,_code:6219,名称:"万修",家族:"万",跳:219,统帅:69,武力:63,智力:81,政治:77,魅力:71,清廉:70,野心:33,性别:0,文化:8,介绍:"万修，字君游，扶风茂陵人，东汉大将，云台二十八将之二十六。万修在更始政权时期被任命为信都令，刘秀宣慰河北之时，王郎起兵追捕刘秀，当时河北的郡国大多投降王郎，只有万修与信都太守任光、信都都尉李忠等人据守信都郡迎接刘秀，使刘秀有了反攻的基地。此后随刘秀击破邯郸、平定河北。"});
  所有历史名人.push({id:220,_code:6220,名称:"邳彤",家族:"邳",跳:220,统帅:74,武力:83,智力:81,政治:61,魅力:54,清廉:70,野心:11,性别:0,文化:8,介绍:"邳彤，字伟君，汉族，信都郡信都县人 。王莽政权时期邳彤担任和成卒正。刘玄称帝后任和成太守。王郎起兵之后，他据城坚守，以待刘秀。此后随刘秀平定天下。先后受封为武义侯、灵寿侯。在河北安国一带的传说中。邳彤被称为“药王”"});
  所有历史名人.push({id:221,_code:6221,名称:"刘植",家族:"刘",跳:221,统帅:67,武力:70,智力:81,政治:74,魅力:81,清廉:70,野心:30,性别:0,文化:8,介绍:"刘植，字伯先，汉族，汉朝巨鹿昌城人。王莽末年，据昌城自守，后归顺刘秀，并助其招降刘扬。此后久经战阵，协助刘秀建立东汉，是东汉中兴名将，“云台二十八将”中排名第二十八。"});
  所有历史名人.push({id:222,_code:6222,名称:"曹文诏",家族:"曹",跳:222,统帅:75,武力:85,智力:40,政治:30,魅力:65,清廉:60,野心:20,性别:0,文化:8,介绍:"曹文诏，山西大同人。勇毅而有智略。明末著名将领。"});
  所有历史名人.push({id:223,_code:6223,名称:"孙承宗",家族:"孙",跳:223,统帅:86,武力:85,智力:78,政治:71,魅力:60,清廉:70,野心:6,性别:0,文化:8,介绍:"孙承宗，字稚绳，号恺阳，北直隶保定高阳人。明末军事战略家。曾为明熹宗朱由校的老师。"});
  所有历史名人.push({id:224,_code:6224,名称:"杨嗣昌",家族:"杨",跳:224,统帅:50,武力:30,智力:78,政治:68,魅力:67,清廉:70,野心:20,性别:0,文化:8,介绍:"杨嗣昌,明代官员。字文弱，号字微，湖南武陵县碴口坡人。万历三十八年进士，崇祯十年任兵部尚书，用“四正六隅”、“十面之网”之策镇压农民起义军，荐熊文灿总理六省军务。后因熊文灿失职，亲自出京督师，被张献忠以走致敌战术牵制，疲于奔命。"});
  所有历史名人.push({id:225,_code:6225,名称:"李成梁",家族:"李",跳:225,统帅:96,武力:95,智力:30,政治:30,魅力:80,清廉:20,野心:20,性别:0,文化:8,介绍:"李成梁，字汝契，号引城，辽东铁岭人，明朝后期将领。镇守辽东30年期间，先后十次奏大捷。但因位望益隆，贵极而骄，奢侈无度，万历三十六年被劾罢。万历四十三年卒，享年90岁。"});
  所有历史名人.push({id:226,_code:6226,名称:"李如松",家族:"李",跳:226,统帅:97,武力:93,智力:70,政治:20,魅力:75,清廉:80,野心:30,性别:0,文化:8,介绍:"李如松，字子茂，号仰城，辽东铁岭卫人，贯陇西李氏，中国明朝著名将领，辽东总兵李成梁之长子。万历中期援朝鲜，以其抗倭成就名垂千古，其中犹值得赞叹的是他指挥的闻名世界的壬辰抗倭援朝战争，出任辽东总兵，后在与蒙古部落的交战中阵亡。死后，朝廷追赠少保宁远伯，立祠谥忠烈。"});
  所有历史名人.push({id:227,_code:6227,名称:"卢象升",家族:"卢",跳:227,统帅:93,武力:97,智力:85,政治:60,魅力:70,清廉:85,野心:1,性别:0,文化:8,介绍:"卢象升，明常州宜兴人，字建斗，号九台，天启进士。授户部主事，擢员外郎，迁大名知府。"});
  所有历史名人.push({id:228,_code:6228,名称:"孙传庭",家族:"孙",跳:228,统帅:90,武力:80,智力:65,政治:20,魅力:50,清廉:70,野心:30,性别:0,文化:8,介绍:"孙传庭自万历四十七年中进士至崇祯十六年兵败身亡的25年间，他由永城知县，逐步升至兵部尚书，统领七省军务，先后参与并主持了数十次对明末农民起义军的镇压活动，深得明廷赏识。《明史》有“传庭死而明亡矣”的说法。"});
  所有历史名人.push({id:229,_code:6229,名称:"赵括",家族:"赵",跳:229,统帅:80,武力:83,智力:75,政治:70,魅力:70,清廉:85,野心:14,性别:0,文化:8,介绍:"赵括，战国时期赵国人，赵国名将赵奢之子，年轻时学兵法，谈起兵事来父亲也难不倒他。长平一战失利，尸骨无存。"});
  所有历史名人.push({id:230,_code:6230,名称:"赵奢",家族:"赵",跳:230,统帅:85,武力:89,智力:75,政治:75,魅力:80,清廉:80,野心:20,性别:0,文化:8,介绍:"赵奢，嬴姓，赵氏，名奢。马服君，战国时代东方六国的八名将之一，简曰马氏。主要生活在赵武灵王到赵孝成王时期，享年约60余岁。"});
  所有历史名人.push({id:231,_code:6231,名称:"陈庆之",家族:"陈",跳:231,统帅:95,武力:77,智力:92,政治:88,魅力:79,清廉:83,野心:30,性别:0,文化:8,介绍:"陈庆之，字子云，汉族，中国南北朝时期南朝梁将领。少为梁武帝萧衍随从。陈庆之身体文弱，难开普通弓弩，不善于骑马和射箭，但是却富有胆略，善筹谋，带兵有方，是一位深得众心的儒将。"});
  所有历史名人.push({id:232,_code:6232,名称:"施士伦",家族:"施",跳:232,统帅:50,武力:20,智力:80,政治:80,魅力:30,清廉:98,野心:2,性别:0,文化:8,介绍:"施世纶，字文贤，清靖海侯施琅之子，是清代著名的清官。他秉公执法，清正廉洁，不畏权贵，勤于民事，在民间素有“施青天”之誉，被康熙称为江南第一清官。"});
  所有历史名人.push({id:233,_code:6233,名称:"韦孝宽",家族:"韦",跳:233,统帅:95,武力:85,智力:84,政治:40,魅力:50,清廉:70,野心:29,性别:0,文化:8,介绍:"韦孝宽，名叔裕，字孝宽，汉族，京兆杜陵人，南北朝时期西魏、北周杰出的军事家、战略家。"});
  所有历史名人.push({id:234,_code:6234,名称:"曹仁",家族:"曹",跳:234,统帅:89,武力:85,智力:72,政治:20,魅力:55,清廉:83,野心:34,性别:0,文化:8,介绍:"字子孝，汉族，沛国谯（今安徽亳州）人，曹操从弟（从祖弟）。三国曹魏名将，官至大司马，封陈侯。曹仁好弓马骑射，少时不修行检，及至长成为大将，则变得严整，奉法守令。从曹操多年，为魏朝立下汗马功劳。"});
  所有历史名人.push({id:235,_code:6235,名称:"徐晃",家族:"徐",跳:235,统帅:89,武力:89,智力:72,政治:58,魅力:45,清廉:89,野心:41,性别:0,文化:8,介绍:"字公明，河东杨（今山西洪洞东南）人。三国时期曹魏名将。本为杨奉帐下骑都尉，杨奉被曹操击败后转投曹操，在曹操手下多立功勋，参与官渡、赤壁、关中征伐、汉中征伐等几次重大战役。"});
  所有历史名人.push({id:236,_code:6236,名称:"万俟卨",家族:"万俟",跳:236,统帅:45,武力:25,智力:89,政治:83,魅力:30,清廉:40,野心:60,性别:0,文化:8,介绍:"万俟卨，字元忠，开封阳武县 ，南宋初年奸臣。初任湖北提点刑狱，依附秦桧，任监察御史、右正言。"});
  所有历史名人.push({id:237,_code:6237,名称:"王彦章",家族:"王",跳:237,统帅:85,武力:90,智力:60,政治:50,魅力:70,清廉:84,野心:30,性别:0,文化:8,介绍:"王彦章，中国五代时后梁名将。字贤明。汉族，郓州寿张人。朱温建后梁时，为彦章以功为亲军将领，历迁刺史、防御使至节度使。他骁勇有力，每战常为先锋，持铁枪驰突，奋疾如飞，军中号为王铁枪。后为李存勖所擒，宁死不降，于是被下令斩首。享年六十一岁。"});
  所有历史名人.push({id:238,_code:6238,名称:"杨一清",家族:"杨",跳:238,统帅:35,武力:20,智力:92,政治:96,魅力:70,清廉:89,野心:20,性别:0,文化:8,介绍:"杨一清，字应宁，号邃庵，别号石淙，明朝南直隶镇江府丹徒人。历经成化、弘治、正德、嘉靖四朝，为官五十余年，官至内阁首辅，号称“出将入相，文德武功”，才华堪与唐代名相姚崇媲美。"});
  所有历史名人.push({id:239,_code:6239,名称:"霍峻",家族:"霍",跳:239,统帅:81,武力:80,智力:79,政治:65,魅力:60,清廉:89,野心:20,性别:0,文化:8,介绍:"霍峻，字仲邈，南郡枝江人，东汉末年刘备麾下名将。"});
  所有历史名人.push({id:240,_code:6240,名称:"邓艾",家族:"邓",跳:240,统帅:95,武力:70,智力:90,政治:90,魅力:70,清廉:80,野心:30,性别:0,文化:8,介绍:"邓艾，字士载，义阳棘阳人。三国时期魏国杰出的军事家、将领。其人文武全才，深谙兵法，对内政也颇有建树。邓艾多年在曹魏西边战线防备蜀汉姜维。"});
  所有历史名人.push({id:241,_code:6241,名称:"张郃",家族:"张",跳:241,统帅:90,武力:85,智力:73,政治:70,魅力:70,清廉:89,野心:25,性别:0,文化:8,介绍:"张郃，字儁乂，河间鄚人。东汉末年，应募参加镇压黄巾起义，后属冀州牧韩馥为军司马。191年，袁绍取冀州，张郃率兵投归，任校尉。后在官渡之战中投降曹操。此后，随曹操攻乌桓、破马超、降张鲁，屡建战功。"});
  所有历史名人.push({id:242,_code:6242,名称:"田丰",家族:"田",跳:242,统帅:30,武力:14,智力:94,政治:90,魅力:40,清廉:93,野心:10,性别:0,文化:8,介绍:"田丰，字元皓，河北巨鹿人 东汉末年袁绍部下谋臣，官至冀州别驾。其为人刚直且有清廉，很有谋略对政治有建树 曾多次向袁绍进言而不被采纳，曹操部下谋臣荀彧曾评价他“刚而犯上”。后因谏阻袁绍征伐曹操而被袁绍下令监禁。官渡之战后，田丰被袁绍杀害。"});
  所有历史名人.push({id:243,_code:6243,名称:"毛玠",家族:"毛",跳:243,统帅:20,武力:15,智力:84,政治:89,魅力:60,清廉:93,野心:12,性别:0,文化:8,介绍:"毛玠，字孝先，陈留平丘人，年少时为县吏，以清廉公正著称。提出“奉天子以令不臣，修耕植，畜军资”的战略规划，得到曹操的欣赏。"});
  所有历史名人.push({id:244,_code:6244,名称:"吕虔",家族:"吕",跳:244,统帅:80,武力:84,智力:80,政治:79,魅力:30,清廉:70,野心:14,性别:0,文化:8,介绍:"吕虔，生卒年不详，字子恪。任城人 。三国时期曹魏将领。"});
  所有历史名人.push({id:245,_code:6245,名称:"孟珙",家族:"孟",跳:245,统帅:90,武力:83,智力:83,政治:79,魅力:70,清廉:90,野心:18,性别:0,文化:8,介绍:"孟珙，字璞玉，原籍绛州，曾祖孟安是岳飞部将，祖父孟林亦是岳飞部属，随军至随州，定居于枣阳。南宋优秀的军事家、统帅，民族英雄，抗金抗蒙名将。南宋中期宋蒙战争爆发后，曾以一人之力统御南宋三分之二战线上的战事，由于其在抵抗蒙古军的杰出表现，被后世军史家称之“机动防御大师”。"});
  所有历史名人.push({id:246,_code:6246,名称:"李典",家族:"李",跳:246,统帅:78,武力:77,智力:81,政治:76,魅力:80,清廉:80,野心:28,性别:0,文化:8,介绍:"字曼成，曹操麾下将领。山阳郡钜野县（今山东巨野）人。李典深明大义，不与人争功，崇尚学习与高贵儒雅，尊重博学之士，在军中被称为长者。李典有长者之风，官至破虏将军，三十六岁去世。魏文帝曹丕继位后追谥号为愍侯。"});
  所有历史名人.push({id:247,_code:6247,名称:"韦睿",家族:"韦",跳:247,统帅:80,武力:30,智力:80,政治:84,魅力:40,清廉:89,野心:19,性别:0,文化:8,介绍:"有光武、周瑜之风的名将，指挥果断，谋略过人 膝下五子，个个勇猛."});
  所有历史名人.push({id:248,_code:6248,名称:"王猛",家族:"王",跳:248,统帅:90,武力:40,智力:93,政治:80,魅力:40,清廉:91,野心:14,性别:0,文化:8,介绍:"王猛，字景略，东晋北海郡剧县人，后移家魏郡。十六国时期著名的政治家、军事家，在前秦官至丞相、大将军，辅佐苻坚扫平群雄，统一北方，被称作“功盖诸葛第一人”。"});
  所有历史名人.push({id:249,_code:6249,名称:"裴行俭",家族:"裴",跳:249,统帅:40,武力:90,智力:90,政治:80,魅力:80,清廉:89,野心:20,性别:0,文化:8,介绍:"儒将之雄，内外双修、文武俱强，出将入相都能达到极高的水准的名将兼能臣."});
  所有历史名人.push({id:250,_code:6250,名称:"韩遂",家族:"韩",跳:250,统帅:79,武力:85,智力:75,政治:65,魅力:40,清廉:88,野心:40,性别:0,文化:8,介绍:"韩遂，字文约。凉州金城郡人。东汉末年军阀、将领，汉末群雄之一。原名韩约，后改名遂。最初闻名于西州，被羌胡叛军劫持并推举为首领，以诛宦官为名举兵造反，聚众十万，先后败皇甫嵩、张温、董卓、孙坚等名将，后受朝廷招安，拥兵割据一方长达三十余年。"});
  所有历史名人.push({id:251,_code:6251,名称:"杜预",家族:"杜",跳:251,统帅:93,武力:80,智力:92,政治:94,魅力:70,清廉:89,野心:27,性别:0,文化:8,介绍:"杜预，字元凯，京兆杜陵人，西晋时期著名的政治家、军事家和学者，灭吴统一战争的统帅之一。著有《春秋左氏经传集解》及《春秋释例》等。"});
  所有历史名人.push({id:252,_code:6252,名称:"羊祜",家族:"羊",跳:252,统帅:80,武力:58,智力:88,政治:78,魅力:60,清廉:93,野心:19,性别:0,文化:8,介绍:"羊祜，字叔子，泰山南城人。著名战略家、政治家和文学家。博学能文，清廉正直，娶夏侯霸之女为妻。"});
  所有历史名人.push({id:253,_code:6253,名称:"高拱",家族:"高",跳:253,统帅:65,武力:33,智力:90,政治:93,魅力:63,清廉:82,野心:38,性别:0,文化:8,介绍:"高拱，字肃卿，号中玄。汉族，新郑人。中国明代嘉靖、隆庆时大臣。"});
  所有历史名人.push({id:254,_code:6254,名称:"长孙道生",家族:"长孙",跳:254,统帅:80,武力:90,智力:76,政治:91,魅力:54,清廉:95,野心:12,性别:0,文化:8,介绍:"长孙道生，代郡人，太尉、柱国大将军、北平王长孙嵩之侄，南北朝时期北魏将领。多次率军征讨，屡立战功，官至司空、侍中等，封上党王。"});
  所有历史名人.push({id:255,_code:6255,名称:"虞允文",家族:"虞",跳:255,统帅:90,武力:61,智力:88,政治:85,魅力:60,清廉:84,野心:34,性别:0,文化:8,介绍:"虞允文，字彬父，一作彬甫，南宋大臣，抗金名将。汉族，南宋隆州仁寿人，绍兴年间进士。"});
  所有历史名人.push({id:256,_code:6256,名称:"杨再兴",家族:"杨",跳:256,统帅:82,武力:90,智力:70,政治:62,魅力:77,清廉:88,野心:21,性别:0,文化:8,介绍:"杨再兴，南宋抗金名将。原是曹成部将，后降于岳飞，成为岳飞部将，跟随岳飞抗击金军，曾试图单枪匹马冲阵擒获金兀术，失败后仍能单骑而还。绍兴十年，杨再兴与金人在小商桥相遇，杨再兴寡不敌众，中箭无数，奋战而亡。"});
  所有历史名人.push({id:257,_code:6257,名称:"张用",家族:"张",跳:257,统帅:61,武力:82,智力:68,政治:42,魅力:34,清廉:51,野心:38,性别:0,文化:8,介绍:"张用，淮阴人，小说里为岳飞、王贵的结拜兄弟，为人贪财怕死，但武艺不错，品性良好，多次暗里帮助岳飞，但又多次怕死而离开岳飞，被岳飞鄙视。多次参军又叛逃，后为岳飞招降。"});
  所有历史名人.push({id:258,_code:6258,名称:"傅庆",家族:"傅",跳:258,统帅:58,武力:88,智力:44,政治:30,魅力:33,清廉:54,野心:48,性别:0,文化:8,介绍:"傅庆，卫州窑户，原为杜充建康留守司统制戚方部属，建炎三年戚方叛逃，岳飞招抚其部众，傅庆率军归降岳飞，授岳家军前军统制。傅庆勇敢善战，屡立功勋，但生性居功自傲，屡次向岳飞勒索财物，不喜岳飞治军严格，在岳飞任通泰镇抚使兼泰州知州时曾谋投刘光世军，建炎四年十一月在泰州清水亭为岳飞所杀。"});
  所有历史名人.push({id:259,_code:6259,名称:"王旦",家族:"王",跳:259,统帅:62,武力:38,智力:94,政治:93,魅力:83,清廉:87,野心:17,性别:0,文化:8,介绍:"王旦，字子明。大名莘县人。北宋名相，王祜子。以著作郎预编《文苑英华》。谥号文正，故后世称其为“王文正”。为昭勋阁二十四功臣之一。"});
  所有历史名人.push({id:260,_code:6260,名称:"赵昌言",家族:"赵",跳:260,统帅:62,武力:33,智力:91,政治:89,魅力:77,清廉:88,野心:15,性别:0,文化:8,介绍:"赵昌言，字仲谟，一作幼谟，汾州孝义人。太平兴国三年，戊寅科胡旦榜进士第三人。赵昌言少有大志，朝中重臣寇准等人对他评价很高。举进士时，他由于文思敏捷而名震考场，以贡部第一的身份参加了廷试。赵昌言作事有气魄，为官以威断立名。"});
  所有历史名人.push({id:261,_code:6261,名称:"张仁愿",家族:"张",跳:261,统帅:90,武力:89,智力:79,政治:84,魅力:62,清廉:83,野心:18,性别:0,文化:8,介绍:"张仁愿，原名仁亶，华州下邽人，唐朝宰相、名将。张仁愿文武全才，曾任殿中侍御史，后任肃政台中丞，检校幽州都督，击退突厥默啜可汗的进犯，兼任并州大都督府长史。"});
  所有历史名人.push({id:262,_code:6262,名称:"姚崇",家族:"姚",跳:262,统帅:88,武力:88,智力:88,政治:88,魅力:58,清廉:68,野心:18,性别:0,文化:8,介绍:"姚崇，本名元崇，字元之，唐代著名政治家。姚崇文武双全，历仕则天、中宗、睿宗三朝，两次拜为宰相，并兼任兵部尚书。他提出十事要说，实行新政，辅佐唐玄宗开创开元盛世，被称为救时宰相。姚崇执政三年，与房玄龄、杜如晦、宋璟并称唐朝四大贤相。"});
  所有历史名人.push({id:263,_code:6263,名称:"宋璟",家族:"宋",跳:263,统帅:62,武力:31,智力:90,政治:93,魅力:51,清廉:88,野心:18,性别:0,文化:8,介绍:"宋璟，广平，十七岁中进士。经武周、中宗、睿宗、殇帝、玄宗五帝，在任52年。开元年间与姚崇同朝为相，把一个充满内忧外患的唐朝，改变为政治、经济、文化、军事处于世界领先地位的大唐帝国，史称“开元盛世”。"});
  所有历史名人.push({id:264,_code:6264,名称:"杜如晦",家族:"杜",跳:264,统帅:89,武力:21,智力:89,政治:82,魅力:71,清廉:80,野心:23,性别:0,文化:8,介绍:"杜如晦，字克明，为隋唐时期李世民帐下重要参谋。李世民承帝位后，杜如晦与房玄龄为左右宰相，为唐选拔人才，制定法度等。"});
  所有历史名人.push({id:265,_code:6265,名称:"裴寂",家族:"裴",跳:265,统帅:33,武力:21,智力:88,政治:91,魅力:57,清廉:84,野心:33,性别:0,文化:8,介绍:"裴寂，字玄真，唐朝宰相。裴寂出身河东裴氏西眷房，隋末曾任晋阳宫副监，与唐高祖交好，后参与策划太原起兵，将晋阳宫物资充作军用。唐朝建立后，裴寂担任左仆射、司空等要职。629年，裴寂受僧人法雅牵连，被免官削邑，放归原籍，后流放静州，并率家僮讨平山羌叛乱。"});
  所有历史名人.push({id:266,_code:6266,名称:"颜真卿",家族:"颜",跳:266,统帅:61,武力:24,智力:89,政治:84,魅力:71,清廉:88,野心:23,性别:0,文化:8,介绍:"颜真卿，字清臣，唐代著名政治家、书法家。颜真卿创立“颜体”楷书，与赵孟頫、柳公权、欧阳询并称为“楷书四大家”。又与柳公权并称“颜柳”。"});
  所有历史名人.push({id:267,_code:6267,名称:"崔日用",家族:"崔",跳:267,统帅:69,武力:48,智力:89,政治:87,魅力:66,清廉:89,野心:33,性别:0,文化:8,介绍:"崔日用，唐朝大臣，诗人。进士出身，为芮城尉。史称崔日用“每朝廷有事，转祸为福，以取富贵”。封齐国公。"});
  所有历史名人.push({id:268,_code:6268,名称:"陈玄礼",家族:"陈",跳:268,统帅:79,武力:88,智力:69,政治:71,魅力:56,清廉:62,野心:43,性别:0,文化:8,介绍:"陈玄礼，唐代名将，初任神武军的果毅都尉，后随李隆基起兵诛杀韦后及安乐公主。玄宗即位后，宿卫宫中。安史之乱时，率军护卫玄宗逃亡四川，行至马嵬驿，在太子李亨支持下，发动兵变杀杨国忠及杨氏姐妹，并逼唐玄宗李隆基缢死了杨贵妃。"});
  所有历史名人.push({id:269,_code:6269,名称:"鱼朝恩",家族:"鱼",跳:269,统帅:83,武力:35,智力:81,政治:67,魅力:37,清廉:43,野心:68,性别:0,文化:8,介绍:"唐朝的擅权宦官。唐玄宗时入宫当太监。安史之乱发生后，随唐玄宗出逃，侍奉太子李亨，颇得信用，历任三宫检责使、左监门卫将军，主管内侍省，统率神策军。最后被宰相元载设计缢死。鱼朝恩的出现大大加强了宦官的实力，为唐朝中、晚期的宦官专权局面埋下了伏笔。"});
  所有历史名人.push({id:270,_code:6270,名称:"尚可孤",家族:"鱼",跳:270,统帅:89,武力:88,智力:77,政治:85,魅力:73,清廉:80,野心:12,性别:0,文化:8,介绍:"尚可孤，原是鲜卑宇文部落人，世代居住松、漠之间，后归降唐朝，隶属范阳节度使安禄山，后来又归属平卢节度使史思明。宦官鱼朝恩统领禁军，喜欢尚可孤的勇猛，特别信任，收为养子，让他改姓鱼，名智德，率领神策禁兵三千人驻守扶风县，后移镇武功。"});
  所有历史名人.push({id:271,_code:6271,名称:"鱼豢",家族:"长鱼",跳:271,统帅:31,武力:25,智力:91,政治:87,魅力:45,清廉:80,野心:15,性别:0,文化:8,介绍:"鱼豢，长鱼氏；京兆人。著名三国时期曹魏国郎中，史学家。撰写有著名的纪传体史书《魏略》，是魏、晋时期不可多得的史学巨著。"});
  所有历史名人.push({id:272,_code:6272,名称:"鱼俱罗",家族:"鱼",跳:272,统帅:85,武力:89,智力:43,政治:41,魅力:45,清廉:80,野心:19,性别:0,文化:8,介绍:"鱼俱罗，著名隋朝将领。鱼俱罗“身长八尺，膂力绝人，声气雄壮，言闻数百步”；每逢战事，“俱罗与数骑奔击，瞋目大呼，所当皆披靡，出左入右，往返若飞”。"});
  所有历史名人.push({id:273,_code:6273,名称:"鱼孟威",家族:"鱼",跳:273,统帅:89,武力:31,智力:80,政治:81,魅力:66,清廉:90,野心:14,性别:0,文化:8,介绍:"鱼孟威，著名唐朝官吏。他写有《重修灵渠记》，建议常加修浚，以利国计民生。后人感念其功，列为修渠“四贤”之一。"});
  所有历史名人.push({id:274,_code:6274,名称:"鱼侃",家族:"鱼",跳:274,统帅:72,武力:11,智力:85,政治:86,魅力:68,清廉:90,野心:5,性别:0,文化:8,介绍:"鱼侃，字希直，晚号颐庵；江苏常熟人。著名明朝官吏。由于鱼侃为人光明正大，铁面无私，秉公执法。当时人们称他“包老”，将他比作包公。"});
  所有历史名人.push({id:275,_code:6275,名称:"令狐楚",家族:"令狐",跳:275,统帅:49,武力:20,智力:88,政治:87,魅力:72,清廉:81,野心:14,性别:0,文化:8,介绍:"唐朝大臣、诗人，字壳士，宜州华原人。他举进士后入仕，担任过中书待郎、尚书、仆射等官职，政绩卓著。他还常与名诗人白居易、刘禹锡唱和，李商隐也出自他的门下，但他本人所作的好诗并不多。他的儿子令狐绹也举为进士后入仕，后官至丞相。"});
  所有历史名人.push({id:276,_code:6276,名称:"东方虬",家族:"东方",跳:276,统帅:37,武力:23,智力:85,政治:84,魅力:68,清廉:82,野心:18,性别:0,文化:8,介绍:"唐朝史官、诗人，唐代武后时任左史，工诗。唐朝武则天时任左史，善于写诗。"});
  所有历史名人.push({id:277,_code:6277,名称:"张廷玉",家族:"张",跳:277,统帅:20,武力:9,智力:93,政治:95,魅力:50,清廉:90,野心:20,性别:0,文化:8,介绍:"张廷玉，字衡臣，号砚斋，安徽桐城人。清康熙时任刑部左侍郎，雍正帝时曾任礼部尚书、户部尚书等职。康熙末年，整治松弛的吏治，后又完善军机制度。"});
  所有历史名人.push({id:278,_code:6278,名称:"况钟",家族:"况",跳:278,统帅:10,武力:9,智力:92,政治:94,魅力:80,清廉:93,野心:9,性别:0,文化:8,介绍:"况钟，明代官员。字伯律，号龙岗，又号如愚。宣德五年出任苏州知府，他是明代一位受百姓尊敬的清官，苏州人民称他“况青天”，和包拯“包青天” 海瑞“海青天”，并称中国民间的三大青天."});
  所有历史名人.push({id:279,_code:6279,名称:"邓芝",家族:"邓",跳:279,统帅:5,武力:12,智力:90,政治:93,魅力:79,清廉:93,野心:13,性别:0,文化:8,介绍:"邓芝，字伯苗。东汉名将邓禹之后，三国时蜀汉重臣。早年就曾被预言，认为其能位至大将。后被刘备任为郫令，升迁为广汉太守。因任官清廉、严谨，有治绩，被征入朝为尚书。刘备逝世后，奉命出使吴国，成功修复两国关系，并深为孙权所欣赏。"});
  所有历史名人.push({id:280,_code:6280,名称:"法正",家族:"法",跳:280,统帅:10,武力:3,智力:95,政治:91,魅力:83,清廉:91,野心:13,性别:0,文化:8,介绍:"法正，字孝直。原为刘璋部下，刘备围成都时劝说刘璋投降，而后又与刘备进取汉中，献计将曹操大将夏侯渊斩首。法正善奇谋，深受刘备信任和敬重。"});
  所有历史名人.push({id:281,_code:6281,名称:"荀攸",家族:"荀",跳:281,统帅:66,武力:37,智力:90,政治:93,魅力:85,清廉:89,野心:21,性别:0,文化:8,介绍:"荀攸，表字公达，颍川颍阴（今河南许昌）人。荀彧之侄，杰出战术家，被称为曹操的“谋主”，擅长灵活多变的克敌战术和军事策略。"});
  所有历史名人.push({id:282,_code:6282,名称:"乐进",家族:"乐",跳:282,统帅:85,武力:88,智力:62,政治:58,魅力:70,清廉:78,野心:31,性别:0,文化:8,介绍:"乐进，字文谦，阳平卫国（今山东莘县）人。东汉末年曹操部将。以胆识英烈而从曹操，随军多年，南征北讨，战功无数。"});
  所有历史名人.push({id:283,_code:6283,名称:"钟会",家族:"钟",跳:283,统帅:85,武力:64,智力:90,政治:78,魅力:67,清廉:72,野心:80,性别:0,文化:8,介绍:"钟会，字士季。三国时期魏国名将、书法家。自幼才华横溢，上至皇帝、下至群臣都对他非常赏识。曾为司马昭献策阻止了曹髦的夺权企图。景元年间，钟会独力支持司马昭的伐蜀计划，从而被任命为镇西将军，假节都督关中诸军事。主持发动伐蜀之战。公元263年，他与邓艾分兵攻打蜀汉，导致蜀汉灭亡。此后钟会欲据蜀自立，与蜀汉降将姜维共谋其事，却因部下的反叛而失败，自己也死于部将兵变，时年40岁。"});
  所有历史名人.push({id:284,_code:6284,名称:"谭纶",家族:"谭",跳:284,统帅:93,武力:90,智力:89,政治:23,魅力:50,清廉:70,野心:20,性别:0,文化:8,介绍:"谭纶（1520年－1577年），字子理，号二华，汉族江右民系，江西宜黄县谭坊人。明代抗倭名将、勇冠三军丶杰出的军事家。与戚继光、俞大猷、李成梁齐名。"});
  所有历史名人.push({id:285,_code:6285,名称:"吴起",家族:"吴",跳:285,统帅:90,武力:30,智力:94,政治:80,魅力:80,清廉:95,野心:30,性别:0,文化:8,介绍:"吴起（前440年－前381年），中国战国初期军事家、政治家、改革家，兵家代表人物。吴起一生历侍鲁、魏、楚三国，通晓兵家、法家、儒家三家思想，在内政、军事上都有极高的成就。后世把他和孙武并称为“孙吴”，《吴子》与《孙子》又合称《孙吴兵法》，在中国古代军事典籍中占有重要地位。"});
  所有历史名人.push({id:286,_code:6286,名称:"吕夷简",家族:"吕",跳:286,统帅:20,武力:30,智力:97,政治:84,魅力:50,清廉:80,野心:10,性别:0,文化:8,介绍:"吕夷简（978年－1044年10月3日），字坦夫，汉族，寿州（治今安徽凤台）人。祖籍莱州（今属山东），祖父吕龟祥移家寿州（治今安徽凤台）。宋代著名政治家，真宗朝名臣吕蒙正之侄。宋真宗年间以刑部郎中权知开封府。宋仁宗立，任宰相。他辅佐年幼的仁宗，在太后临朝听政的情况下，正确处理北宋国内国外诸多矛盾，保证了北宋社会安定，经济发展，为宋代名相之一。"});
  所有历史名人.push({id:287,_code:6287,名称:"李莫愁",家族:"李",跳:287,统帅:70,武力:88,智力:79,政治:50,魅力:92,清廉:80,野心:60,性别:1,文化:8,介绍:"金庸武侠小说《神雕侠侣》中主要反面人物之一，为情所伤很悲情的女性人物，绰号“赤练仙子”，是主人公杨过的师伯，小龙女的师姐。"});
  所有历史名人.push({id:288,_code:6288,名称:"杜凤扬",家族:"杜",跳:288,统帅:84,武力:85,智力:70,政治:50,魅力:89,清廉:88,野心:45,性别:1,文化:8,介绍:"杜凤扬，清咸丰、同治年间云南回民起义军杜文秀长女，童年随父起义。清官吏称其“知兵善战，为贼所推服”。同治七年曾率军击溃云贵总督刘岳昭军（其中有久经战阵的湘军），围攻昆明城。不久清廷调大军进援，杜文秀失败。杜凤扬逃至民间，后为云南提督马如龙（起义军叛徒）搜获。最后在昆明被巡抚岑毓英秘密处死。"});
  所有历史名人.push({id:289,_code:6289,名称:"王异",家族:"王",跳:289,统帅:74,武力:65,智力:87,政治:70,魅力:89,清廉:88,野心:45,性别:1,文化:8,介绍:"王异，或作士异，东汉末年曹操所置羌道令、益州刺史赵昂之妻。马超作乱凉州时，王异协助丈夫守城，多有功勋，马超强攻冀城时赵昂曾顾惜亲子而不敢轻易定计，王异道：“雪君父之大耻，虽丧身亦不惜，何况一子乎！君若顾子而不行，吾当先死矣！”令赵昂下定决心协助杨阜。王氏更将自己的首饰资帛，亲自往祁山军中赏劳军士，自马超攻冀城至祁山坚守，赵昂曾出奇计九条，王异皆有参与。"});
  所有历史名人.push({id:290,_code:6290,名称:"屠炉",家族:"屠",跳:290,统帅:84,武力:85,智力:87,政治:40,魅力:89,清廉:88,野心:45,性别:1,文化:2,介绍:"清代章回体古典小说《说唐后传》人物。西番国丞相屠封之女，乃黄龙岭守将。因她能知三略，会提兵调将，善识八卦阵，兵书、战册尽皆通透。气力又狠、武艺又精、才高貌美。所以东突厥的赤壁宝康王将她过继为公主。"});
  所有历史名人.push({id:291,_code:6291,名称:"妇好",家族:"子",跳:291,统帅:90,武力:88,智力:87,政治:80,魅力:90,清廉:50,野心:30,性别:1,文化:8,介绍:"商朝君主武丁的妻子，中国历史上有据可查（甲骨文）的第一位女性军事统帅，同时也是一位杰出的女政治家。她不仅能够率领军队东征西讨为武丁拓展疆土，而且还主持着武丁朝的各种祭祀活动。因此武丁十分喜欢她，她去世后武丁悲痛不已，追谥曰“辛”，商朝的后人们尊称她为“母辛”、“后母辛”，司母辛鼎即是她的用器。"});
  所有历史名人.push({id:292,_code:6292,名称:"荀灌",家族:"荀",跳:292,统帅:90,武力:83,智力:87,政治:80,魅力:90,清廉:80,野心:30,性别:1,文化:8,介绍:"晋平南将军、襄阳太守，都督江北诸军事，曹操重要谋士荀彧之后荀崧女荀灌，她自幼好骑射，在宛城被数万胡骑围困时，以十三岁稚龄，率十余死士突破重围，请来援军，解宛城围。"});
  所有历史名人.push({id:293,_code:6293,名称:"李秀宁",家族:"李",跳:293,统帅:91,武力:82,智力:88,政治:82,魅力:90,清廉:80,野心:30,性别:1,文化:8,介绍:"平阳公主，唐高祖李渊第三女，母为太穆皇后窦氏。才识胆略过人，大业末年，为了策应晋阳起兵，发动司竹起兵，统领『娘子军』建功立业，挑选精兵与李世民会师共同攻破长安。唐朝建立后，册封平阳公主。武德六年（623年），去世，谥号为昭，是唐朝第一位死后赐予谥号的公主，也是中国封建史上唯一一个采用军礼殡葬的女子，真正的生荣死哀。"});
  所有历史名人.push({id:294,_code:6294,名称:"冼阿莫",家族:"冼",跳:294,统帅:90,武力:83,智力:87,政治:80,魅力:90,清廉:80,野心:30,性别:1,文化:8,介绍:"谯国夫人即冼珍，又称冼夫人，南北朝时期南越族首领，政治家、军事家、社会活动家。她善于结识英雄豪杰，嫁于当时的高凉太守冯宝。她率领族人归附隋朝被加封谯国夫人，历经梁、陈、隋三朝，世为南越首领，一生审时度势，顺应潮流，识时务，爱国爱民，因而深得后人敬重，先后被七朝君王敕封，被尊称为岭南“圣母”。"});
  所有历史名人.push({id:295,_code:6295,名称:"梁红玉",家族:"梁",党:0,跳:295,统帅:78,武力:77,智力:80,政治:65,魅力:90,清廉:80,野心:55,性别:1,文化:8,介绍:"梁红玉。宋代楚州（今淮安）北辰坊人，生于宋徽宗崇宁元年，父亲行伍出身，后征方腊战败获罪被杀，红玉由此沦为京口歌姬。后来被韩世忠娶了，在黄天荡大战中亲自击鼓助战，使宋军士气大振，是中国著名的女英雄。"});
  所有历史名人.push({id:296,_code:6296,名称:"杨妙真",家族:"杨",党:0,跳:296,统帅:64,武力:72,智力:77,政治:50,魅力:90,清廉:78,野心:30,性别:1,文化:8,介绍:"金末武术家，红袄军首领杨安儿之妹，号“四娘子”，与李全结为夫妇，随李全投宋，又降蒙古，善骑射。嘉定十三年以后，偏安江南的南宋统治者，担心转战北方的李、杨“红袄军”伺机反宋，处处加以提防与刁难。控制使用、少发粮晌，并且在宋军、各忠义军和李、杨军队之间制造磨擦，挑起地方割据。先后派贾涉、许国等出任淮东制置使，公开向李全、杨妙真发难，削弱其义军势力。"});
  所有历史名人.push({id:297,_code:6297,名称:"唐赛儿",家族:"杨",党:0,跳:297,统帅:74,武力:78,智力:87,政治:70,魅力:87,清廉:78,野心:30,性别:1,文化:8,介绍:"唐赛儿是明朝初年起兵反朝廷的著名白莲教女首领。唐赛儿通晓法术兵法，以传白莲教为名，集合民众数千起事。唐赛儿起事后全歼了前来围攻的军队，各地民众纷纷响应。朝廷派出京师精兵前来征讨。明军仗人多势众，包围了唐赛儿山寨。唐赛儿假作投降，乘机夜袭官军。明军大乱，唐赛儿突围而出。"});
  所有历史名人.push({id:298,_code:6298,名称:"柴媚春",家族:"柴",党:0,跳:298,统帅:78,武力:79,智力:87,政治:79,魅力:89,清廉:89,野心:30,性别:1,文化:8,介绍:"柴郡主，小说人物，杨六郎正妻。过继给宋太祖赵匡胤，从小在赵匡胤家长大，与八贤王赵德芳兄妹相称。柴郡主长大成人后，嫁给杨继业的儿子——杨延昭，成为一名巾帼英雄、女中豪杰，成为杨门女将之一，在杨家将中除佘太君以外，比较有份量的人物，多次和杨门女将一起出去打仗，保卫国家疆士，出生入死，奋不顾身。"});
  所有历史名人.push({id:299,_code:6299,名称:"红娘子",家族:undefined,党:0,跳:299,统帅:78,武力:79,智力:79,政治:75,魅力:88,清廉:88,野心:50,性别:1,文化:8,介绍:"红娘子，姓名不详，明末民变中起义军的女将，李岩之妻。出身于江湖艺人。李岩在河南杞县散粮赈灾济贫，红娘子率众起义，攻破县衙，与李岩成婚。李岩后来离开义军，回到家乡。被官府缉拿。红娘子救出李岩，一起投靠李自成。"});
  所有历史名人.push({id:300,_code:6300,名称:"佘赛花",家族:"佘",党:0,跳:300,统帅:88,武力:81,智力:89,政治:81,魅力:89,清廉:86,野心:40,性别:1,文化:8,介绍:"佘太君名佘赛花，在评书演义中是杨家将中杨继业之妻，其一生经历数代杨家将故事，至百岁还率领十二寡妇征西夏，为杨门女将的代表人物。其历史原型为北宋名将折德扆之女，宋代名将杨继业（杨业）之妻折氏。"});
  所有历史名人.push({id:301,_code:6301,名称:"杨延琪",家族:"杨",党:0,跳:301,统帅:59,武力:78,智力:60,政治:30,魅力:83,清廉:75,野心:38,性别:1,文化:8,介绍:"佘太君之小女儿，刁蛮少女贵千金，冰雪聪明，鬼马自信，能言善辩，敢作敢为，文韬武略，才华锋芒毕露。具大丈夫气概，而不失女性温柔，挑战传统，不理天高地厚，漠视世情，不怕权势，有点我行我素。初期不认同佘太君为杨家一块御赐丰碑，及后明白丰碑的为杨门猛将以热血换取的无尚荣耀，开始肩负杨家使命，发挥杨门英雌，巾帼丈夫本色。"});
  所有历史名人.push({id:302,_code:6302,名称:"陆令萱",家族:"陆",党:0,跳:302,统帅:28,武力:24,智力:77,政治:79,魅力:90,清廉:12,野心:89,性别:1,文化:15,介绍:"陆令萱，又称陆媪，鲜卑族，代郡(今山西)人。北齐后期奸臣、女官，官至女侍中。最初，嫁给北魏将领骆超。骆超谋反被诛，陆令萱被没入皇宫为婢女，后拨给长广王高湛宫中，成为太子高纬乳母，封为郡君。公元565年，高纬即位，授陆令萱为女侍中，正三品，母子把持朝政，陷害忠良，权倾一时。公元576年，北周大举进攻北齐，攻下邺城，陆令萱自杀，其子孙皆弃市，北齐从此灭亡。"});
  所有历史名人.push({id:303,_code:6303,名称:"曹植",家族:"曹",党:0,跳:303,统帅:68,武力:39,智力:88,政治:85,魅力:89,清廉:89,野心:20,性别:0,文化:8,介绍:"曹植，字子建，曹操与武宣卞皇后所生第三子，三国时期著名文学家，作为建安文学的代表人物之一与集大成者， 他在两晋南北朝时期，被推尊到文章典范的地位。其代表作有《洛神赋》《白马篇》《七哀诗》等。后人因其文学上的造诣而将他与曹操、曹丕合称为“三曹”。其诗以笔力雄健和词采华美见长，散文具有“情兼雅怨，体被文质”的特色，加上其品种的丰富多样，使他在这方面取得了卓越的成就。"});
  所有历史名人.push({id:304,_code:6304,名称:"杨延昭",家族:"杨",党:0,跳:304,统帅:78,武力:79,智力:81,政治:79,魅力:89,清廉:89,野心:30,性别:0,文化:8,介绍:"杨延昭，本名杨延朗，后改为杨延昭，亦称杨六郎，并州太原（今山西太原）人，北宋名将。杨延昭自幼随父亲杨业征战，雍熙三年北伐，杨业率军攻应、朔等州，时年二十九岁的延昭为先锋，战朔州城下，流矢穿臂，战斗愈勇，终于攻下朔州。其父死，便担负起河北延边的抗辽重任。在与辽兵作战中，杨延昭威震边庭，人们称杨延昭守卫的遂城为“铁遂城”。宋真宗称赞他“治兵护塞有父风”。"});
  所有历史名人.push({id:所有历史名人.length,_code:1000,名称:"李奕",家族:"李",党:0,跳:400,统帅:78,武力:54,智力:88,政治:85,魅力:91,清廉:96,野心:20,性别:0,文化:8,介绍:"北魏宿卫监,也是冯太后的男宠。"});
  所有历史名人.push({id:所有历史名人.length,_code:1001,名称:"潘安",家族:"潘",党:0,跳:401,统帅:20,武力:28,智力:90,政治:85,魅力:99,清廉:90,野心:10,性别:0,文化:8,介绍:"潘安，即潘岳，又名潘安仁，字安仁，西晋著名文学家，出身儒学世家。作为男性美的符号，他体现的是一种、柔美多愁的文采风流"});
  所有历史名人.push({id:所有历史名人.length,_code:1002,名称:"李佑",家族:"李",党:0,跳:402,统帅:78,武力:78,智力:84,政治:82,魅力:91,清廉:92,野心:15,性别:0,文化:8,介绍:"唐太宗的第五子，出生年份不详，被封为宜阳，又被封为楚王、燕王、齐王，最后被自己父亲赐死。"});
  所有历史名人.push({id:所有历史名人.length,_code:1003,名称:"宋玉",家族:"宋",党:0,跳:403,统帅:23,武力:48,智力:87,政治:89,魅力:97,清廉:88,野心:12,性别:0,文化:8,介绍:"战国后期楚国辞赋作家，鄢城人。其艺术成就很高，为屈原之后最杰出的楚辞作家。"});
  所有历史名人.push({id:所有历史名人.length,_code:1004,名称:"公孙子都",家族:"公孙",党:0,跳:404,统帅:23,武力:89,智力:83,政治:83,魅力:91,清廉:80,野心:30,性别:0,文化:8,介绍:"周朝末年，春秋时期郑国人，原名公孙阏，本姓为姬，与周王同宗，字子都，是郑国的宗族子弟（郑国贵族）。为郑国公族大夫，春秋第一美男，武艺高超，相貌英俊，因此深得郑庄公宠幸。"});
