  后宫名人.push({id:75,_code:2075,性格:[13,9],名称:"公孙大娘",家族:"公孙",党:0,跳:75,统帅:1,武力:30,智力:60,政治:30,魅力:90,清廉:90,野心:3,性别:1,文化:8,介绍:"公孙大娘是开元盛世时的唐宫的第一舞人。以舞《剑器》而闻名于世。她在民间献艺，观者如山，应邀到宫廷表演，无人能比。世事浮云，以公孙娘子盛唐第一的技艺，最终结局却是流落江湖，寂寞而终。然而，她的盖世技艺是与中国历史上的两座文化高峰联系在一起的。正是因为她，我们才有幸看到了草圣张旭的一卷绝妙丹青，才有幸读到了诗圣杜甫的一首慷慨悲凉的《剑器行》，就连画圣吴道子也曾通过观赏公孙大娘舞剑，体会用笔之道。"});
  后宫名人.push({id:76,_code:2076,性格:[14,1],名称:"李仙蕙",家族:"李",党:0,跳:76,统帅:24,武力:15,智力:60,政治:80,魅力:92,清廉:19,野心:90,性别:1,文化:8,介绍:"唐中宗李显第七女，字秾辉。李显在帝位仅一年，当遭武后废黜，贬降庐陵郡王。仙蕙因是韦妃嫡出，得封永泰郡主。她姿色端妍，才智聪慧，终温且惠，淑慎其身。驸马武延基因私议武后男宠二张之事，被杖杀。她受惊难产、一身两命，韶龄仅十七。中宗复位，追赠永泰公主，超礼改葬，号墓为陵，规格与帝王相等。此等哀荣，空前绝后。"});
  后宫名人.push({id:77,_code:2077,性格:[5,18],名称:"杨芷",家族:"杨",党:0,跳:77,统帅:25,武力:10,智力:61,政治:61,魅力:90,清廉:67,野心:30,性别:1,文化:8,介绍:"西晋晋武帝的皇后，字季兰，小字男胤，东汉太尉杨震幼子杨奉的后裔，宁二年立为皇后，史称“婉嫕有妇德，美映椒房”，得宠于晋武帝，后押到金墉城居住冻饿而死。"});
  后宫名人.push({id:78,_code:2078,性格:[3,4],名称:"王神爱",家族:"王",党:0,跳:78,统帅:20,武力:23,智力:86,政治:67,魅力:93,清廉:67,野心:20,性别:1,文化:8,介绍:"出身琅琊王氏，东晋安帝司马德宗的皇后。王神爱是新安公主司马道福与驸马王献之的爱女，才貌双全、姿情冠时，书法神妙、不逊乃父。她在十五岁时嫁配太子司马德宗为嫡妃，次年晋身正宫皇后，有宠无所出。"});
  后宫名人.push({id:79,_code:2079,性格:[1,40],名称:"苏蕙",家族:"苏",党:0,跳:79,统帅:28,武力:11,智力:81,政治:64,魅力:86,清廉:88,野心:30,性别:1,文化:8,介绍:"字若兰，十六国时期东扶风人，容貌秀丽，举止娴雅，十六岁时嫁于前秦秦州刺史窦滔。窦滔因罪徙放流沙，与妻苏蕙海誓山盟，挥泪告别。苏蕙表白对窦滔的忠贞不渝的爱情，等他回来团圆，誓死不改嫁；可是窦滔到流沙后却另寻新妇，苏蕙得知，由思念转为郁愤。花前月下，椒房灯前，织成婉转循环锦绣文诗，名曰《璇玑图》，寄与窦滔，使夫妻关系重新合好。"});
  后宫名人.push({id:80,_code:2080,性格:[0,7],名称:"郑瞀",家族:"郑",党:0,跳:80,统帅:51,武力:20,智力:86,政治:88,魅力:82,清廉:78,野心:46,性别:1,文化:8,介绍:"郑瞀 ，郑国人。楚成王娶郑国国君之女，郑瞀是作为媵妾随嫁来楚国的。《古列女传》说，楚成王想改立太子，询问郑瞀意思，郑认为楚成王多爱其子，又不明，使庶嫡纷争，祸乱将作，楚成王不听。后又想废商臣，改立王子职为太子，郑瞀想以自身之死而使楚成王回心转意，于是自尽。后来臣果然与其师潘崇谋，发动政变，逼其父楚成王自缢而死。"});
  后宫名人.push({id:81,_code:2081,性格:[37,29],名称:"冯小怜",家族:"冯",党:0,跳:81,统帅:20,武力:15,智力:66,政治:66,魅力:92,清廉:19,野心:85,性别:1,文化:15,介绍:"北齐后主高纬的嫔妃，聪明灵巧，善弹琵琶，精于歌舞，后北齐灭亡被周军押解到长安，后因中伤李氏，被李询的母亲赐死。"});
  后宫名人.push({id:82,_code:2082,性格:[6,40],名称:"步非烟",家族:"步",党:0,跳:82,统帅:22,武力:17,智力:75,政治:68,魅力:88,清廉:67,野心:27,性别:1,文化:8,介绍:"步非烟，也作步飞烟，是唐传奇《非烟传》中的女主角，是唐懿宗时期临淮武公业的爱妾，曰非烟，姓步氏，容止纤丽，若不胜绔罗。善秦声，好文笔，尤工击瓯，其韵与丝竹合。"});
  后宫名人.push({id:83,_code:2083,性格:[29,35],名称:"宣姜",家族:"姜",党:0,跳:83,统帅:22,武力:18,智力:69,政治:69,魅力:91,清廉:39,野心:40,性别:1,文化:8,介绍:"卫宣姜是齐僖公长女，原为卫国世子急所聘，可是卫宣公却贪其美色，故意於婚礼前命世子急使宋，并在新婚之日於新台把儿媳据为己有。"});
  后宫名人.push({id:84,_code:2084,性格:[3,5],名称:"郑旦",家族:"郑",党:0,跳:84,统帅:24,武力:19,智力:70,政治:70,魅力:94,清廉:39,野心:40,性别:1,文化:8,介绍:"春秋末年越国（今诸暨）美人，与西施同时齐名，在越教授以礼仪，习以歌舞，精通舞技，容貌堪比西施，与西施有“浣纱双姝”之称。郑旦好剑，性格刚烈，与西施一同被越王勾践选中，教以礼仪，习以歌舞，献吴王为妃，以迷惑吴王夫差，离间其君臣关系。她们临危受命，忍辱负重，以身许国，扮演了使者和间谍的角色。"});
  后宫名人.push({id:85,_code:2085,性格:[17,40],名称:"沈珍珠",家族:"沈",党:0,跳:85,统帅:2,武力:3,智力:80,政治:76,魅力:86,清廉:80,野心:2,性别:1,文化:8,介绍:"睿真皇后，沈姓，名字生卒年不详。吴兴人氏，唐代宗为广平郡王时的妾室，唐德宗生母，在安史之乱中失踪，后追尊为皇太后。电视系列剧《珍珠传奇》片头曲《望断西京留传奇》中的歌词描述为：“天姿蒙珍宠，明眸转珠辉。兰心慧质出名门，吴兴才女沈珍珠。”"});
  后宫名人.push({id:86,_code:2086,性格:[30,37],名称:"文姜",家族:"姜",党:0,跳:86,统帅:10,武力:11,智力:72,政治:72,魅力:94,清廉:45,野心:43,性别:1,文化:8,介绍:"鲁文姜，齐僖公之女，齐襄公的异母妹妹。有名的美女和才女。但更令她闻名的是她与齐襄公的乱论之恋。齐襄公还曾为了她杀掉了她的夫君鲁桓公。"});
  后宫名人.push({id:87,_code:2087,性格:[11,12],名称:"谢阿蛮",家族:"谢",党:0,跳:87,统帅:11,武力:14,智力:73,政治:73,魅力:93,清廉:45,野心:44,性别:1,文化:8,介绍:"谢阿蛮，谢阿蛮擅长《凌波舞》，凌波池中卫宫护驾的龙女，安史之乱时流落民间，至德二载夏入宫重见唐玄宗，再舞《凌波舞》。"});
  后宫名人.push({id:88,_code:2088,性格:[18,40],名称:"王玉燕",家族:"王",党:0,跳:88,统帅:14,武力:16,智力:81,政治:74,魅力:91,清廉:67,野心:45,性别:1,文化:8,介绍:"字玳梁，江苏丹徒人，清代嘉庆间女书画家，云南临安知府、书法家王文治孙女，书有祖风，工诗画，常以草汁画兰，婉丽可喜，擅长梅花水仙。"});
  后宫名人.push({id:89,_code:2089,性格:[3,5],名称:"朱佛女",家族:"朱",党:0,跳:89,统帅:15,武力:17,智力:85,政治:55,魅力:91,清廉:89,野心:26,性别:1,文化:8,介绍:"明仁祖朱世珍与淳皇后陈氏之女，太祖朱元璋的姐姐。昔年太祖家贫，她孝顺知理，纺织刺绣，补贴家用。江南淮安有富户，其家少爷李贞有仪范，明志节，慕而迎娶，生子名文忠。"});
  后宫名人.push({id:90,_code:2090,性格:[15,40],名称:"李师儿",家族:"李",党:0,跳:90,统帅:16,武力:18,智力:76,政治:76,魅力:91,清廉:56,野心:47,性别:1,文化:8,介绍:"金章宗完颜璟的宠妃，位列“元宸贵惠”四妃之首。她出身贫贱，早年没入宫籍监。及长，肌映流霞，足翘细笋，眉黛远山，面似银月，白昼端相，娇艳尤绝。章宗性喜汉学风雅、厌怠女真族姬，唯独与此区区一介宫婢情意相通、绾结同心。师儿初称昭容，次年就进封元妃。她的父亲李相也扶摇直上，授爵陇西郡公、领上柱国。"});
  后宫名人.push({id:91,_code:2091,性格:[9,16],名称:"戴九莲",家族:"戴",党:0,跳:91,统帅:17,武力:19,智力:77,政治:77,魅力:83,清廉:87,野心:48,性别:1,文化:8,介绍:"《红高粱》女主角，余占鳌的妻子，带领队伍将日本鬼子引到了高粱地，点燃红高粱与敌人同归于尽，用自己的生命在这片充满生命力的山东高密大地上撰写了爱与征服。"});
  后宫名人.push({id:92,_code:2092,性格:[29,35],名称:"霍成君",家族:"霍",党:0,跳:92,统帅:40,武力:20,智力:80,政治:76,魅力:92,清廉:85,野心:90,性别:1,文化:8,介绍:"西汉大司马、大将军、博陆侯霍光的小女儿，汉宣帝刘询的第二任皇后。本始三年（前71年），霍成君的母亲霍显派女医淳于衍害死皇后许平君后，将她送进皇宫，成为汉宣帝的第二任皇后。地节四年（前66年）七月，霍家发动政变未遂，招致灭族，霍家子孙及霍显都被诛杀。同年八月，汉宣帝以阴谋毒害太子刘奭为由，废黜霍成君皇后之位，将其迁往上林苑的昭台宫居住。五凤四年（公前54年），汉宣帝下令将其迁往云林馆居住，霍成君自杀，葬于昆吾亭东。"});
  后宫名人.push({id:93,_code:2093,性格:[3,25],名称:"小龙女",家族:"龙",党:0,跳:93,统帅:69,武力:91,智力:89,政治:49,魅力:91,清廉:85,野心:40,性别:1,文化:8,介绍:"出自金庸所著武侠小说《神雕侠侣》中的人物。她清冷性傲，秀丽绝俗，明眸流转，风致嫣然。其拜入古墓派门下、师祖林朝英，自幼修习玉女心经，收养了彼时幼小的杨过，传授其武功，被唤作“姑姑”。"});
