  后宫名人.push({id:176,_code:2176,性格:[11,12],名称:"碧瑶",家族:undefined,党:0,跳:176,统帅:35,武力:74,智力:90,政治:83,魅力:92,清廉:86,野心:20,性别:1,文化:8,介绍:"碧瑶，国产小说《诛仙》及其衍生作品中的女主角。魔教鬼王宗少宗主，仙姿仪容，灵气逼人，博闻广识，妙颜无双。为救爱人张小凡使用“痴情咒”，以身挡下“诛仙剑阵”，三魂六魄受九幽之苦。一魄被扣入合欢铃，不老不死。后十年，张小凡为救碧瑶化为鬼厉寻觅救治之法。狐岐山崩塌时碧瑶的身体失踪，只留下一角绿色衣裳。全书尾，张小凡带着碧瑶的绿色衣角和一个普通铃铛在草庙村隐居。"});
  后宫名人.push({id:177,_code:2177,性格:[19,27],名称:"王清惠",家族:"王",党:0,跳:177,统帅:12,武力:14,智力:68,政治:45,魅力:84,清廉:78,野心:29,性别:1,文化:8,介绍:"王清惠，约活动于宋度宗咸淳至元世祖至元（1265—1294）前后。宋度宗昭仪。恭帝德佑二年（1276），临安（今浙江杭州）沦陷，随三宫一同被俘往元都，后自请为女道士，号冲华。现存诗四首，词一首，皆融个人遭遇与国破家亡、去国怀乡于一炉，为亡国遗民长歌当哭之作，格调低回悲壮。"});
