  后宫名人.push({id:185,_code:2185,性格:[40,4],名称:"王贞仪",家族:"王",党:0,跳:185,统帅:24,武力:16,智力:60,政治:60,魅力:80,清廉:40,野心:40,性别:1,文化:8,介绍:"女数学家王贞仪(1768－1797 )，字德卿，安徽天长人，迁居江宁府上元县（今江苏南京）。是清代学者王锡琛之女，著有《西洋筹算增删》一卷、《重订策算证讹》一卷、《象数窥余》四卷、《术算简存》五卷、《筹算易知》一卷。从她遗留下来的著作可以看出，她是一位从事天文和筹算研究的女数学家。"});
  后宫名人.push({id:186,_code:2186,性格:[0,5],名称:"李明达",家族:"李",党:0,跳:186,统帅:32,武力:23,智力:95,政治:40,魅力:91,清廉:80,野心:23,性别:1,文化:8,介绍:"唐太宗李世民与文德皇后之女，封晋阳公主，乳名兕子。皇后去世后由太宗亲自抚养，是唐太宗最为疼爱的女儿。"});
  后宫名人.push({id:187,_code:2187,性格:[7,8],名称:"王惠风",家族:"王",党:0,跳:187,统帅:27,武力:19,智力:60,政治:45,魅力:91,清廉:88,野心:40,性别:1,文化:8,介绍:"王惠风，字惠风。父亲王衍是当时大名士、著名清谈家。惠风早年聘为晋惠帝太子司马遹的太子妃。公元299年，愍怀太子（即司马遹）的事件，王衍怕牵连自己，上表惠帝，请求女儿王惠风与太子离婚。惠风却是个贞婉有志节的女子，号哭着回家。后王惠风落入汉国刘曜手中。刘曜将王惠风赏给自己手下的将领乔属。乔属想强暴她。王惠风拔剑反抗，怒斥：“我是太尉公之女，皇太子之妃，宁可为义而死，不为胡虏所辱！”乔属大怒，将她杀害。《晋书》将王惠风列入“列女传”中。"});
  后宫名人.push({id:188,_code:2188,性格:[29,13],名称:"种时光",家族:"种",党:0,跳:188,统帅:10,武力:10,智力:60,政治:42,魅力:92,清廉:88,野心:81,性别:1,文化:8,介绍:"南唐烈祖李昪的宠妃。本为后宫乐部官伎，得到李昪的临幸，生皇子李景逷，此后得宠日盛，封为夫人。姿容出众，“常靓庄去饰，而态度娴雅，宛若神仙。”。李昪的长子李璟喜欢音乐，有一次李昪见他正在弹琴，大怒斥责。种氏侍宠趁机说其子景逷的才识超过李璟。李昪知道她有政治野心，大怒，斥下殿，除去簪饰，幽于别宫。数月后，令其出家为尼。"});
