  后宫名人.push({id:192,_code:2192,性格:[0,17],名称:"何仙姑",家族:"何",党:0,跳:192,统帅:20,武力:60,智力:72,政治:43,魅力:93,清廉:56,野心:40,性别:1,文化:8,介绍:"汉族民间传说中的八仙之一，苦修积善才修练成仙，是世传八仙中唯一的女性，原型为一个容貌非凡的女性，经常手持荷花。"});
  后宫名人.push({id:193,_code:2193,性格:[6,29],名称:"嬿婉",家族:"魏佳",党:0,跳:193,统帅:12,武力:11,智力:80,政治:45,魅力:92,清廉:88,野心:40,性别:1,文化:8,介绍:"正黄旗包衣魏氏，清高宗爱新觉罗弘历的宠妃，生仁宗颙琰。乾隆四十年抬旗入镶黄旗满洲，仁宗年间改姓魏佳。她是内务府大臣武士宜之孙，内管领魏清泰之女。乾隆六年，采选入侍，为孝贤皇后斫教养者，约九年，仰沐天恩而封贵人。十年正月封令嫔，十三年五月称令妃，二十四年腊月累进令贵妃。三十年二月、乌拉那拉皇后宫权尽罢，五月、上册魏佳氏为皇贵妃，代行母仪。"});
  后宫名人.push({id:194,_code:2194,性格:[0,2],名称:"容音",家族:"富察",党:0,跳:194,统帅:24,武力:18,智力:80,政治:45,魅力:92,清廉:87,野心:11,性别:1,文化:18,介绍:"满洲镶黄旗富察氏，清高宗爱新觉罗·弘历的元后。她是察哈尔总管李荣保之女，姿容窈窕，秉性恭俭。雍正四年，指婚四阿哥弘历为嫡福晋。五年七月，在重华宫圆礼，世宗帝后与熹妃亲临。乾隆元年，册立长春宫皇后，恩爱笃挚。其子二阿哥永琏，出自正嫡，惜则早殇，追赠端慧皇太子；其女三公主和敬，聪颖殊常，然则远嫁，联姻蒙古科尔沁。十二年，其所出幼子、七阿哥永琮出痘夭折。富察皇后悲悼成疾，仍执意随帝东巡、以维母仪。"});
  后宫名人.push({id:195,_code:2195,性格:[18,20],名称:"李上真",家族:"李",党:0,跳:195,统帅:15,武力:11,智力:93,政治:70,魅力:90,清廉:82,野心:27,性别:1,文化:8,介绍:"五代十国时期后唐明宗李嗣源的女儿、末帝李从珂之姊，也是后晋高祖石敬瑭的皇后、少帝石重贵之母。其生经历三朝迭代，从公主、皇后、皇太后到乡野村妇，亦足称是乱世中传奇的一笔。"});
