  后宫名人.push({id:197,_code:2197,性格:[6,19],名称:"师妃暄",家族:"师",党:0,跳:197,统帅:18,武力:10,智力:78,政治:45,魅力:90,清廉:45,野心:4,性别:1,文化:8,介绍:"《大唐双龙传》中 “慈航静斋”圣女，为背负正邪两道最大门派历史使命的绝世美女，最后帮助李世民登上帝位，是扶持大唐统一天下的正道势力代表。"});
  后宫名人.push({id:198,_code:2198,性格:[19,17],名称:"娥皇",家族:"伊祁",党:0,跳:198,统帅:34,武力:76,智力:70,政治:50,魅力:95,清廉:56,野心:25,性别:1,文化:8,介绍:"娥皇，又称娥肓、倪皇、后育、娥盲、娥娙，上古汉族神话传说中帝舜的妻子，部落酋长唐尧伊祁放勋的长女，和妹妹女英同时嫁给了虞舜姚重华，娥皇无子。舜父顽，母嚣，弟劣，曾多次欲置舜于死地，因娥皇、女英的帮助而脱险。后舜帝南巡苍梧而死。二妃千里寻夫，知舜已死，抱竹痛哭，竹上生斑，泪尽而死，因称“潇湘竹”或“湘妃竹”。"});
  后宫名人.push({id:199,_code:2199,性格:[12,18],名称:"女英",家族:"伊祁",党:0,跳:199,统帅:25,武力:69,智力:70,政治:50,魅力:93,清廉:56,野心:25,性别:1,文化:8,介绍:"女英出身于伊祁氏部族，上古有五帝，颛顼、帝俊、尧、舜、禹。她是尧的次女、有姊娥皇，在父亲将尊位禅让给舜后，其姐妹又成为舜的妻室，她生有一子名商均。舜南巡苍梧而逝，其与姊千里寻夫，在舜的逝地九嶷山抱竹痛哭，竹上生斑，泪尽而终。"});
  后宫名人.push({id:200,_code:2200,性格:[2,9],名称:"伏寿",家族:"伏",党:0,跳:200,统帅:40,武力:17,智力:89,政治:76,魅力:94,清廉:86,野心:50,性别:1,文化:8,介绍:"汉献帝皇后，徐州琅邪郡东武县（今山东诸城）人，父亲是学者伏完，母为阳安长公主刘华，出身高贵。早年李傕、郭汜作乱时与献帝相伴共苦，受尽磨难。后曹操专权、目无君上，伏皇后下密诏欲联合父亲共讨逆贼，后事情败露，献帝为求自保不愿相救，被曹操囚于掖庭暴室，幽禁去世，所生的两位皇子亦以毒酒毒杀。。"});
  后宫名人.push({id:201,_code:2201,性格:[40,26],名称:"唐琬",家族:"唐",党:0,跳:201,统帅:23,武力:6,智力:80,政治:50,魅力:89,清廉:86,野心:6,性别:1,文化:8,介绍:"唐琬，字蕙仙，陆游母舅唐诚女儿，自幼文静灵秀，才华横溢。她是陆游的第一任妻子，与陆游两情相悦，后因陆母偏见而被拆散。她也因此写下著名的《钗头凤》（世情薄），写下《钗头凤》不久后，一代佳人唐婉便香消玉殒，抑郁而终。也因此而有了陆游众多纪念佳人的千古绝唱。"});
  后宫名人.push({id:202,_code:2202,性格:[11,14],名称:"霍云歌",家族:"霍",党:0,跳:202,统帅:25,武力:69,智力:70,政治:50,魅力:85,清廉:56,野心:10,性别:1,文化:8,介绍:"霍去病和狼女金玉之女，生于大漠，长于四海。云歌性活泼、精灵手巧，厨艺非凡，于情感事件上缺乏明确的态度，小儿女心态过甚，但云歌渴求专一的感情，实与现代女孩无异。"});
  后宫名人.push({id:203,_code:2203,性格:[5,17],名称:"如懿",家族:"乌拉那拉",党:0,跳:203,统帅:40,武力:17,智力:89,政治:76,魅力:91,清廉:86,野心:35,性别:1,文化:18,介绍:"满洲正黄旗乌拉那拉氏，清高宗爱新觉罗·弘历的继后。她是正黄旗佐领讷尔布之女，沉静温润，女中光华。"});
  后宫名人.push({id:204,_code:2204,性格:[40,36],名称:"贺兰敏月",家族:"贺兰",党:0,跳:204,统帅:34,武力:26,智力:70,政治:50,魅力:95,清廉:56,野心:75,性别:1,文化:8,介绍:"魏国夫人贺兰氏，名不详（一说敏月实乃杜撰）。父贺兰越石，母韩国夫人武顺，兄贺兰敏之。贺兰氏是武则天外甥女，唐高宗李治的情人。唐高宗朝，其母韩国夫人可以自由的出入宫廷，而女儿也是姿色艳美，唐高宗对母女二人皆宠之。韩国夫人卒，贺兰氏被封为魏国夫人，唐高宗封禅泰山后，魏国夫人被姨母武则天毒杀，并嫁祸给她的异母兄弟武惟良、武怀运。"});
  后宫名人.push({id:205,_code:2205,性格:[6,13],名称:"曹野那",家族:"曹",党:0,跳:205,统帅:25,武力:39,智力:74,政治:55,魅力:89,清廉:72,野心:30,性别:1,文化:11,介绍:"粟特族人，唐玄宗晚年的宠妃。她是西域胡姬，出身“昭武九姓”——安、史、曹、康、石、米、何、火寻、戊地之“曹”氏，盖与安禄山、史思明为同族。曹野那歌舞精妙，尤善胡旋舞，堪称当世一绝。自入唐宫，恩宠一时之盛，后渐没于平平。有女李虫娘，代宗年间始封寿安公主。"});
  后宫名人.push({id:206,_code:2206,性格:[18,27],名称:"夏淑吉",家族:"夏",党:0,跳:206,统帅:34,武力:76,智力:74,政治:35,魅力:82,清廉:72,野心:10,性别:1,文化:8,介绍:"夏淑吉，约活动于南明弘光至清顺治前后。字荆影，一字美南，号龙隐，华亭（今上海）人，明吏部考功司郎中夏允彝长女，夏完淳的同父异母姐，嘉定侯玄洵妻。夏淑吉“善琴工弈，励志操，善词赋”，极富文采。夏淑吉在父亲和弟弟死后，出家为尼，面对孤灯古佛了此一生。"});
  后宫名人.push({id:207,_code:2207,性格:[0,1],名称:"李丽质",家族:"李",党:0,跳:207,统帅:25,武力:39,智力:84,政治:65,魅力:93,清廉:82,野心:30,性别:1,文化:8,介绍:"唐太宗李世民之女，封长乐公主。她是长孙皇后的长女，容色殊丽，敏慧有智，工于书画。贞观七年，下嫁自己的表兄，齐国公长孙无忌的嫡长子、宗正少卿长孙冲。太宗出于对这位掌上明珠的宠爱而谕加礼部，使其嫁妆竟倍于皇姑、高祖李渊第六女永嘉公主；宰相魏徵以此因私废礼、逾越宗法典制而顶撞龙颜、刚正直谏，终使归循礼法。公主婚后与夫琴瑟韵合，谨礼持家。"});
  后宫名人.push({id:208,_code:2208,性格:[17,6],名称:"杨少妁",家族:"杨",党:0,跳:208,统帅:34,武力:26,智力:79,政治:55,魅力:91,清廉:81,野心:30,性别:1,文化:8,介绍:"朝齐王李元吉的王妃。她是隋观国公杨恭仁之女，夭桃秾李逸仙姿，宛转蛾眉足风流。武德九年，元吉遭尉迟敬德所杀，血溅玄武门。居丧未久，应旨入宫。她在宫邀有盛宠，生曹王李明、皇子女中序齿最幼。长孙故逝，望图继后。魏徵跪谏曰：“陛下方比德尧舜，奈何以文嬴自累”！二十一年薨，太宗旨将之与先弟归葬，而令曹王出继元吉之嗣，史称巢刺王妃。"});
  后宫名人.push({id:209,_code:2209,性格:[8,4],名称:"石青璇",家族:"石",党:0,跳:209,统帅:20,武力:60,智力:70,政治:30,魅力:88,清廉:67,野心:60,性别:1,文化:8,介绍:"《大唐双龙传》小说里的绝世美女，气质清纯脱俗，不食人间烟火，与徐子陵互生情愫，最后携手共度。"});
  后宫名人.push({id:210,_code:2250,性格:[40,5],名称:"李舜弦",家族:"李",党:0,跳:250,统帅:26,武力:23,智力:78,政治:52,魅力:92,清廉:73,野心:22,性别:1,文化:20,介绍:"梓州人氏，五代十国时期前蜀后主王衍的昭仪。她有波斯血统，晓文工诗，尤善七律。有赞云：“天潢珠润，圆折浮夜光之采；若木分晖，秾华照朝阳之色”。其兄李珣亦素有才子之名。舜弦有佳作云：“浓树禁花开后庭，饮筵中散酒微醺。蒙蒙雨草瑶阶湿，钟晓愁吟独倚屏”——后世诗家品评，中以“禁”字所用犹妙，使人拍案叫绝。"});
  后宫名人.push({id:211,_code:2251,性格:[0,9],名称:"林徽因",家族:"林",党:0,跳:251,统帅:67,武力:24,智力:95,政治:73,魅力:90,清廉:84,野心:23,性别:1,文化:8,介绍:"林徽因，女，汉族，福建闽县（今福州）人，出生于浙江杭州。容貌姣好，才华横溢，是民国时期的四大美人之首，在诗歌方面有着极高的天赋。"});
