  后宫名人.push({id:214,_code:2254,性格:[14,12],名称:"陆小曼",家族:"陆",党:0,跳:254,统帅:53,武力:27,智力:88,政治:76,魅力:90,清廉:87,野心:26,性别:1,文化:8,介绍:"民国时期女作家、画家、翻译家。"});
  后宫名人.push({id:215,_code:2255,性格:[3,9],名称:"胡蝶",家族:"胡",党:0,跳:255,统帅:31,武力:28,智力:79,政治:57,魅力:90,清廉:78,野心:27,性别:1,文化:8,介绍:"民国内地女演员。中国第一位“电影皇后”。"});
  后宫名人.push({id:216,_code:2256,性格:[40,5],名称:"纪映淮",家族:"纪",党:0,跳:256,统帅:42,武力:29,智力:78,政治:68,魅力:95,清廉:79,野心:18,性别:1,文化:8,介绍:"明思宗崇祯年间女诗人，字冒青、乳名阿囡。其父纪青，字竺远，少为诸生，地方名士；母刘玉涵，苏州吴江人，世代官宦；兄纪映钟，字伯紫，颇负诗名，多有著述。映淮性情贞静，通经史，尤工韵语，对百家典籍娓娓道来间、如数家珍，是故博闻强记如此。"});
  后宫名人.push({id:217,_code:2257,性格:[19,26],名称:"钱锦鸾",家族:"钱",党:0,跳:257,统帅:43,武力:20,智力:71,政治:69,魅力:88,清廉:80,野心:29,性别:1,文化:8,介绍:"明英宗朱祁镇的皇后。正统十四年，土木堡惊变，御驾亲征的英宗被蒙古所俘，时讯传来，前朝汲于拱卫京师，后宫哀戚愁云惨淡。她日夜为丈夫在佛祖像前祈福，跪地不起，致残一腿，连日哀哭不止，致盲一目。次年蒙军大败，礼送英宗还朝。她与丈夫被幽囚南宫，久历七载寒暑，饱尝人情冷暖、世态炎凉。天顺元年，英宗复辟，重返中宫。成化元年，进尊太后。"});
  后宫名人.push({id:218,_code:2258,性格:[0,29],名称:"周莹",家族:"周",党:0,跳:258,统帅:64,武力:31,智力:88,政治:80,魅力:97,清廉:81,野心:30,性别:1,文化:8,介绍:"清朝末年女性企业家，字竹君。她出身清贫，天资聪颖，精于算数，嫁泾阳大户吴家的少爷吴聘。在吴家的男主人相继去世后，周莹以女流之身肩挑家业。她任用贤能，多谋善断，以盐商起家，使吴家商铺自陕西遍及各地，后先后涉足丝绸、药材、茶业等，日滚万利。至光绪年间，她已晋身秦商之首，成为陕甘一域女首富。"});
  后宫名人.push({id:219,_code:2259,性格:[17,27],名称:"婉容",家族:"郭络罗",党:0,跳:259,统帅:25,武力:21,智力:85,政治:41,魅力:88,清廉:82,野心:31,性别:1,文化:18,介绍:"满洲正白旗郭络罗氏，清逊帝爱新觉罗·溥仪的皇后。她是总管内务府大臣荣源之女，字慕鸿、号植莲。民国十一年选秀，她与蒙古镶黄旗额尔德特·文绣同时参选，溥仪本钟意文绣，然而她在瑾贵太妃的支持下终登后位，册立储秀宫皇后。她思想开放，喜好西学，溥仪曾为她取名为伊丽莎白，而淑妃文绣则遭到冷落。民国十三年十月，冯玉祥迫溥仪离宫，宣告废其帝号、婉容后号亦废，迁居天津静园。"});
  后宫名人.push({id:220,_code:2260,性格:[40,9],名称:"文绣",家族:"额尔德特",党:0,跳:260,统帅:36,武力:20,智力:88,政治:62,魅力:82,清廉:83,野心:32,性别:1,文化:10,介绍:"蒙古镶黄旗额尔德特氏，清逊帝爱新觉罗·溥仪的妃嫔。她是内务府主事端恭之女，字蕙心、号爱莲。民国十一年清宫选秀，其与满洲正白旗郭络罗·婉容同时参选，溥仪本钟情于她，然而婉容终登后位，她遂封长春宫淑妃。文绣温婉智识，娴静有礼，素居敦朴，外柔内刚，不以主仆阶级为囿，曾教宫女识字读书。十三年十月，冯玉祥驱逐溥仪离宫，满清皇室自此永远地退出了紫禁城。二十年，在天津法院向溥仪提出离婚诉讼，时称“皇妃革命”。"});
  后宫名人.push({id:221,_code:2261,性格:[31,39],名称:"高晞月",家族:"高",党:0,跳:261,统帅:29,武力:28,智力:72,政治:63,魅力:88,清廉:82,野心:90,性别:1,文化:8,介绍:"慧贤皇贵妃，高佳氏，大学士高斌女。事高宗潜邸，为侧室福晋。乾隆初，为贵妃，晋皇贵妃。薨，谥曰慧贤皇贵妃。葬胜水峪。"});
  后宫名人.push({id:222,_code:2262,性格:[12,6],名称:"戚阿懿",家族:"戚",党:0,跳:262,统帅:10,武力:10,智力:59,政治:44,魅力:90,清廉:21,野心:90,性别:1,文化:8,介绍:"即戚夫人，秦末定陶人，深得刘邦的宠爱，自恃得宠，经常哭闹，在枕边细语要刘邦改立太子，欲从吕后手中夺取儿子的继承权，且屡次陷害汉惠帝、鲁元公主，欲将置其于死地，吕后因此十分痛恨戚夫人，对她恨之入骨。在刘邦死后被吕雉制成人彘，数天之后惨死于摧残中。"});
  后宫名人.push({id:223,_code:2263,性格:[4,6],名称:"李彦君",家族:"李",党:0,跳:263,统帅:23,武力:18,智力:73,政治:73,魅力:93,清廉:82,野心:20,性别:1,文化:8,介绍:"汉武帝刘彻的皇后，史称“李夫人”。祖辈皆平民、家清徒四壁，唯国色天成、使蓬荜生辉。她幼同兄长延年入籍汉乐府，郎鼓乐、妾曼吟。飘然影旋回雪轻，嫣然娇送游龙惊；从风绮袖戏杨柳，映日花钿云欲生。公元前112年，她凭一曲“北方有佳人，遗世而独立；一顾倾人城，再顾倾人国”见幸于天子，成就了世间流传的“倾国倾城”。前101年，寝疾沉疴，容颜病颓，思言：“以色事人者，色衰而爱弛，爱弛则恩绝”至死拒见武帝一面。"});
  后宫名人.push({id:224,_code:2264,性格:[0,10],名称:"刘妧娙",家族:"刘",党:0,跳:264,统帅:43,武力:25,智力:83,政治:76,魅力:88,清廉:89,野心:30,性别:1,文化:8,介绍:"汉武帝刘彻之女，封鄂邑大长公主。她姿容端庄，德望甚高，处事周谨，颇有见地。因是盖夫人所出，多以“盖主”呼之，嫁乐成侯丁义。"});
  后宫名人.push({id:225,_code:2265,性格:[5,4],名称:"赵玉漱",家族:"赵",党:0,跳:265,统帅:20,武力:38,智力:79,政治:42,魅力:89,清廉:78,野心:53,性别:1,文化:8,介绍:"宋仁宗赵祯第十女，封鲁国大长公主，中国历史最长寿的公主。仁宗嘉祐四年五月廿五，降诞皇城潜龙宫，昭淑贵妃周氏所出。英宗治平四年，帝封皇妹为庆寿公主，嫁配彭城郡王钱景臻为妻。"});
  后宫名人.push({id:226,_code:2266,性格:[1,6],名称:"甄定徽",家族:"甄",党:0,跳:266,统帅:26,武力:76,智力:63,政治:44,魅力:80,清廉:67,野心:20,性别:1,文化:8,介绍:"辽世宗耶律阮的皇后。她是辽朝两百余年间，唯一非出身于后族萧氏、却因帝王恩宠得册立的皇后，更是绝无仅有的汉女皇后。盖其先历后唐、后晋两朝后宫，才情敏慧、仪态万方，桃李夭夭、为之逊色"});
  后宫名人.push({id:227,_code:2267,性格:[40,26],名称:"易睐娘",家族:"易",党:0,跳:267,统帅:25,武力:22,智力:77,政治:51,魅力:89,清廉:72,野心:11,性别:1,文化:8,介绍:"明思宗崇祯年间画家，字醉香。她幼敏慧，工刀札，善作花鸟小图，尝临摹“画圣”吴道子之作，颇得“吴带当风”之气韵。其家世居舜水镇，家藏甚丰，后嫁言姓夫家。言郎贪色无状，寻欢觅乐红粉窟，千金销魂春宵度。睐娘郁郁而终，卒年二十四岁。"});
  后宫名人.push({id:228,_code:2268,性格:[2,14],名称:"李文懿",家族:"李",党:0,跳:268,统帅:15,武力:24,智力:82,政治:66,魅力:90,清廉:79,野心:21,性别:1,文化:8,介绍:"唐懿宗李漼长女，母郭淑妃，封同昌公主。公主深得圣宠，宠溺无比，册封同昌公主。咸通九年，下嫁起居郎韦保衡，礼仪甚盛。豪华程度，终唐一朝，绝无仅有。新婚的第二年，公主曾经白日小睡，梦一绛衣女致语云“南齐潘淑妃，来取吾之九鸾钗”，骤惊而梦醒，此后一病不起。咸通十年，公主去世，时年二十一岁。唐懿宗悲痛至极，自制挽歌，恸哭不已，追赠卫国公主，谥号文懿。"});
  后宫名人.push({id:229,_code:2269,性格:[2,17],名称:"胡善祥",家族:"胡",党:0,跳:269,统帅:15,武力:21,智力:72,政治:66,魅力:86,清廉:89,野心:11,性别:1,文化:8,介绍:"明宣宗朱瞻基的废后，锦衣卫指挥使胡荣之女。永乐十五年，皇太孙朱瞻基及冠礼，成祖以钦天监所奏吉兆应在济河，钦选她为皇太孙妃。洪熙年间，进太子妃；宣德年间，正位中宫。她性情端静，恭慎贤谨，无所过失，时当贵妃孙氏与其争宠。宣德三年，诏谕废后，贬称静慈仙师，退居长安宫。"});
  后宫名人.push({id:230,_code:2270,性格:[17,21],名称:"哲哲",家族:"博尔济吉特",党:0,跳:270,统帅:24,武力:18,智力:80,政治:31,魅力:88,清廉:81,野心:71,性别:1,文化:18,介绍:"蒙古博尔济吉特氏，清太宗爱新觉罗·皇太极的皇后。明万历四十二年，皇太极为谋蒙古支持，乃政治联姻科尔沁，娶宰桑贝勒之女哲哲为妻。后金天聪元年，夫承汗位，故进大福晋。"});
  后宫名人.push({id:231,_code:2271,性格:[31,29],名称:"阿巴亥",家族:"乌拉那拉",党:0,跳:271,统帅:24,武力:18,智力:80,政治:45,魅力:92,清廉:87,野心:61,性别:1,文化:18,介绍:"海西女真乌拉那拉氏，清太祖爱新觉罗·努尔哈赤的大福晋。明万历二十九年，乌拉部贝勒布占泰将侄女送入建州。她丰姿貌美，巧于机变。仅二年，居大妃位，年仅十四。公元1616年，太祖建后金，改元天命，分封八旗贝勒。她有三子，多尔衮最得父心，常伴左右，属意栽培。"});
  后宫名人.push({id:232,_code:2272,性格:[0,4],名称:"娜木钟",家族:"博尔济吉特",党:0,跳:272,统帅:14,武力:22,智力:75,政治:22,魅力:96,清廉:87,野心:11,性别:1,文化:10,介绍:"博尔济吉特氏，清太宗爱新觉罗·皇太极的妃嫔。蒙古阿霸垓郡王额齐格诺颜之女，本为蒙古察哈尔部林丹汗多罗大福晋（正室大福晋）。为林丹汗的八大福晋之首，称“囊囊福晋”，统管阿纥土门万户斡尔朵。娜木钟率部众归顺后金，亦被皇太极立为侧福晋。崇德元年皇太极在盛京称帝，钦定国号为清，受封西宫贵妃，居麟趾宫，位居崇德五宫后妃的第三位。"});
  后宫名人.push({id:233,_code:2273,性格:[12,35],名称:"锦琢",家族:"他他拉",党:0,跳:273,统帅:24,武力:18,智力:60,政治:20,魅力:93,清廉:37,野心:11,性别:1,文化:18,介绍:"满洲镶红旗他他拉氏，清德宗爱新觉罗·载湉的宠妃。她在光绪十四年选秀入宫，十五年封珍嫔，二十年晋珍妃，同年因忤逆慈禧太后遭褫衣廷杖，降珍贵人，次年因帝宠复进珍妃。二十四年，戊戌变法事败，慈禧将光绪软禁在瀛台，并将珍妃幽囚于钟粹宫之北三所。二十六年，八国联军入侵北京，慈禧行前命将珍妃投井，时年二十五岁。"});
  后宫名人.push({id:234,_code:2274,性格:[19,18],名称:"佟姝嬛",家族:"佟",党:0,跳:274,统帅:22,武力:19,智力:70,政治:21,魅力:90,清廉:81,野心:11,性别:1,文化:8,介绍:"汉军正蓝旗佟氏，清世祖爱新觉罗·福临的妃嫔，生圣祖玄烨。她在顺治十年二月选秀入宫，圣眷日隆，五月便传出孕信，中宫妒恨深，八月世祖诏废皇后；十一年三月诞玄烨，恩晋康妃、正景仁宫主位，时人多揣圣意以其为继立，然五月孝庄太后懿旨废后之侄入宫，次月即圆大婚。十三年董鄂妃入，她前已失势旋又失宠。"});
  后宫名人.push({id:235,_code:2275,性格:[17,7],名称:"李渐荣",家族:"李",党:0,跳:275,统帅:34,武力:24,智力:80,政治:55,魅力:90,清廉:87,野心:11,性别:1,文化:8,介绍:"长安人氏，唐昭宗李晔的昭仪，位冠九嫔之首。公元904年，宣武军节度使朱温密谋弑帝，遣亲信部将蒋玄晖闯宫。时昭宗醉梦椒兰殿，左右仅有昭仪李渐荣、修仪裴贞一伴驾在侧。是夜，兵变事发！裴贞一先行出称昭宗业已安寝，言道：“急奏不应以猝来”，阻蒋入殿，被杀。李渐荣以身护驾，连呼曰：“莫伤陛下，宁杀我辈”！斧钺加身，血泪横流，贞烈而终。"});
  后宫名人.push({id:236,_code:2276,性格:[19,4],名称:"豆卢仪鸾",家族:"豆卢",党:0,跳:276,统帅:23,武力:18,智力:70,政治:35,魅力:88,清廉:67,野心:21,性别:1,文化:8,介绍:"京兆人氏，唐睿宗李旦的宠妃，玄宗李隆基、惠庄太子李捴的养母。鲜卑大姓慕容氏之后，右武卫大将军豆卢仁业之孙女，晋阳县令豆卢钦肃之女。上元三年，以良家子选入相王李旦府为孺人，时年十五。睿宗嗣位，乃册为贵妃。神龙二年，豆卢氏之伯父、宰相豆卢钦望以“妃久处禁闱”为由“特乞出内”，豆卢贵氏被恩准出宫，出居娘家。顺下翊上，言逊身全。"});
  后宫名人.push({id:237,_code:2277,性格:[3,14],名称:"秦罗敷",家族:"秦",党:0,跳:277,统帅:21,武力:12,智力:66,政治:25,魅力:92,清廉:67,野心:24,性别:1,文化:8,介绍:"汉乐府《陌上桑》与《孔雀东南飞》中均有提到。《陌上桑》写采桑女秦罗敷拒绝一“使君”即太守之类官员调戏的故事，歌颂她的美貌与坚贞的情操。“头上倭堕髻，耳中明月珠。缃绮为下裙，紫绮为上襦。行者见罗敷，下担捋髭须。少年见罗敷，脱帽着帩头。耕者忘其犁，锄者忘其锄”。《孔雀东南飞》中用“罗敷”代指美女。"});
  后宫名人.push({id:238,_code:2278,性格:[17,27],名称:"刘兰芝",家族:"刘",党:0,跳:278,统帅:21,武力:11,智力:71,政治:26,魅力:90,清廉:77,野心:12,性别:1,文化:8,介绍:"东汉献帝年间庐江郡小吏焦仲卿的发妻。她十七岁时为焦家新妇，夫妻相濡以沫，两相倾慕，琴瑟和鸣。但焦母不喜儿媳兰芝，终将其遣回娘家，并相逼儿子别娶；而刘兄贪慕权贵，认为自己的妹妹貌美柔情，当嫁官宦高门，亦迫其改嫁。新婚之夜，刘兰芝举身赴清池；焦仲卿闻之，自挂东南枝，殉情而终。时人有感二人情深似海，故作一赋；后人收录于《玉台新咏》，赋名《孔雀东南飞》。"});
  后宫名人.push({id:239,_code:2279,性格:[13,15],名称:"吴绛仙",家族:"吴",党:0,跳:279,统帅:23,武力:16,智力:67,政治:24,魅力:92,清廉:67,野心:23,性别:1,文化:8,介绍:"江都人氏，隋炀帝杨广的宠妃，封崆峒夫人。炀帝巡幸扬州，自洛阳沿大运河南下，至江南琼花两岸，水流平缓，龙舟行水迟慢，就征召姿容俊秀的少男少女为徭役，拉纤行船，谓为“江南好景”。她原是牵挽龙舟的殿脚女，姿色清丽，楚楚可怜，受炀帝所幸，帝曰：“古人云秀色可餐，如绛仙者，真可疗饥矣”。人言她善使螺子黛画眉，备受追捧，时称“绛仙眉”。"});
  后宫名人.push({id:240,_code:2280,性格:[17,6],名称:"董凤霁",家族:"董",党:0,跳:280,统帅:20,武力:13,智力:68,政治:26,魅力:87,清廉:68,野心:23,性别:1,文化:8,介绍:"唐玄宗早年的宠妃。景云元年，睿宗李旦册立皇三子李隆基为储君。依东宫妃嫔礼制，皇太子妃以下，良娣二人、视同当朝正三品，良媛六人、轶正四品。她与杨真一并册为太子良娣，甚有尊荣。开元元年，玄宗初登大宝，有诏是：“良娣董氏，门袭钟鼎，训彰礼则，美誉光於六寝。穆兹朝典，宜升徽号，封为贵妃”。"});
  后宫名人.push({id:241,_code:2281,性格:[19,4],名称:"杨真一",家族:"杨",党:0,跳:281,统帅:13,武力:12,智力:64,政治:26,魅力:87,清廉:67,野心:23,性别:1,文化:8,介绍:"唐玄宗早年的宠妃。景云元年，睿宗李旦册立皇三子李隆基为储君。依东宫妃嫔礼制，皇太子妃以下，良娣二人、视同当朝正三品，良媛六人、轶正四品。她与董凤霁并册为太子良娣，甚有尊荣。开元元年，玄宗初登大宝，有诏是：“良娣杨氏，器识柔顺，质性幽闲，令范成於四教。穆兹朝典，宜升徽号，封为淑妃”。"});
  后宫名人.push({id:242,_code:2282,性格:[5,8],名称:"杨阿五",家族:"杨",党:0,跳:282,统帅:27,武力:13,智力:68,政治:23,魅力:90,清廉:77,野心:21,性别:1,文化:8,介绍:"出身弘农杨氏，隋文帝杨坚的嫡女，封兰陵公主。她性情和孝，通晓诗书，素为帝后所钟爱。公主及笄，下嫁柳述，杨柳成姻。柳述文采斐然，质迈寒松，但性情高傲，与重臣杨素向来不睦，又卷入仁寿宫变，遭炀帝忌讳，获罪流徙南疆。杨阿五贞烈，与兄当庭对质，天威惊怒。未几，忧愤而薨，仅薄葬于长安洪渎川。"});
  后宫名人.push({id:243,_code:2283,性格:[35,29],名称:"张宠则",家族:"张",党:0,跳:283,统帅:23,武力:19,智力:69,政治:24,魅力:90,清廉:27,野心:83,性别:1,文化:8,介绍:"脩武人氏，唐高祖李渊的宠妃，字伽蓝，生郑王李元懿。她本是隋炀帝在长安大兴宫中的女婢，李渊入主隋宫后，因姿容出众而得幸，在帝年近花甲之际添一幼子，高祖深喜之，赐名元懿，亲授诗书，皇子亦聪敏好学。其晋婕妤，恃宠参与太子李建成与秦王李世民夺嫡之争，望引二王相争，从中渔利，侍奉高祖时对秦王常加诋毁，收纳东宫所赠珠宝金玉不计其数。"});
  后宫名人.push({id:244,_code:2284,性格:[18,15],名称:"李德贤",家族:"李",党:0,跳:284,统帅:26,武力:21,智力:77,政治:32,魅力:89,清廉:87,野心:21,性别:1,文化:8,介绍:"陇西李氏，唐太宗李世民之女，封清河公主。公主名敬，表字德贤，文雅贞懿，端静淑丽，温娴柔徽。其颇精书道，每有佳作，足臻能品之境。贞观七年，出降卢国公、骠骑大将军程咬金之子。程家长子怀默袭爵，次子怀亮因尚主而获封驸马都尉，名将之后，忠义凛凛。太宗甫崩，突厥异动频，高宗以其驸马挂帅，奉命出兵镇守陇西峣关。公主不辞随军劳苦，亦曾伴夫远赴边陲。"});
  后宫名人.push({id:245,_code:2285,性格:[22,17],名称:"王贞祐",家族:"王",党:0,跳:285,统帅:33,武力:26,智力:67,政治:34,魅力:87,清廉:67,野心:69,性别:1,文化:8,介绍:"出身太原王氏，唐高宗李治的废后。她家世显赫，母亲魏国夫人出身河东柳氏，舅父柳奭官至宰相。太宗贞观年间，她因同安大长公主的举荐，受聘为晋王李治嫡妻。高宗永徽二年，她为分薄萧淑妃的宠爱而主动请旨武媚娘入宫。武氏野心权谋，世所罕见，令失帝心。六年，废庶人、囚掖庭，遭武后私刑迫害致死。"});
  后宫名人.push({id:246,_code:2286,性格:[32,36],名称:"萧安思",家族:"萧",党:0,跳:286,统帅:23,武力:21,智力:67,政治:29,魅力:91,清廉:27,野心:83,性别:1,文化:8,介绍:"出身兰陵萧氏，唐高宗李治的宠妃。她初选入东宫为良娣，及帝践祚，获封淑妃，极尽奢宠。萧妃奸狡善妒，美艳绝伦，又屡有身孕，与无子的王皇后争斗不休。王氏为制衡她，转而支持尚在感业寺的武媚娘入宫。武氏为昭仪，李治专宠至深；王萧皆遭诬害，幽禁掖庭回心院。高宗偶至，二女伏跪乞怜。武后闻之，令杖刑一百，截断手足，弃于酒瓮，名曰“骨醉”，残害致死。"});
  后宫名人.push({id:247,_code:2287,性格:[18,19],名称:"赵玉盘",家族:"赵",党:0,跳:287,统帅:23,武力:11,智力:68,政治:22,魅力:87,清廉:63,野心:11,性别:1,文化:22,介绍:"汴京人氏，宋徽宗赵佶嫡长女，封嘉德帝姬。她是徽宗赵佶与继配显肃郑皇后之女，在宋朝时嫁左卫将军曾夤为妻。靖康之难，她被金太宗完颜晟的长子宗磐强霸为妾。太宗崩，遗诏太祖嫡长孙完颜亶继位。完颜宗磐意欲谋反，终遭熙宗所灭，她复被收入金廷后宫。公元1140年十二月亡故，完颜亶有宠于她，赠封夫人。"});
  后宫名人.push({id:248,_code:2288,性格:[4,17],名称:"杜陵阳",家族:"杜",党:0,跳:288,统帅:16,武力:18,智力:62,政治:31,魅力:89,清廉:81,野心:13,性别:1,文化:8,介绍:"东晋成帝司马衍的皇后。她出身侯门、是丹阳侯杜乂的贵女，史载其：“少有姿色，然长犹无齿，有来求婚者辄中止。及帝纳采之日，一夜齿尽生”。咸康二年，悉备礼、许之国后，择日入宫。成帝奕世名德，携后共御太极前殿，群臣毕贺三跪九叩。"});
  后宫名人.push({id:249,_code:2289,性格:[7,8],名称:"郑祁耶",家族:"郑",党:0,跳:289,统帅:28,武力:11,智力:78,政治:28,魅力:87,清廉:83,野心:13,性别:1,文化:8,介绍:"隋朝越国公夫人，政治家、军事家、权臣杨素的妻子。她与独孤家七小姐伽罗年岁相仿，幼结手帕交，闺谊豆蔻女，花信待含绽，娇慕英杨郎。开皇年间，杨素爵封越国公、加上柱国，宅中诸美充盈，名妓红拂等俱才色冠绝之辈。祁耶不忿，多起争执，杨素愤言：“我若作天子，卿定不堪为皇后！”她在一气之下，直闯大内，登鸣御状，使素贬官。其于重病缠身之时，独孤皇后曾接入宫中，亲问汤药。冷月映空帷，生死两苍茫。"});
  后宫名人.push({id:250,_code:2290,性格:[5,18],名称:"李下玉",家族:"赵",党:0,跳:290,统帅:22,武力:13,智力:69,政治:36,魅力:90,清廉:78,野心:18,性别:1,文化:8,介绍:"字㝹妆，唐高宗李治长女，封义阳公主。同母妹宣城公主，同母弟许王李素节。永徽二年，其母萧淑妃宠冠后廷、风头无两，王皇后为求制衡，主动奏请武氏还俗入宫；六年，武氏为后，王萧被废。虽为公主，然母尚遭横死，她被长年幽囚于掖庭。逾年不嫁，太子李弘为之奏请出降，于是下嫁翊军都尉权毅。天授二年，权毅参与了反对武后的行动被杀，年四十五。"});
  后宫名人.push({id:251,_code:2291,性格:[4,10],名称:"张玄妙",家族:"张",党:0,跳:291,统帅:23,武力:11,智力:68,政治:22,魅力:87,清廉:63,野心:13,性别:1,文化:8,介绍:"阌乡人氏，明太祖晚年的宠妃，封美人。朱元璋驾崩时，除了有子傍身、且年岁亦长的高位妃嫔外，其余的年轻貌美者，尽皆殉葬。张玄妙因其女宝庆公主时仅三岁稚龄，成为唯一获开赦的幸存者。"});
var 所有敌将= [];
  所有敌将.push({id:0,_code:4000,文化:0,被关押:0,名称:"王昭",家族:"王",性格:[8,7],地位:0,跳:0,统帅:12,武力:54,智力:88,政治:91,魅力:89,清廉:96,野心:50,抗拒:100,底线:80,性别:0,介绍:"王昭，字日华，高丽王朝第四任君主。他是高丽太祖王建第四子、高丽惠宗王武、高丽定宗王尧之弟。乾祐二年（949年）受禅即位，广顺三年（953年）被后周册封为高丽国王。他在位时致力于强化王权，颁布奴婢按检法，实行科举制度，制定百官公服，并使用独立的年号，甚至可能自称皇帝。在位后期为政苛酷，鼓励告密，大兴冤狱，屠戮功臣。同时崇尚佛教，创建归法寺等多处庙宇。"});
  所有敌将.push({id:1,_code:4001,文化:0,被关押:0,名称:"王伷",家族:"王",性格:[9,28],地位:1,跳:1,统帅:23,武力:43,智力:58,政治:53,魅力:89,清廉:27,野心:22,抗拒:100,底线:70,性别:0,介绍:"王伷，高丽王朝第五任君主。字长民，父为高丽光宗王昭，母为大穆王后皇甫氏。965年被立为太子，975年即位后平反冤狱，推行田柴科制，但沉湎享乐，在位六年即病重，禅位于堂弟王治，旋薨。"});
  所有敌将.push({id:2,_code:4002,文化:1,被关押:0,名称:"成明",家族:"",性格:[7,18],地位:0,跳:2,统帅:34,武力:32,智力:78,政治:75,魅力:85,清廉:78,野心:6,抗拒:100,底线:60,性别:0,介绍:"村上天皇，讳：成明，醍醐天皇的第十四皇子，日本第62代天皇，前任朱雀天皇。母为藤原基经之女中宫稳子。第61代朱雀天皇同母弟。村上天皇励精图治，整顿吏治，重视文化发展，使日本国泰民安，社会稳定，经济得到进一步发展。但他未能继续扩大天皇权力，在位期间摄关家势力反而不断膨胀。"});
  所有敌将.push({id:3,_code:4003,文化:2,被关押:0,名称:"咄苾",家族:"阿史那",性格:[8,9],地位:0,跳:3,统帅:84,武力:98,智力:78,政治:34,魅力:96,清廉:87,野心:50,抗拒:150,底线:50,性别:0,介绍:"颉利可汗，阿史那氏，名咄苾，突厥族，东突厥可汗启民可汗的第三子。咄苾最初担任莫贺咄设（军事统帅），武德三年，继任颉利可汗，迎娶后母隋朝义成公主为妻。秉承父兄基业，兵马强盛，阻挠唐朝统一。唐太宗即位后，突厥兵临渭水，双方实现便桥之盟，索要重金财宝，方肯退还。贞观三年（629），颉利兵败于阴山，押送进入长安，授右卫大将军。 "});
  所有敌将.push({id:4,_code:4004,文化:3,被关押:0,名称:"波罗帕羯罗伐",家族:"弹那",性格:[40,3],地位:0,跳:4,统帅:96,武力:67,智力:89,政治:86,魅力:82,清廉:94,野心:60,抗拒:150,底线:60,性别:0,介绍:"波罗帕羯罗伐弹那，意译为光增。古印度室利康塔国普什亚布蒂王朝的国王，父为阿迪蒂亚伐弹那，母为后期笈多王朝公主。曾先后战胜旁遮普西北部的白匈奴人、摩腊婆人与瞿折罗人等，号称“王中之大王”，并以女罗阇室利嫁穆克里王朝国王揭罗诃跋摩，结为姻盟对抗高达—摩腊婆联盟。"});
  所有敌将.push({id:5,_code:4005,文化:3,被关押:0,名称:"戒日王",家族:"弹那",性格:[0,2],地位:1,跳:5,统帅:97,武力:58,智力:90,政治:87,魅力:83,清廉:95,野心:61,抗拒:151,底线:61,性别:0,介绍:"戒日王，印度戒日朝国王，戒日王朝的建立者，印度古典文化的集大成者，最后一个统一了北印度的本地人国王，其统治时期是印度历史上的一个光辉的时代。他是继笈多王朝之后统一印度的著名国王，曾多次派遣使臣与中国唐朝通好；唐太宗亦派王玄策等人多次使印报聘。在他统治的40余年间，北印度相对稳定繁荣。死后，帝国开始分裂，出现了王朝林立的局面。"});
  所有敌将.push({id:6,_code:4006,文化:4,被关押:0,名称:"耶律贤",家族:"耶律",性格:[0,2],地位:0,跳:6,统帅:82,武力:74,智力:88,政治:56,魅力:90,清廉:96,野心:70,抗拒:150,底线:50,性别:0,介绍:"辽景宗耶律贤，字明扆，辽朝第五位皇帝，辽世宗耶律阮次子。幼年经历祥古山之变，丧失父母，体弱多病，得到堂叔辽穆宗的抚养。辽穆宗遇弑后，登基称帝，尊号“天赞皇帝”。在位期间厉行改革，拨乱反正，网罗人才，关心朝政、孜孜求治。对外发动了瓦桥关之战和满城之战，攻打北宋。汉化改革的范围和成效为辽圣宗时期的全面繁荣奠定了基础。在位后期，政事多委于皇后萧绰。"});
  所有敌将.push({id:7,_code:4007,文化:4,被关押:0,名称:"耶律隆绪",家族:"耶律",性格:[6,5],地位:1,跳:7,统帅:85,武力:98,智力:78,政治:80,魅力:85,清廉:78,野心:55,抗拒:100,底线:60,性别:0,介绍:"辽圣宗耶律隆绪，契丹名耶律文殊奴，辽景宗耶律贤长子，母承天皇太后萧绰。乾亨四年嗣位为皇帝，改元统和，改国号契丹。母承天皇太后萧绰奉遗诏摄政。在位期间，对内实行改革，大力整顿吏治，加强汉人的作用。使辽朝达鼎盛。对外实行联合党项抗击宋朝之策，向周邻扩张。他精射法，晓音律，好绘画买，汉文化修养颇高，史称“道、佛二教，皆洞彻其宗旨。”"});
  所有敌将.push({id:8,_code:4008,文化:5,被关押:0,名称:"段正淳",家族:"段",性格:[1,19],地位:0,跳:8,统帅:72,武力:88,智力:88,政治:43,魅力:88,清廉:96,野心:60,抗拒:100,底线:50,性别:0,介绍:"大理中宗段正淳，亦作段政淳。云南大理人，白族先民。大理保定帝段正明之弟。天授元年（1096年），接受段家禅让成为大理皇帝的高升泰迫于传统势力及佛教意识影响，临终前嘱托其子高泰明还位于段正淳。同年段正淳即位，政权仍握持于高氏。文安四年（1108年），段正淳禅位于太子段正严，出家为僧。"});
  所有敌将.push({id:9,_code:4009,文化:5,被关押:0,名称:"段和誉",家族:"段",性格:[0,5],地位:1,跳:9,统帅:93,武力:95,智力:94,政治:85,魅力:91,清廉:88,野心:12,抗拒:100,底线:60,性别:0,介绍:"段和誉，大理宪宗，文安帝段正淳之子，金庸武侠小说《天龙八部》中段誉的原型。段正严在位期间勤于政事，爱民用贤，思揽政权，远方慕之，悉来贡献。对外臣服于北宋，遣使来朝，拜金紫光禄大夫、检校司空、云南节度使、上柱国、大理国王。段正严虽励精图治，但是始终无法改变被高氏架空的局面。统治后期诸子内争外叛，于是禅位于段正兴，出家为僧。"});
  所有敌将.push({id:10,_code:4010,文化:6,被关押:0,名称:"松赞干布",家族:"刘",性格:[40,4],地位:0,跳:10,统帅:22,武力:54,智力:98,政治:90,魅力:91,清廉:86,野心:20,抗拒:150,底线:50,性别:0,介绍:"吐蕃王朝第33任赞普，是实际上吐蕃王朝的立国之君。与其王妃赤尊公主、文成公主三人，至今仍受藏族人尊崇。"});
  所有敌将.push({id:11,_code:4011,文化:7,被关押:0,名称:"君士坦丁",家族:"马其顿",性格:[17,13],地位:0,跳:11,统帅:83,武力:80,智力:96,政治:87,魅力:89,清廉:90,野心:14,抗拒:102,底线:62,性别:0,介绍:"君士坦丁八世是拜占廷皇帝罗曼努斯二世之子，其母狄奥法诺有亚美尼亚血统、前任国王巴西尔二世之弟。962年，罗曼努斯二世将君士坦丁及其兄巴西尔二世加冕成为共治皇帝。君士坦丁年青时与保加利亚国王女儿定婚，但是最后与海伦娜结婚，两人生了三个女儿欧多齐娅、佐伊及狄奥多拉，亦即后来的佐伊女皇及狄奥多拉女皇。"});
  所有敌将.push({id:12,_code:4012,文化:10,被关押:0,名称:"铁木真",家族:"孛儿只斤",性格:[7,9],地位:0,跳:12,统帅:96,武力:98,智力:92,政治:88,魅力:84,清廉:91,野心:98,抗拒:150,底线:63,性别:0,介绍:"孛儿只斤·铁木真，尊号“成吉思汗”，蒙古族乞颜部人，大蒙古国可汗，世界史上杰出的军事家、政治家。铁木真早年丧父，投奔克烈部首领脱里，积蓄实力，被推举为蒙古乞颜部可汗后经过一系列战争，统一蒙古高原诸部。1206年在斡难河源即皇帝位，建立大蒙古国。建国后，实行千户制，建立护卫军，颁布《大扎撒》。此后经过多次的对外战争，占领东亚地区金朝的大片领土，并灭亡西夏、西辽及中亚的花剌子模，其征服足迹远抵东欧的黑海海滨"});
  所有敌将.push({id:13,_code:4013,文化:10,被关押:0,名称:"窝阔台",家族:"孛儿只斤",性格:[17,2],地位:1,跳:13,统帅:84,武力:94,智力:81,政治:75,魅力:80,清廉:87,野心:80,抗拒:150,底线:50,性别:0,介绍:"孛儿只斤·窝阔台，蒙古帝国大汗，史称“窝阔台汗”。元太祖成吉思汗的第三子。1229年忽里台大会被拥戴登基，继续父亲的遗志，扩张领土，南下灭金国，派拔都远征欧洲，疆域版图曾扩充到中亚、华北和东欧。在位期间，采用汉法，并且开科取士，重用中原文人，奠定元朝的基础。窝阔台天性慷慨大方，仁爱好施，宽仁待民，他的宫廷几乎成了普天下的庇护和避难地。"});
  所有敌将.push({id:14,_code:4014,文化:10,被关押:0,名称:"拖雷",家族:"孛儿只斤",性格:[6,8],地位:2,跳:14,统帅:96,武力:98,智力:80,政治:72,魅力:87,清廉:90,野心:80,抗拒:150,底线:50,性别:0,介绍:"孛儿只斤·拖雷（Tului，蒙古语意为镜子，1193—1232年），成吉思汗孛儿只斤·铁木真第四子（幼子），尊号“也可那颜”（大官人）。"});
  所有敌将.push({id:15,_code:4015,文化:11,被关押:0,名称:"伊本",家族:"阿赫马德",性格:[0,17],地位:0,跳:15,统帅:88,武力:98,智力:90,政治:93,魅力:90,清廉:88,野心:82,抗拒:150,底线:50,性别:0,介绍:"伊本·阿赫马德，纳斯尔二世。其统治时期萨曼王朝疆域达到了鼎盛。北方的塔什干（柘析城），东北方的费尔干纳，西南方的赖伊（直到928年才归萨曼王朝），都成为萨曼王朝国家的组成部分，王朝的实际影响远至喀什噶尔。"});
  所有敌将.push({id:16,_code:4016,文化:12,被关押:0,名称:"托勒密",家族:"",性格:[26,27],地位:0,跳:16,统帅:87,武力:83,智力:87,政治:80,魅力:87,清廉:79,野心:70,抗拒:150,底线:50,性别:0,介绍:"托勒密十三世，古埃及托勒密王朝法老之一。托勒密十三世是埃及法老托勒密十二世之子，与姐姐克利奥帕特拉七世，即后世闻名的埃及艳后结婚，并共治埃及。"});
  所有敌将.push({id:17,_code:4017,文化:13,被关押:0,名称:"伊戈尔",家族:"留里科维奇",性格:[6,27],地位:0,跳:17,统帅:88,武力:73,智力:88,政治:88,魅力:82,清廉:60,野心:74,抗拒:100,底线:50,性别:0,介绍:"古罗斯王公，统治基辅的大公。伊戈尔是俄罗斯国家的第一个王朝留里克王朝的实际创建者。"});
  所有敌将.push({id:18,_code:4018,文化:13,被关押:0,名称:"斯维亚托斯拉夫",家族:"留里科维奇",性格:[0,6],地位:1,跳:18,统帅:99,武力:76,智力:88,政治:99,魅力:80,清廉:75,野心:64,抗拒:100,底线:50,性别:0,介绍:"斯维亚托斯拉夫·伊戈列维奇，古罗斯军事活动家，基辅大公。斯维亚托斯拉夫·伊戈列维奇是伊戈尔·留里科维奇大公之子，母亲是普斯科夫的奥丽加。他成年后，开始为扩张基辅罗斯的势力而连年作战，最成功的对外战争之一是彻底打败了哈扎尔人。在打败哈扎尔人之后，除了不时侵扰的宿敌佩切涅格人之外，斯维亚托斯拉夫在邻近地区已无对手。凭借这些功绩，斯维亚托斯拉夫也成为最伟大的罗斯征服者，并赢得了“勇者”的头衔。"});
  所有敌将.push({id:19,_code:4019,文化:14,被关押:0,名称:"苏耶跋摩",家族:"",性格:[30,22],地位:0,跳:19,统帅:85,武力:74,智力:98,政治:83,魅力:83,清廉:96,野心:80,抗拒:100,底线:50,性别:0,介绍:"苏耶跋摩一世，吴哥王朝国王，柬埔寨三神王之一。据说他本为单马令王子，因联姻宣称有吴哥王位，抵达真腊东部海岸，先后击败众多竞争对手，1010年正式登位为王。他身为篡位者，为巩固王位与前对手的遗孀联姻，并要求一切新旧臣僚向其效忠。之后继续向外扩张，将堕罗钵底王国、单马令王国纳入领土。他是第一位皈依大乘佛教的吴哥国王。"});
  所有敌将.push({id:20,_code:4020,文化:15,被关押:0,名称:"慕容儁",家族:"慕容",性格:[30,17],地位:0,跳:20,统帅:76,武力:75,智力:89,政治:84,魅力:89,清廉:77,野心:81,抗拒:101,底线:51,性别:0,介绍:"慕容儁，字宣英，鲜卑名贺赖跋，鲜卑族。十六国时期前燕开国皇帝。慕容儁依靠慕容恪、悦绾、慕容评等一干宗室、名将，趁着石赵崩坏后中原纷乱，灭冉魏、段齐，在军事征服中屡屡获胜，极大地扩展了前燕的版图。在扩张领土的战争中屡次获胜，进而图谋消灭东晋、前秦。统治末期，穷兵黩武，百姓凋敝，盗贼兴起。 "});
  所有敌将.push({id:21,_code:4021,文化:15,被关押:0,名称:"慕容冲",家族:"慕容",性格:[,],地位:1,跳:21,统帅:72,武力:88,智力:88,政治:43,魅力:99,清廉:96,野心:60,抗拒:100,底线:50,性别:0,介绍:"慕容冲，小字凤皇，鲜卑族，前燕景昭帝慕容儁之子，前燕幽帝慕容暐、西燕烈文帝慕容泓之弟，母皇后可足浑氏，十六国时期西燕第二位皇帝。"});
  所有敌将.push({id:22,_code:4022,文化:16,被关押:0,名称:"李元昊",家族:"李",性格:[6,28],地位:0,跳:22,统帅:99,武力:76,智力:88,政治:99,魅力:80,清廉:75,野心:64,抗拒:100,底线:50,性别:0,介绍:"李元昊，别名曩霄，小字嵬理，党项族人，西夏开国皇帝。"});
  所有敌将.push({id:23,_code:4023,文化:16,被关押:0,名称:"宁令哥",家族:"李",性格:[8,26],地位:1,跳:23,统帅:21,武力:76,智力:88,政治:35,魅力:80,清廉:75,野心:64,抗拒:100,底线:50,性别:0,介绍:"宁令哥,西夏景宗李元昊的儿子。母亲是元昊的第一任皇后野利氏。1042年，在野利皇后的请求下，被册立为皇太子。然而妻子没藏氏被父亲元昊霸占，母亲家族受到灭族，宁令哥担心受到废黜，难以忍受夺爱之恨，加上野心家没藏讹庞挑唆，于是持戈进宫刺伤元昊，而后被没藏讹庞处死。"});
  所有敌将.push({id:24,_code:4024,文化:17,被关押:0,名称:"李旵",家族:"李",性格:[16,20],地位:0,跳:24,统帅:79,武力:55,智力:81,政治:83,魅力:88,清廉:77,野心:21,抗拒:121,底线:51,性别:0,介绍:"李旵，越南李朝第八任皇帝。惠宗久病无子，只有皇后陈容所生的二个女儿：长女顺天公主和幼女昭圣公主名李天馨。天彰有道元年（1224年），李佛金受李惠宗传位，为李昭皇，时年七岁。任陈守度为辅国太尉，陈守度让其侄子陈日煚和昭皇成婚。不久，陈守度逼迫李昭皇让位于驸马陈日煚，降昭皇为昭圣皇后，改元建中。"});
  所有敌将.push({id:25,_code:4025,文化:18,被关押:0,名称:"完颜旻",家族:"完颜",性格:[0,7],地位:0,跳:25,统帅:80,武力:56,智力:82,政治:84,魅力:89,清廉:78,野心:22,抗拒:122,底线:52,性别:0,介绍:"完颜阿骨打，女真族，金朝开国皇帝。汉名旻。是女真族的伟大领袖，对金朝灭亡辽朝、统一北方具有奠基意义。 "});
  所有敌将.push({id:26,_code:4026,文化:18,被关押:0,名称:"完颜宗峻",家族:"完颜",性格:[6,9],地位:1,跳:26,统帅:71,武力:54,智力:80,政治:76,魅力:87,清廉:77,野心:20,抗拒:80,底线:50,性别:0,介绍:"完颜宗峻，女真名完颜绳果，是金太祖嫡长子、金熙宗完颜亶生父。天辅五年（1121），领合扎猛安，受金牌，与其叔父忽鲁勃极烈完颜杲取辽中京，中京既下，与杲追袭天祚帝于鸳鸯泊（今河北张北县北安固里淖）。 在取中京和救西京的战争中受伤，后在天会二年（1124年）七月死去。其子熙宗即位，追谥景宣皇帝。 "});
  所有敌将.push({id:27,_code:4027,文化:19,被关押:0,名称:"磨延啜",家族:"药罗葛",性格:[8,6],地位:0,跳:27,统帅:82,武力:95,智力:81,政治:77,魅力:88,清廉:78,野心:71,抗拒:81,底线:51,性别:0,介绍:"英武可汗，药罗葛氏，名磨延啜。回纥的第二任可汗，原称“葛勒可汗”。安史之乱爆发后，磨延啜应唐朝之邀，派长子叶护太子帮助唐朝收复两京。758年，唐朝赐葛勒可汗号“英武威远毗伽阙可汗”，简称“英武可汗”；唐肃宗将寡居的二女儿宁国公主嫁给了英武可汗。"});
  所有敌将.push({id:28,_code:4028,文化:20,被关押:0,名称:"孟昶",家族:"孟",性格:[15,14],地位:0,跳:29,统帅:62,武力:39,智力:88,政治:58,魅力:97,清廉:36,野心:20,抗拒:100,底线:50,性别:0,介绍:"孟昶，本名孟仁赞，字保元 ，五代十国时期后蜀末代皇帝。孟昶即位初年，励精图治，实行“与民休息”政策，后蜀国势强盛，将北线疆土扩张到长安。但他在位后期，沉湎酒色，不思国政，生活荒淫，奢侈无度，朝政十分腐败。后蜀广政三十年（965年），蜀军与宋军在剑门关外进行大战，蜀军全军覆灭，灭亡之势已不可免了。宋军包围成都府，孟昶投降，后蜀灭亡。"});
  所有敌将.push({id:29,_code:4029,文化:21,被关押:0,名称:"李煜",家族:"李",性格:[4,2],地位:0,跳:28,统帅:69,武力:40,智力:91,政治:28,魅力:97,清廉:86,野心:20,抗拒:100,底线:50,性别:0,介绍:"李煜，原名从嘉，字重光，号钟山隐士、钟锋隐者、白莲居士、莲峰居士，唐元宗李璟第六子，南唐末代君主，史称李后主。开宝八年，宋军破南唐都城，李煜降宋，被俘至汴京。后因作感怀故国的名词《虞美人》而被宋太宗毒死。李煜虽不通政治，但其艺术才华却非凡。精书法，善绘画，通音律，诗和文均有一定造诣，尤以词的成就最高。"});
  所有敌将.push({id:30,_code:4030,文化:22,被关押:0,名称:"赵匡胤",家族:"赵",性格:[0,17],地位:0,跳:30,统帅:93,武力:70,智力:97,政治:95,魅力:90,清廉:87,野心:78,抗拒:150,底线:51,性别:0,介绍:"宋太祖赵匡胤，涿郡人，五代至北宋初年军事家、政治家、战略家，宋朝开国皇帝。赵匡胤在后汉时投奔枢密使郭威，致身行伍，并于后周世宗柴荣在位时随征北汉、南唐，战功卓著。后在“陈桥兵变”中被拥立为帝，并回京逼迫后周恭帝禅位。同年，赵匡胤登基为帝，改元建隆，国号“宋”。赵匡胤在位期间，先后灭亡荆南、武平、后蜀、南汉及南唐南方割据政权，完成了全国大部的统一。"});
  所有敌将.push({id:31,_code:4031,文化:0,被关押:0,名称:"王建",家族:"王",性格:[0,17],跳:31,统帅:12,武力:54,智力:88,政治:78,魅力:89,清廉:96,野心:50,抗拒:100,底线:80,性别:0,介绍:"朝鲜高丽王朝的开国君主。"});
  所有敌将.push({id:32,_code:4032,文化:0,被关押:0,名称:"解仇",家族:undefined,跳:32,统帅:33,武力:84,智力:78,政治:84,魅力:80,清廉:90,野心:45,抗拒:100,底线:70,性别:0,介绍:"刺杀朝鲜百济第22代国王文周王扶馀牟都的刺客。"});
  所有敌将.push({id:33,_code:4033,文化:1,被关押:0,名称:"石田三成",家族:"石田",跳:33,统帅:88,武力:70,智力:90,政治:95,魅力:96,清廉:90,野心:40,抗拒:150,底线:60,性别:0,介绍:"日本战国时代和安土桃山时代的武将及大名，以忠诚、仁义、足智多谋著称。父亲是石田正继，正室是宇多赖忠的女儿皎月院。最初因为“三献茶”事件得到丰臣秀吉的赏识，并成为秀吉的得力干将，后来更成为日本最高权力机构“五奉行”的首席元老。丰臣秀吉死后拥立其子秀赖。1600年，关原之战爆发，石田三成率领的西军在此战中被德川家康率领的东军虐袭战中击破，三成本人也在不久后被捕并遭处决。"});
  所有敌将.push({id:34,_code:4034,文化:1,被关押:0,名称:"安倍晴明",家族:"安倍",跳:34,统帅:23,武力:43,智力:98,政治:88,魅力:97,清廉:97,野心:22,抗拒:120,底线:70,性别:0,介绍:"活跃于平安时代中期的阴阳师，是遣唐使阿倍仲麻吕的后代。他对当时处在科技与咒术最先端的“天文道”和占卜为主的“阴阳道”的相关技术有着卓越知识，是位受到平安贵族们信赖的大阴阳师。生前受天皇及权臣器重，79岁时受“法清院”爵。死后经由几代子孙的努力竟从一个从四位下的天文博士升至位极人臣的从一位。以至于江户时代流传着一句名言“不知源义经，但知晴明公”。"});
  所有敌将.push({id:35,_code:4035,文化:1,被关押:0,名称:"源义经",家族:"源",跳:35,统帅:34,武力:98,智力:78,政治:34,魅力:96,清廉:87,野心:20,抗拒:150,底线:50,性别:0,介绍:"源义朝的第九子，幼名牛若丸。日本传奇英雄，日本平安时代末期的名将。他的一生充满戏剧性，但最终却以惨遭兄弟屠戮的悲剧而结束。 "});
  所有敌将.push({id:36,_code:4036,文化:1,被关押:0,名称:"桂小太郎",家族:"桂",跳:36,统帅:67,武力:90,智力:90,政治:75,魅力:96,清廉:90,野心:60,抗拒:150,底线:50,性别:0,介绍:"“不是假发！是桂！”出自《银魂》。该人物原型为日本幕末时期的攘夷志士桂小五郎。"});
  所有敌将.push({id:37,_code:4037,文化:1,被关押:2,名称:"信女",家族:"伊集院",跳:37,统帅:33,武力:84,智力:78,政治:24,魅力:89,清廉:90,野心:45,抗拒:150,底线:50,性别:1,介绍:"在架空的历史背景下锄强扶弱，对坏人实施天诛的女武士。"});
  所有敌将.push({id:38,_code:4038,文化:1,被关押:0,名称:"佐佐木小次郎",家族:"佐佐木",跳:38,统帅:45,武力:97,智力:88,政治:24,魅力:95,清廉:77,野心:55,抗拒:150,底线:50,性别:0,介绍:"日本战国时代与安土桃山时代的剑术家，号岩流（或曰岸流），日本战国后期的著名剑客，富田势源的弟子，曾与中条流的钟卷自斋学习武术。为了修炼武艺而游历各国，并独自创立了自己的流派。相传他相貌英俊，擅长使用三尺的长刀，由于剑身相当长，攻击范围大，据称连天上的飞燕皆飞不出其长剑范围，被一切为二的绝招，故名“燕返”，与被后世尊为“剑豪”的宫本武藏于下关市岩流岛（小仓岛）对决。"});
  所有敌将.push({id:39,_code:4039,文化:2,被关押:0,名称:"绛宾",家族:undefined,跳:39,统帅:10,武力:54,智力:98,政治:62,魅力:88,清廉:96,野心:20,抗拒:80,底线:50,性别:0,介绍:"绛宾，公元前1世纪的龟兹国王。他娶了乌孙昆弥翁归靡和汉朝楚公主刘解忧的长女弟史为妻。"});
  所有敌将.push({id:40,_code:4040,文化:2,被关押:0,名称:"阿史那思摩",家族:"阿史那",跳:40,统帅:24,武力:54,智力:81,政治:45,魅力:80,清廉:87,野心:20,抗拒:150,底线:50,性别:0,介绍:"本姓阿史那氏，被赐姓李氏。唐朝攻破颉利可汗以后，为招抚突厥人，李思摩被封为乙弥泥熟俟利苾可汗，统治这些突厥人。"});
  所有敌将.push({id:41,_code:4041,文化:2,被关押:0,名称:"那利",家族:undefined,跳:41,统帅:57,武力:94,智力:98,政治:32,魅力:80,清廉:96,野心:20,抗拒:80,底线:50,性别:0,介绍:"唐太宗派郭孝恪讨伐龟兹，破都城，郭孝恪自留守，龟兹国相那利率众遁逃。那利等率众万余，与城内降胡表里为应攻郭孝恪，郭孝恪中流矢死。"});
  所有敌将.push({id:42,_code:4042,文化:2,被关押:0,名称:"莫贺咄",家族:undefined,跳:42,统帅:85,武力:54,智力:81,政治:63,魅力:56,清廉:87,野心:20,抗拒:150,底线:50,性别:0,介绍:"贞观初年，莫贺咄暗杀统叶护，自立为可汗，国中大乱，西突厥从此衰落。"});
  所有敌将.push({id:43,_code:4043,文化:3,被关押:0,名称:"臣盘",家族:undefined,跳:43,统帅:11,武力:54,智力:80,政治:56,魅力:87,清廉:77,野心:20,抗拒:80,底线:50,性别:0,介绍:"疏勒王臣盘，原为前王安国之舅，因罪徙月氏为质子，月氏王甚喜爱，为他在三地住处建伽蓝，冬夏迁居。"});
  所有敌将.push({id:44,_code:4044,文化:3,被关押:0,名称:"迦腻色伽",家族:undefined,跳:44,统帅:99,武力:90,智力:98,政治:78,魅力:97,清廉:96,野心:20,抗拒:150,底线:50,性别:0,介绍:"贵霜帝国影响最大的君主。原为阎膏珍监领天竺的将领，阎膏珍死后拥兵自立，成为贵霜新主。"});
  所有敌将.push({id:45,_code:4045,文化:3,被关押:0,名称:"阿育王",家族:undefined,跳:45,统帅:12,武力:90,智力:98,政治:34,魅力:97,清廉:96,野心:20,抗拒:150,底线:50,性别:0,介绍:"古印度摩揭孔雀王朝第三代国王，被佛教典籍称为无忧王。他继承并发展了父祖统一印度的事业，使孔雀王朝成为印度历史上第一个统一的大帝国。"});
  所有敌将.push({id:46,_code:4046,文化:3,被关押:0,名称:"阿尔巴兹",家族:"米尔",跳:46,统帅:85,武力:90,智力:78,政治:86,魅力:88,清廉:88,野心:70,抗拒:150,底线:50,性别:0,介绍:"阿尔巴兹·米尔（Arbaaz Mir），他倾其一生与侵略祖国与伤害人民的敌人战斗。"});
  所有敌将.push({id:47,_code:4047,文化:3,被关押:0,名称:"纳斯拉姆",家族:undefined,跳:47,统帅:62,武力:75,智力:82,政治:22,魅力:80,清廉:50,野心:60,抗拒:150,底线:50,性别:0,介绍:"刺杀圣雄甘地的凶手。"});
  所有敌将.push({id:48,_code:4048,文化:3,被关押:0,名称:"布林斯",家族:undefined,跳:48,统帅:20,武力:94,智力:85,政治:65,魅力:92,清廉:96,野心:20,抗拒:100,底线:80,性别:0,介绍:"布林斯是一个流浪各地的冒险家，他的出生是一个谜。有传说他在战争中失去了双亲，在那之后他放弃了以前的身份，成为了一个执着狂热的冒险家。"});
  所有敌将.push({id:49,_code:4049,文化:4,被关押:0,名称:"耶律亿",家族:"耶律",跳:49,统帅:12,武力:54,智力:98,政治:56,魅力:90,清廉:96,野心:70,抗拒:150,底线:50,性别:0,介绍:"耶律阿保机，汉名耶律亿或刘亿，辽朝开国君主，勇善射骑，明达世务。"});
  所有敌将.push({id:50,_code:4050,文化:4,被关押:0,名称:"耶律冲哥",家族:"耶律",跳:50,统帅:95,武力:98,智力:78,政治:40,魅力:85,清廉:78,野心:35,抗拒:150,底线:60,性别:0,介绍:"从小被卖为奴，一度在宋朝待过十多年。被卖回辽朝之后，他成了东宫的伶人。然后是侍卫，最后成了太子惕隐司武将。也许是因为长相俊美，贵族圈一直认为他不过是因为太子的龙阳之好，才得到了如此的高位。太平中兴初年，他被任命了北院都部署兼西北路招讨使，耶律冲哥因其赫赫战功而变得闻名天下。"});
  所有敌将.push({id:51,_code:4051,文化:4,被关押:0,名称:"萧忽古",家族:"萧",跳:51,统帅:11,武力:54,智力:98,政治:75,魅力:80,清廉:96,野心:70,抗拒:150,底线:50,性别:0,介绍:"契丹名将。此公很看不惯耶律乙辛这个大奸臣，整天想着刺杀他。有一次在桥下行刺，结果暴雨把桥冲坏了，萧忽古侥幸逃脱，刺杀未成。"});
  所有敌将.push({id:52,_code:4052,文化:4,被关押:0,名称:"耶律乙辛",家族:"耶律",跳:52,统帅:83,武力:83,智力:91,政治:95,魅力:96,清廉:60,野心:80,抗拒:150,底线:50,性别:0,介绍:"契丹族人，辽道宗年间宰相，杰出的政治家、战略家以及阴谋家。"});
  所有敌将.push({id:53,_code:4053,文化:5,被关押:0,名称:"巴蔓子",家族:"巴",跳:53,统帅:96,武力:98,智力:97,政治:88,魅力:84,清廉:91,野心:15,抗拒:103,底线:63,性别:0,介绍:"古巴国忠州人，东周末期的巴国将军。约公元前4世纪，巴国朐忍发生内乱。巴蔓子遂以许诺酬谢楚国三城为代价，借楚兵平息内乱。事平，楚使索城，蔓子认为国家不可分裂，身为人臣不能私下割城。但不履行承诺是为无信，割掉国土是为不忠，蔓子告曰“将吾头往谢之，城不可得也。”于是自刎，以授楚使。巴蔓子以头留城、忠信两全的故事，在巴渝大地传颂。"});
  所有敌将.push({id:54,_code:4054,文化:5,被关押:0,名称:"舍龙",家族:undefined,跳:54,统帅:23,武力:87,智力:98,政治:24,魅力:98,清廉:96,野心:50,抗拒:100,底线:50,性别:0,介绍:"哀牢王族，舍龙凭自己的勇猛和智慧，统一了邪龙川周边哀牢部族，建立了南诏部落联盟。"});
  所有敌将.push({id:55,_code:4055,文化:5,被关押:0,名称:"蛇灵",家族:undefined,跳:55,统帅:33,武力:87,智力:98,政治:98,魅力:98,清廉:96,野心:50,抗拒:100,底线:50,性别:0,介绍:"一只架空的风骚妩媚的毒哥。"});
  所有敌将.push({id:56,_code:4056,文化:6,被关押:0,名称:"拉隆",家族:"贝吉多杰",跳:56,统帅:23,武力:54,智力:98,政治:45,魅力:80,清廉:86,野心:20,抗拒:150,底线:50,性别:0,介绍:"拉隆·贝吉多杰，他为了维护佛教，为不使佛教在藏区根绝，不得不开杀戒刺杀了禁佛灭法的藏王朗达玛。"});
  所有敌将.push({id:57,_code:4057,文化:6,被关押:0,名称:"苏失利之",家族:undefined,跳:57,统帅:32,武力:54,智力:80,政治:56,魅力:89,清廉:86,野心:50,抗拒:100,底线:50,性别:0,介绍:"小勃律王，被吐蕃军击败，被迫臣服吐蕃，迎娶吐蕃公主为妃。"});
  所有敌将.push({id:58,_code:4058,文化:7,被关押:0,名称:"克劳狄",家族:undefined,跳:58,统帅:78,武力:78,智力:98,政治:98,魅力:97,清廉:96,野心:20,抗拒:150,底线:50,性别:0,介绍:"克劳狄一世，罗马帝国朱里亚·克劳狄王朝的第四任皇帝。他的统治力求各阶层的和谐，凡事采取中庸之道，修补了卡利古拉时期皇帝与元老议员之间的破裂关系，提高行省公民在罗马的政治权力，并兴建国家的实业。后期史学家认为，罗马帝国初期政治的中央集权统治型式，是在他的手中和平地转移完成的。"});
  所有敌将.push({id:59,_code:4059,文化:7,被关押:0,名称:"凯撒",家族:undefined,跳:59,统帅:34,武力:54,智力:98,政治:65,魅力:89,清廉:76,野心:90,抗拒:150,底线:40,性别:0,介绍:"罗马权倾一时的独裁者，结束了以元老院为权力中心的议会制。"});
  所有敌将.push({id:60,_code:4060,文化:7,被关押:0,名称:"帕里斯",家族:undefined,跳:60,统帅:90,武力:90,智力:98,政治:78,魅力:97,清廉:96,野心:20,抗拒:150,底线:50,性别:0,介绍:"他出生之前，预言家就说这个孩子将会给王国带来灾祸和不幸。王后吓坏了，就让一个奴隶杀掉自己的孩子。奴隶不忍心亲手杀死他，就将他扔到艾达山上的森林里。一只母熊后来收养了他，把他当做自己的孩子养大。帕里斯还卷入了奥林匹斯山上的女神之争，他裁决了赫拉，雅典娜，阿佛洛狄忒谁是最美的女人，裁决了谁拥有金苹果。帕里斯是与神有着“金苹果之约”的风流美男子，可以得到世上最美的女人。因为他的出现，祭司认定他会给特洛伊带来毁灭式的命运，便被放逐到伊达山放牧多年。为了向希腊讨还自己的姑母赫西俄涅。帕里斯奉父亲之命去到了希腊本土，在那里遇到了海伦。他与海伦迅速相爱，并且毫不犹豫地进行了名垂千古的一次私奔。这同时拉开了特洛伊战争的序幕。"});
  所有敌将.push({id:61,_code:4061,文化:7,被关押:0,名称:"梭伦",家族:undefined,跳:61,统帅:87,武力:90,智力:98,政治:98,魅力:97,清廉:96,野心:20,抗拒:150,底线:50,性别:0,介绍:"梭伦，生于雅典，出身于没落的贵族。他年轻时一面经商，一面游历，到过许多地方，漫游名胜古迹，考察社会风情。梭伦是古代雅典的政治家，立法者，诗人，是古希腊七贤之一。梭伦在前594年出任雅典城邦的第一任执政官，制定法律，进行改革，史称“梭伦改革”。"});
  所有敌将.push({id:62,_code:4062,文化:7,被关押:0,名称:"哈摩狄阿斯",家族:undefined,跳:62,统帅:22,武力:80,智力:84,政治:85,魅力:79,清廉:90,野心:40,抗拒:150,底线:50,性别:0,介绍:"古希腊的一位刺客。"});
  所有敌将.push({id:63,_code:4063,文化:7,被关押:0,名称:"吉安娜",家族:"普罗德摩尔",跳:63,统帅:78,武力:67,智力:88,政治:88,魅力:90,清廉:70,野心:70,抗拒:150,底线:50,性别:1,介绍:"吉安娜?普罗德摩尔曾是已被摧毁的塞拉摩统治者，现任的领袖。"});
  所有敌将.push({id:64,_code:4064,文化:7,被关押:0,名称:"帕里塞伊斯",家族:undefined,跳:64,统帅:12,武力:34,智力:89,政治:56,魅力:90,清廉:80,野心:58,抗拒:150,底线:50,性别:1,介绍:"特洛伊著名美女。她在战争中被阿喀琉斯俘获，两人日久生情，而后，希腊联军统帅阿伽门农贪图其美貌而“插足”，引起阿喀琉斯不满。"});
  所有敌将.push({id:65,_code:4065,文化:7,被关押:0,名称:"布鲁图斯",家族:undefined,跳:65,统帅:16,武力:54,智力:98,政治:98,魅力:89,清廉:76,野心:90,抗拒:150,底线:40,性别:0,介绍:"出身罗马贵族世家。密谋策划了刺杀凯撒的行动，既遂。"});
  所有敌将.push({id:66,_code:4066,文化:7,被关押:0,名称:"西泽尔",家族:"博尔吉亚",跳:66,统帅:82,武力:73,智力:95,政治:99,魅力:90,清廉:67,野心:90,抗拒:150,底线:50,性别:0,介绍:"教皇亚历山大六世的私生子，瓦伦蒂诺公爵，罗马尼阿的主人。曾担任瓦伦西亚大主教和枢机主教却以他的邪恶、残忍和征战的天才，将一个教皇国的梦想献给他的家族。传闻与妹妹博尔吉亚有不伦之恋。"});
  所有敌将.push({id:67,_code:4067,文化:8,被关押:0,名称:"赵佗",家族:"赵",跳:67,统帅:83,武力:80,智力:96,政治:87,魅力:83,清廉:90,野心:14,抗拒:102,底线:62,性别:0,介绍:"赵佗，秦朝著名宗室将领，华夏族，南越国创建者。赵佗是南越国第一代王和皇帝，公元前203年至前137年在位，号称“南越武王”或“南越武帝”。在执政期间，由于他一直实行“和辑百越”的政策，促进了汉越民族的融合，并把中原地区的先进文化带到了南越之地，使南越得到了更好的发展。"});
  所有敌将.push({id:68,_code:4068,文化:8,被关押:0,名称:"聂政",家族:"聂",跳:68,统帅:34,武力:90,智力:80,政治:44,魅力:64,清廉:80,野心:20,抗拒:150,底线:50,性别:0,介绍:"聂政（？—公元前397年），战国时侠客，韩国轵（今济源东南）人，以任侠著称，为春秋战国四大刺客之一。"});
  所有敌将.push({id:69,_code:4069,文化:8,被关押:0,名称:"高渐离",家族:"高",跳:69,统帅:36,武力:92,智力:80,政治:46,魅力:90,清廉:80,野心:20,抗拒:150,底线:50,性别:0,介绍:"高渐离，战国末燕人，荆轲的好友 ，擅长击筑。后刺杀秦王未遂，被杀。"});
  所有敌将.push({id:70,_code:4070,文化:8,被关押:0,名称:"豫让",家族:"姬",跳:70,统帅:39,武力:95,智力:80,政治:49,魅力:80,清廉:80,野心:20,抗拒:150,底线:50,性别:0,介绍:"豫让，姬姓，毕氏。春秋战国时期晋国人，是晋卿智瑶（智伯）家臣。晋出公二十二年（前453年），赵﹑韩﹑魏共灭智氏。豫让用漆涂身，吞炭使哑，暗伏桥下，谋刺赵襄子未遂，后为赵襄子所捕。临死时，求得赵襄子衣服，拔剑击斩其衣，以示为主复仇，然后伏剑自杀。"});
  所有敌将.push({id:71,_code:4071,文化:8,被关押:0,名称:"荆轲",家族:"姜",跳:71,统帅:55,武力:94,智力:71,政治:34,魅力:71,清廉:67,野心:32,抗拒:150,底线:50,性别:0,介绍:"荆轲（？—公元前227年），姜姓，庆氏（古时“荆”音似“庆”）。战国末期卫国朝歌（今河南鹤壁淇县）人，战国时期著名刺客，也称庆卿、荆卿、庆轲，是春秋时期齐国大夫庆封的后代。喜好读书击剑，为人慷慨侠义。"});
  所有敌将.push({id:72,_code:4072,文化:10,被关押:0,名称:"赤老温",家族:"逊都思",跳:72,统帅:88,武力:98,智力:60,政治:33,魅力:80,清廉:58,野心:32,抗拒:150,底线:50,性别:0,介绍:"赤老温，蒙古“四骏”之一。父亲为锁儿罕失剌，兄弟沉白，妹妹为合答安皇后。在少年成吉思汗被泰亦赤兀族追击之际掩护其脱险，获得信任。子孙为元朝四大名族之一极尽权势。"});
  所有敌将.push({id:73,_code:4073,文化:10,被关押:0,名称:"札木合",家族:"札达兰",跳:73,统帅:87,武力:83,智力:87,政治:80,魅力:81,清廉:59,野心:70,抗拒:150,底线:50,性别:0,介绍:"札木合（Jamuqa，1164年－1204年），蒙古札达兰部首领，被称为古儿汗。他与铁木真都希望统一蒙古。他是铁木真的主要对手之一，二人曾在蒙古草原上对立。后来虽然札木合败在铁木真的手下，不论是蒙古还是中原的历史对他的评价都非常高。"});
  所有敌将.push({id:74,_code:4074,文化:10,被关押:0,名称:"博尔术",家族:"阿儿剌",跳:74,统帅:88,武力:73,智力:88,政治:88,魅力:82,清廉:60,野心:34,抗拒:100,底线:50,性别:0,介绍:"博尔术，蒙古名将、成吉思汗“四俊”开国元勋之首。原名孛儿楚。蒙古阿儿剌氏。由于相助少年成吉思汗夺回被盗的爱马，成为其属下。最早加入蒙古军，为蒙古的发展作出巨大贡献。参加统一蒙古诸部战争，志意沉雄，善战知兵，多立战功。"});
  所有敌将.push({id:75,_code:4075,文化:10,被关押:0,名称:"皓月",家族:undefined,跳:75,统帅:56,武力:96,智力:98,政治:50,魅力:89,清廉:96,野心:20,抗拒:150,底线:50,性别:0,介绍:"草原上的狼族后裔。"});
  所有敌将.push({id:76,_code:4076,文化:10,被关押:0,名称:"曲蓝",家族:"高",跳:76,统帅:66,武力:97,智力:80,政治:51,魅力:80,清廉:80,野心:20,抗拒:150,底线:50,性别:0,介绍:"高曲蓝是一名主要在蒙古地区活动的刺客，他的箭术十分出名，后来他因此被刺客们所称赞。"});
  所有敌将.push({id:77,_code:4077,文化:11,被关押:0,名称:"帖木儿",家族:undefined,跳:77,统帅:99,武力:90,智力:98,政治:78,魅力:97,清廉:96,野心:20,抗拒:150,底线:50,性别:0,介绍:"帖木儿，1336年生于撒马尔罕以南的碣石（今沙赫里萨布兹）。其祖先做过察合台汗国的大臣，父亲死后继为碣石的一名封建城主。虽然帖木儿是突厥化蒙古人，但由于当地自古以来的波斯文化遗留，帖木儿在文化意识上倾向波斯文化。"});
  所有敌将.push({id:78,_code:4078,文化:11,被关押:0,名称:"哈桑",家族:"萨巴赫",跳:78,统帅:78,武力:90,智力:98,政治:62,魅力:80,清廉:96,野心:20,抗拒:100,底线:50,性别:0,介绍:"哈桑·萨巴赫，突厥籍波斯人，伊斯兰密教组织阿萨辛派的建立者。"});
  所有敌将.push({id:79,_code:4079,文化:11,被关押:0,名称:"阿拉乌丁",家族:"摩诃末",跳:79,统帅:78,武力:84,智力:98,政治:90,魅力:89,清廉:96,野心:60,抗拒:120,底线:50,性别:0,介绍:"花剌子模第六代君王。他使花剌子模国达到了鼎盛，在他统治期间花剌子模国成为中亚的主要帝国。"});
  所有敌将.push({id:80,_code:4080,文化:11,被关押:0,名称:"阿尔达班",家族:undefined,跳:80,统帅:96,武力:94,智力:85,政治:75,魅力:72,清廉:96,野心:20,抗拒:100,底线:80,性别:0,介绍:"波斯敌国宰相，策划了一场宫廷政变，刺杀了薛西斯一世。"});
  所有敌将.push({id:81,_code:4081,文化:11,被关押:0,名称:"卡利姆",家族:undefined,跳:81,统帅:21,武力:54,智力:80,政治:35,魅力:94,清廉:86,野心:50,抗拒:100,底线:50,性别:0,介绍:"侍奉王子的侍者。是一位热心于工作又认真的青年，貌似对阿修拉夫王子有着异样的情愫。"});
  所有敌将.push({id:82,_code:4082,文化:11,被关押:0,名称:"艾卜",家族:undefined,跳:82,统帅:88,武力:67,智力:93,政治:77,魅力:60,清廉:80,野心:70,抗拒:150,底线:50,性别:0,介绍:"奴隶出身的艾卜发动起义，推翻了倭马亚王朝的统治，建立阿拔斯王朝,史称“黑衣大食”。"});
  所有敌将.push({id:83,_code:4083,文化:12,被关押:0,名称:"汉谟拉比",家族:undefined,跳:83,统帅:78,武力:78,智力:98,政治:98,魅力:97,清廉:96,野心:20,抗拒:150,底线:50,性别:0,介绍:"阿摩利人的巴比伦王国的第六任国王。在一连串战争中，他击败邻国，将巴比伦的统治区域扩展至整个两河流域（美索不达米亚），从而成为巴比伦尼亚帝国的第一任国王。尽管他的帝国掌控了整个两河流域，他的继承者却无力保持他的伟业，帝国最终走向衰亡。"});
  所有敌将.push({id:84,_code:4084,文化:12,被关押:0,名称:"胡夫",家族:undefined,跳:84,统帅:78,武力:78,智力:98,政治:98,魅力:97,清廉:96,野心:20,抗拒:150,底线:50,性别:0,介绍:"胡夫，全名胡尼胡夫，埃及第四王朝第二位法老。埃及最大的金字塔就是为他修建的胡夫大金字塔。他曾经远征过西奈半岛和努比亚。巩固了从尼罗河三角洲到努比亚这样一个统一大国。"});
  所有敌将.push({id:85,_code:4085,文化:12,被关押:0,名称:"拉美西斯",家族:undefined,跳:85,统帅:78,武力:78,智力:98,政治:98,魅力:97,清廉:96,野心:20,抗拒:150,底线:50,性别:0,介绍:"拉美西斯二世是埃及最伟大的法老，他是个伟大的建筑师，也是个了不起的勇士。在他统治埃及的66年间总计生了100个小孩。拉美西斯二世总共有8个正式的妻子，还有将近100个妾。他死于公元前1212年，享年90岁。"});
  所有敌将.push({id:86,_code:4086,文化:12,被关押:0,名称:"乌尔纳姆",家族:undefined,跳:86,统帅:88,武力:87,智力:93,政治:91,魅力:80,清廉:80,野心:90,抗拒:150,底线:50,性别:0,介绍:"约公元前21世纪末，乌尔纳姆创建了乌尔第三王朝，统一了两河流域南部， 实行中央集权统治， 国王集军事、行政和司法大权于一身。历史上怀疑他谋害了乌鲁克第五王朝的国王乌图赫伽尔而登上王座。"});
  所有敌将.push({id:87,_code:4087,文化:12,被关押:0,名称:"阿蒙内特",家族:undefined,跳:87,统帅:22,武力:80,智力:90,政治:45,魅力:80,清廉:70,野心:70,抗拒:150,底线:50,性别:1,介绍:"阿蒙内特是一位埃及女刺客，在公元前30年8月12日，阿蒙内特潜入了克娄巴特拉七世的宫殿。她在宫殿中用一条毒蛇杀死了埃及艳后。"});
  所有敌将.push({id:88,_code:4088,文化:12,被关押:0,名称:"伊斯坎德尔",家族:undefined,跳:88,统帅:77,武力:90,智力:90,政治:84,魅力:70,清廉:90,野心:80,抗拒:150,底线:50,性别:0,介绍:"伊斯坎德尔（Iskender）是文艺复兴时期刺客组织埃及兄弟会的导师，且是阿泰尔?伊本-拉阿哈德的一位后裔。"});
  所有敌将.push({id:89,_code:4089,文化:13,被关押:0,名称:"伊凡",家族:undefined,跳:89,统帅:88,武力:91,智力:90,政治:90,魅力:88,清廉:60,野心:21,抗拒:151,底线:51,性别:0,介绍:"伊凡·瓦西里耶维奇，又被称为伊凡雷帝或者“恐怖的伊凡”、“伊凡大帝”。瓦西里三世与叶琳娜·格林斯卡娅之子，是俄国历史上的第一位沙皇。"});
  所有敌将.push({id:90,_code:4090,文化:13,被关押:0,名称:"贞德",家族:"达克",跳:90,统帅:94,武力:95,智力:96,政治:89,魅力:93,清廉:90,野心:20,抗拒:150,底线:50,性别:1,介绍:"圣女贞德是法国的军事家，天主教圣人，法国人民心中的自由女神。被法国人视为民族英雄，也是历史上唯一能在17岁时就指挥国家大军并取得胜利的少女。"});
  所有敌将.push({id:91,_code:4091,文化:14,被关押:0,名称:"巴法瓦尔曼",家族:"刹利",跳:91,统帅:76,武力:78,智力:93,政治:94,魅力:80,清廉:80,野心:80,抗拒:150,底线:50,性别:0,介绍:"真腊原为扶南的属国，公元6世纪中叶，真腊国公主嫁扶南国王子巴法瓦尔曼为妻，真腊原国王去世，巴法瓦尔曼继位为真腊国王。公元7世纪中叶，扶南国王去世，真腊国王巴法瓦尔曼欲兼任为扶南王，与扶南国太子发生纠纷，真腊国王巴法瓦尔曼起兵，武力征服扶南国，将扶南国变为真腊属国，建都伊赏那补罗城。"});
  所有敌将.push({id:92,_code:4092,文化:14,被关押:0,名称:"范蔓",家族:"范",跳:92,统帅:80,武力:56,智力:82,政治:84,魅力:89,清廉:78,野心:22,抗拒:122,底线:52,性别:0,介绍:"范蔓本是扶南国大将，勇健有权略，以兵威攻伐邻国，各邻国都服属扶南国，范蔓自号为「扶南大王」。 扶南大王范蔓雄才大略，建造大船，渡涨海，攻屈都昆（今马来半岛）、九稚、典孙等十余国，开地五六千里， 在位二十多年。"});
  所有敌将.push({id:93,_code:4093,文化:15,被关押:0,名称:"轲比能",家族:undefined,跳:93,统帅:88,武力:80,智力:78,政治:67,魅力:80,清廉:96,野心:60,抗拒:100,底线:50,性别:0,介绍:"汉末三国时期的鲜卑民族的杰出首领，由于他作战勇敢，执法公平，不贪财物，所以被鲜卑民众推举为大人。"});
  所有敌将.push({id:94,_code:4094,文化:16,被关押:0,名称:"拓跋思恭",家族:"拓跋",跳:94,统帅:80,武力:82,智力:78,政治:74,魅力:87,清廉:84,野心:48,抗拒:98,底线:48,性别:0,介绍:"李思恭，原名拓跋思恭，党项族，唐朝末年平夏部的首领，唐末因平定黄巢有功被赐皇姓“李”。原是夏州的偏将，咸通末年据宥州，自称刺史。中和元年（881年）黄巢入长安，李思恭与鄜州李孝昌同誓讨贼，唐僖宗以他为左武卫将军，权知夏绥银节度事。抵达王桥，被黄巢击败，之后与郑畋等四节度同盟，屯兵渭桥。之后进封四面都统，权知京兆尹。黄巢被平定后，李思恭兼太子太傅，封夏国公，赐姓李，拜夏州节度使。李思恭管辖的地区改名为“定难军”， 统辖夏、绥、银、宥、静五州地区。 "});
  所有敌将.push({id:95,_code:4095,文化:16,被关押:0,名称:"李睍",家族:"李",跳:95,统帅:31,武力:33,智力:63,政治:55,魅力:84,清廉:85,野心:49,抗拒:99,底线:49,性别:0,介绍:"李睍，党项族，夏神宗李遵顼之孙，夏献宗李德旺之侄，清平郡王之子，西夏最后一位皇帝。公元1227年春，蒙古军进围都城中兴府，李睍坚守半年后，因城中粮食用尽，军民大批得病，又遭强烈地震，城中宫室都被震塌，只得向成吉思汗奉上祖传金佛和金银财宝请降，要求宽限1个月再献城。李睍向蒙古请降后不久，成吉思汗去世，密不发丧，以免西夏反悔。李睍投降后按照成吉思汗遗嘱被杀，蒙古军将领察罕努力使银川避免了屠城的命运，并入城安抚城内军民，城内的军民得以保全，西夏灭亡。"});
  所有敌将.push({id:96,_code:4096,文化:17,被关押:0,名称:"李贲",家族:"李",跳:96,统帅:79,武力:55,智力:81,政治:83,魅力:88,清廉:77,野心:21,抗拒:121,底线:51,性别:0,介绍:"李贲，又称李南帝，是公元6世纪中期越南北部地区领袖，万春国的开国君主。龙兴太平（今属越南）人，出身地方俚族有势力家庭。其七世祖来自中国，因西汉末年的战乱而来到交州避难。李贲曾出仕南朝梁，但因为战乱，回到故乡。"});
  所有敌将.push({id:97,_code:4097,文化:17,被关押:0,名称:"黎利",家族:"黎",跳:97,统帅:88,武力:67,智力:93,政治:91,魅力:80,清廉:80,野心:50,抗拒:150,底线:50,性别:0,介绍:"越南后黎朝开国君主，后人称为黎太祖。"});
  所有敌将.push({id:98,_code:4098,文化:18,被关押:0,名称:"努尔哈赤",家族:"爱新觉罗",跳:98,统帅:92,武力:80,智力:81,政治:88,魅力:80,清廉:88,野心:90,抗拒:149,底线:49,性别:0,介绍:"清太祖爱新觉罗·努尔哈赤，女真族，建州女真首领、后金第一位大汗、清朝实际奠基者。"});
  所有敌将.push({id:99,_code:4099,文化:18,被关押:0,名称:"亦都赫辛",家族:undefined,跳:99,统帅:33,武力:80,智力:78,政治:54,魅力:80,清廉:60,野心:70,抗拒:150,底线:50,性别:1,介绍:"一位女真族女萨满。"});
  所有敌将.push({id:100,_code:4100,文化:19,被关押:0,名称:"阚伯周",家族:undefined,跳:100,统帅:78,武力:54,智力:80,政治:82,魅力:87,清廉:76,野心:20,抗拒:120,底线:50,性别:0,介绍:"中国古代高昌国的君主之一，阚氏高昌开国君主。"});
  所有敌将.push({id:101,_code:4101,文化:19,被关押:0,名称:"吐迷度",家族:undefined,跳:101,统帅:45,武力:54,智力:98,政治:83,魅力:83,清廉:96,野心:20,抗拒:100,底线:50,性别:0,介绍:"唐代回纥首领。药罗葛氏。原为菩萨属下胡屋(禄)俟利发。"});
  所有敌将.push({id:102,_code:4102,文化:20,被关押:0,名称:"熊商",家族:"芈",跳:102,统帅:88,武力:73,智力:88,政治:88,魅力:82,清廉:60,野心:34,抗拒:100,底线:50,性别:0,介绍:"楚威王熊商，芈姓，熊氏，名商，楚宣王之子，战国时期楚国国君，继承其父楚宣王救赵伐魏与开拓巴 蜀的格局，战国时代，楚国继楚悼王以后，使楚国国势发展最强的君王，他一生以恢复楚庄王时代的霸 业为志业，力图使楚国冠绝诸国之首。楚威王七年（前333年）打败越王无疆，尽取吴地，在长江边石头 山（今清凉山）上建立金陵邑（南京城）。"});
  所有敌将.push({id:103,_code:4103,文化:21,被关押:0,名称:"要离",家族:"要",跳:103,统帅:37,武力:93,智力:80,政治:47,魅力:10,清廉:80,野心:20,抗拒:150,底线:50,性别:0,介绍:"要离，春秋时期吴国人，刺客。生得身材瘦小，仅五尺余，腰围一束，形容丑陋，有万人之勇，是当时有名的击剑能手。足智多谋，以捕鱼为业，家住无锡鸿山山北。"});
  所有敌将.push({id:104,_code:4104,文化:21,被关押:0,名称:"专诸",家族:"专",跳:104,统帅:35,武力:91,智力:80,政治:45,魅力:76,清廉:80,野心:20,抗拒:150,底线:50,性别:0,介绍:"专诸，春秋时期吴国人氏，为吴国公子光(即后来的吴王阖闾)所雇，用来刺杀王位竞争对手吴王僚。"});
  所有敌将.push({id:105,_code:4105,文化:22,被关押:0,名称:"韩世忠",家族:"韩",跳:105,统帅:93,武力:95,智力:94,政治:85,魅力:81,清廉:88,野心:12,抗拒:100,底线:60,性别:0,介绍:"韩世忠，两宋之际的名将，出身贫寒，18岁应募从军。英勇善战，胸怀韬略，在抗击西夏和金的战争中为宋朝立下汗马功劳，而且在平定各地的叛乱中也作出重大的贡献。为官正派，不肯依附奸相秦桧，为岳飞遭陷害而鸣不平。死后被追赠为太师，追封通义郡王；宋孝宗时，又追封蕲王，谥号忠武，配飨宋高宗庙廷。是南宋朝一位颇有影响的人物。"});
  所有敌将.push({id:106,_code:4106,文化:22,被关押:0,名称:"吴玠",家族:"吴",跳:106,统帅:94,武力:96,智力:95,政治:86,魅力:82,清廉:89,野心:13,抗拒:101,底线:61,性别:0,介绍:"南宋抗金名将。早年从军御边，抗击西夏建功。后领兵抗金，和尚原之战中，大败金兵兀术部，破川陕路金兵进攻。因功官至四川宣抚使。由于长期鞍马之劳，病卒于防地仙人关，年仅47岁，谥号武安，作庙于仙人关，号思烈。淳熙中，追封涪王。是南宋朝一位颇有影响的人物。"});
  所有敌将.push({id:107,_code:4107,文化:8,被关押:0,名称:"张起灵",家族:"张",跳:107,统帅:56,武力:99,智力:99,政治:39,魅力:99,清廉:99,野心:0,抗拒:0,底线:0,性别:0,介绍:"一个身世如谜题般的人物，外号闷油瓶，为人神秘莫测，身手不凡，为张家族长的现任指定继承人。"});
  所有敌将.push({id:108,_code:4108,文化:8,被关押:0,名称:"黑瞎子",家族:"齐",跳:108,统帅:23,武力:99,智力:99,政治:57,魅力:99,清廉:99,野心:0,抗拒:0,底线:0,性别:0,介绍:"旗人，职业盗墓者，会易容，本名未知。总是带着一副墨镜，是个无论何时脸上都带着不明意味笑容的怪人，身手极好。"});
  所有敌将.push({id:109,_code:4109,文化:8,被关押:0,名称:"杨天策",家族:"杨",跳:109,统帅:78,武力:94,智力:80,政治:88,魅力:89,清廉:83,野心:40,抗拒:0,底线:0,性别:0,介绍:"红星寿的徒弟，武艺高强，善于使用弓箭。"});
  所有敌将.push({id:110,_code:4110,文化:10,被关押:0,名称:"顾惜朝",家族:"顾",跳:110,统帅:12,武力:70,智力:95,政治:56,魅力:91,清廉:85,野心:40,抗拒:0,底线:0,性别:0,介绍:"顾惜朝，出自温瑞安武侠小说、同名电视剧《逆水寒》。"});
  所有敌将.push({id:111,_code:4111,文化:7,被关押:0,名称:"伊丽莎白",家族:"都铎",跳:111,统帅:12,武力:70,智力:95,政治:56,魅力:91,清廉:85,野心:40,抗拒:0,底线:0,性别:1,介绍:"英国都铎王朝伊丽莎白一世女王。公元1558年，伊丽莎白即位，开启了属于自己的时代。她采取对天主教和新教兼容并蓄的政策，勤于政事，安抚民心，展现出杰出的治国理政才能。在其统治期间，英国成为欧洲国力最强盛、国人最富有的国家，文化也达到鼎盛，涌现出莎士比亚等名烁古今的伟大人物，史称“黄金时代”。“英明女王”不愿与别国王子共享权力，终身未立王夫、亦未有嗣。"});
  所有敌将.push({id:112,_code:4112,文化:7,被关押:0,名称:"维多利亚",家族:"汉诺威",跳:112,统帅:12,武力:70,智力:95,政治:56,魅力:91,清廉:85,野心:40,抗拒:0,底线:0,性别:1,介绍:"维多利亚女王，大不列颠及爱尔兰联合王国女王，印度女皇。她在位时是英国最强的“日不落帝国”时期，英国历史上称为“维多利亚时代”。此时，英国加大殖民扩张，建立和占领了很多殖民地。她在位的几十年，英国自由资本主义由方兴未艾到顶尖、进而过渡到垄断资本主义的转变，经济、文化空前繁荣，君主立宪制得到充分发展，使维多利亚女王成了英国和平与繁荣的象征。"});
  所有敌将.push({id:113,_code:4113,文化:13,被关押:0,名称:"叶卡捷琳娜",家族:"阿列克谢耶芙娜",跳:113,统帅:12,武力:70,智力:95,政治:56,魅力:91,清廉:85,野心:40,抗拒:0,底线:0,性别:1,介绍:"沙俄帝国叶卡捷琳娜二世女皇陛下。她是德意志安哈尔特亲王之女，十三岁成为沙俄皇储妃。其统治三十四年间，击败奥斯曼帝国，吞并克里米亚，治国有方，功勋显赫。她一生情人虽多，但从不愿为他们有孕，始终只有与先夫所生一子、即保罗一世。在俄罗斯千年历史上，唯有她和彼得一世享有“大帝”尊号，被视为千古一见的明君英主。"});
