  外域美人.push({id:0,_code:5000,名称:"皇甫丽援",家族:"皇甫",地位:0,性格:[2,4],党:0,跳:0,统帅:34,武力:12,智力:76,政治:34,魅力:95,清廉:80,野心:9,性别:1,文化:0,介绍:"大穆王后皇甫氏，高丽光宗王昭之妻。父亲是高丽太祖王建，母亲是神静太后皇甫氏，随母姓，嫁给异母兄弟高丽光宗王昭，生高丽景宗、孝和太子、千秋殿夫人、宝华宫夫人、文德王后。"});
  外域美人.push({id:1,_code:5001,名称:"藤原安子",家族:"藤原",地位:0,性格:[32,36],党:0,跳:1,统帅:12,武力:12,智力:66,政治:78,魅力:96,清廉:64,野心:16,性别:1,文化:1,介绍:"藤原安子为村上天皇中宫，右大臣藤原师辅长女。藤原安子生下两位天皇，确立了藤原摄关家的地位。安子的侄子藤原道长更将权位发展至巅峰，造就藤原氏的传奇与荣华。"});
  外域美人.push({id:2,_code:5002,名称:"杨奕承",家族:"杨",地位:0,性格:[17,25],党:0,跳:2,统帅:20,武力:28,智力:70,政治:65,魅力:94,清廉:90,野心:10,性别:1,文化:8,介绍:"义成公主杨氏，隋宗室女，史籍又作义城公主。开皇十九年（599年），下嫁东突厥启民可汗的安义公主卒，隋文帝复以义成公主下嫁启民可汗。有隋一代，少数民族首领连娶两位公主者，唯启民可汗一人。义成公主在突厥生活近30年，先后为启民可汗、始毕可汗、处罗可汗、颉利可汗之可贺敦。 "});
  外域美人.push({id:3,_code:5003,名称:"阿史那燕",家族:"阿史那",地位:2,性格:[9,7],党:0,跳:3,统帅:23,武力:56,智力:82,政治:57,魅力:90,清廉:86,野心:10,性别:1,文化:2,介绍:"突厥颉利可汗的掌上明珠，因李世民不接受其感情，后嫁给李建成。玄武门之变中，因对李世民余情未了，未下杀手，最终成为李世民的妃子。"});
  外域美人.push({id:4,_code:5004,名称:"拉芝修黎",家族:"弹那",地位:2,性格:[4,10],党:0,跳:4,统帅:34,武力:21,智力:78,政治:56,魅力:95,清廉:95,野心:24,性别:1,文化:3,介绍:"波罗帕羯罗伐弹那之女，戒日王之姐。波罗帕羯罗伐弹那将其嫁给穆里克国王格拉巴伐尔曼，以加强两国的联盟关系。高达和摩腊婆两国联合发兵进攻坦尼沙的盟国穆里克，穆里克国王兵败被杀，王后拉芝修黎被俘。戒日王得知其姐拉芝修黎已从高达国王设赏迦那里逃脱，便率部分人马离开战场寻找拉芝修黎，最后在文迪亚山林中找到其姐。而后戒日王恢复了穆里克国，由拉芝修黎担任名义上的女王，实际上由戒日王统治。"});
  外域美人.push({id:5,_code:5005,名称:"萧燕燕",家族:"萧",地位:0,性格:[0,7],党:0,跳:5,统帅:99,武力:70,智力:89,政治:99,魅力:82,清廉:95,野心:89,性别:1,文化:4,介绍:"萧绰，小字燕燕，辽朝著名的政治家、军事家和改革家，她摄政期间，辽朝进入了历史上统治中原二百年间最为鼎盛的辉煌时期。"});
  外域美人.push({id:6,_code:5006,名称:"耶律观音女",家族:"耶律",地位:2,性格:[5,17],党:0,跳:6,统帅:32,武力:38,智力:34,政治:56,魅力:92,清廉:78,野心:15,性别:1,文化:4,介绍:"耶律观音女，中国辽代景宗耶律贤和萧太后长女，嫁萧绰堂弟萧继先。耶律观音女为景宗之女、圣宗之姊、兴宗之姑。长公主出生时佛教盛行，因此被人们称为耶律观音女。萧太后对长女“尤加爱，赐奴婢万口。”景宗的女儿中，只有耶律观音女许建了私城头下州——徽州，“滕户万户，节度使以下，皆公主府属。”"});
  外域美人.push({id:7,_code:5007,名称:"耶律长寿女",家族:"耶律",地位:2,性格:[11,12],党:0,跳:7,统帅:12,武力:87,智力:67,政治:34,魅力:87,清廉:88,野心:8,性别:1,文化:4,介绍:"耶律长寿女，中国辽代景宗耶律贤和萧太后次女，封吴国公主。统和初年，进封卫国公主，改封魏国长公主。耶律长寿女下嫁宰相萧排押。萧排押长女萧氏为其兄辽圣宗贵妃，但萧贵妃年长于公主。"});
  外域美人.push({id:8,_code:5008,名称:"耶律延寿女",家族:"耶律",地位:2,性格:[14,19],党:0,跳:8,统帅:22,武力:22,智力:85,政治:90,魅力:94,清廉:90,野心:22,性别:1,文化:4,介绍:"耶律延寿女，中国辽代景宗耶律贤和萧太后第三女，封越国公主，下嫁萧恒德。耶律延寿女性情沉厚，不以贵宠自骄，睿智皇后萧绰在诸女中非常喜爱她。二十一岁因病而死，追封赵国公主。"});
  外域美人.push({id:9,_code:5009,名称:"高升洁",家族:"高",地位:0,性格:[1,40],党:0,跳:9,统帅:20,武力:12,智力:91,政治:67,魅力:89,清廉:87,野心:41,性别:1,文化:5,介绍:"大理中宗段正淳之妻，大理宪宗段正严的母后。高升洁是“国中才女”，“幼学于本慧国师，精奇门。”经高升泰撮合，嫁给段正淳为妻。《段氏传灯录》中记载，段正淳曾作赞妻之文，言：“国有巾帼，家有娇妻。夫不如妻，亦大好事。妻叫东走莫朝西，朝东甜言蜜语，朝西比武赛诗。丈夫天生不才，难与红妆娇妻比高低。”"});
  外域美人.push({id:10,_code:5010,名称:"李雪雁",家族:"李",地位:0,性格:[10,6],党:0,跳:10,统帅:33,武力:18,智力:44,政治:44,魅力:90,清廉:22,野心:88,性别:1,文化:8,介绍:"文成公主，唐朝和亲公主，吐蕃赞普松赞干布的王后。本是唐室远支宗室女，于642年奉唐太宗之命和亲吐蕃。在吐蕃被尊称甲木萨（藏语中“甲”的意思是“汉”，“木”的意思是“女”，“萨”的意思为神仙）。"});
  外域美人.push({id:11,_code:5011,名称:"赤尊",家族:undefined,地位:3,性格:[16,6],党:0,跳:11,统帅:11,武力:11,智力:75,政治:78,魅力:92,清廉:78,野心:16,性别:1,文化:6,介绍:"赤尊公主，又译为作墀尊公主、尺尊公主、赤真公主、赤贞公主，或按梵文译为波利库姬、布里库提、毗俱胝。吐蕃神话传说中的尼婆罗（吐蕃的附属国，在现在的尼泊尔境内的一个古国）公主，远嫁吐蕃赞普松赞干布。"});
  外域美人.push({id:12,_code:5012,名称:"佐伊",家族:"马其顿",地位:1,性格:[35,29],党:0,跳:12,统帅:63,武力:45,智力:77,政治:88,魅力:90,清廉:23,野心:97,性别:1,文化:7,介绍:"佐伊，拜占庭帝国第二位女皇，皇帝君士坦丁八世与海伦娜皇后之女，罗曼努斯三世的皇后。君士坦丁八世担心未来的女婿会过多干预皇室事务，直到弥留之际才让其中的一个女儿与他选中的皇位继承人罗曼努斯结婚。因为佐伊已经50岁，不能再生育，所以君士坦丁八世有意让狄奥多拉结婚，但狄奥多拉自恃貌美，拒绝和出生低微的罗曼努斯结婚，佐伊就代替妹妹和罗曼努斯结婚，婚后三天，两人共同登上皇位。"});
  外域美人.push({id:13,_code:5013,名称:"狄奥凡诺",家族:"马其顿",地位:2,性格:[21,40],党:0,跳:13,统帅:45,武力:34,智力:90,政治:83,魅力:92,清廉:86,野心:20,性别:1,文化:7,介绍:"狄奥凡诺，拜占庭帝国皇帝君士坦丁八世和海伦娜皇后的小女儿，拜占庭帝国第三位女皇，马其顿王朝末代皇帝。狄奥多拉在父皇死后过着隐居的生活，但她在臣民之中的号召力遭到姐姐佐伊女皇的嫉妒。佐伊以她试图篡夺皇位为借口将她软禁长达14年之久。君士坦丁九世去世后，年届七旬的狄奥多拉单独执政。女皇显示了她隐匿已久的政治手腕，在她稳固的统治下，先前为所欲为的贵族受到约束，但她也因对政敌过于严厉又不适当地雇佣心腹而受到“任人唯亲”的非议。"});
  外域美人.push({id:14,_code:5014,名称:"孛儿帖",家族:"弘吉剌",地位:0,性格:[0,5],党:0,跳:14,统帅:78,武力:22,智力:92,政治:82,魅力:91,清廉:86,野心:18,性别:1,文化:10,介绍:"草原民族弘吉拉部落美女，成吉思汗的正室。居于第一汗尔敦（蒙古宫帐），地位最高、最得敬重、最得宠、年迈后亦如此。铁木真19岁时，为救20岁的妻子孛儿帖打响人生第一场战争。孛儿帖宅心渊静，禀德柔嘉，聪慧贤明，辅佐成吉思汗奠定蒙古帝国基业。"});
  外域美人.push({id:15,_code:5015,名称:"忽兰",家族:"蔑儿乞",地位:3,性格:[19,8],党:0,跳:15,统帅:32,武力:55,智力:23,政治:43,魅力:92,清廉:45,野心:10,性别:1,文化:10,介绍:"成吉思汗侧妃。兀儿思蔑儿乞部长答亦儿兀孙之女。她是第二斡儿朵之首，地位仅次于大皇后孛儿帖。成吉思汗征战西域七年，在妻妾当中只让忽兰随行。忽兰生有一子阔列坚，因为母亲很得宠的关系，被视为嫡子一样看待。"});
  外域美人.push({id:16,_code:5016,名称:"古儿别速",家族:"乃蛮",地位:3,性格:[10,12],党:0,跳:16,统帅:32,武力:21,智力:35,政治:51,魅力:90,清廉:39,野心:72,性别:1,文化:10,介绍:"古儿别速原为乃蛮部汗王亦难察必勒格宠妃。乃蛮部灭亡后，被成吉思汗宠爱，封为皇后。"});
  外域美人.push({id:17,_code:5017,名称:"合答安",家族:"逊都思",地位:3,性格:[19,17],党:0,跳:17,统帅:33,武力:22,智力:36,政治:52,魅力:91,清廉:40,野心:73,性别:2,文化:10,介绍:"合答安，元太祖成吉思汗铁木真第四斡儿朵可敦（皇后）。蒙古泰赤乌部速勒逊都氏锁儿罕失剌之女，赤老温之妹。"});
  外域美人.push({id:18,_code:5018,名称:"李嵬名",家族:"李",地位:3,性格:[7,25],党:0,跳:18,统帅:33,武力:22,智力:36,政治:52,魅力:91,清廉:40,野心:73,性别:2,文化:16,介绍:"李嵬名，党项族兴庆人氏，元太祖孛儿只斤·铁木真的宠妃，居第三斡儿朵，原是西夏察合公主。据说在她跳黄河以后，成吉思汗曾令士兵开掘黄河，一代美女沦为西夏的救国工具，可西夏最终还是难逃被灭。"});
  外域美人.push({id:19,_code:5019,名称:"火臣别乞",家族:"孛儿只斤",地位:2,性格:[10,15],党:0,跳:19,统帅:32,武力:76,智力:43,政治:43,魅力:91,清廉:75,野心:56,性别:1,文化:10,介绍:"火臣别乞，孛儿只斤氏，蒙古国公主。成吉思汗与孛儿帖之长女。"});
  外域美人.push({id:20,_code:5020,名称:"克丽佩脱拉",家族:undefined,地位:0,性格:[16,29],党:0,跳:20,统帅:96,武力:23,智力:85,政治:75,魅力:98,清廉:41,野心:99,性别:1,文化:12,介绍:"埃及艳后，古埃及克罗狄斯·托勒密王朝的最后一任女法老。她才貌出众，聪颖机智，擅长手段，心怀叵测，一生富有戏剧性。特别是卷入罗马共和国末期的政治漩涡，同恺撒、安东尼关系密切，并伴以种种传闻逸事，传说为保持国家免受罗马帝国吞并，曾色诱盖厄斯·儒略·凯撒大帝及他的手下安东尼，她让一条毒蛇咬死自己来同时结束自己和埃及的生命，从此以后，埃及成为了罗马帝国的一部分。"});
  外域美人.push({id:21,_code:5021,名称:"奥丽加",家族:undefined,地位:0,性格:[0,8],党:0,跳:21,统帅:34,武力:34,智力:80,政治:65,魅力:96,清廉:64,野心:69,性别:1,文化:13,介绍:"奥丽加，古罗斯国女政治家，基辅大公伊戈尔的夫人，斯维亚托斯拉夫·伊戈列维奇大公的母亲和摄政，也作圣奥丽加。在斯维亚托斯拉夫成年后，奥丽加仍然是基辅罗斯的实际统治者。奥丽加是第一个皈依基督教的罗斯统治者。为加强与拜占庭帝国的联系，奥丽加于前往帝都君士坦丁堡。她在那里受洗成为一名基督教徒，并得到一个基督教名字叶莲娜，为俄罗斯东正教会最早追认的圣人之一。"});
  外域美人.push({id:22,_code:5022,名称:"可足浑",家族:undefined,地位:0,性格:[7,30],党:0,跳:22,统帅:56,武力:33,智力:78,政治:39,魅力:90,清廉:80,野心:78,性别:1,文化:15,介绍:"可足浑，十六国时期前燕景昭帝慕容儁的皇后。出生低微，因其貌美有才智，慕容儁深爱之，娶其为妻，称帝后晋封为皇后。育有前燕献怀太子慕容晔、燕幽帝慕容暐、中山王慕容冲。"});
  外域美人.push({id:23,_code:5023,名称:"慕容凊",家族:"慕容",地位:2,性格:[26,19],党:0,跳:23,统帅:33,武力:56,智力:82,政治:57,魅力:90,清廉:86,野心:10,性别:1,文化:15,介绍:"清河公主慕容氏，鲜卑族，十六国时期前燕公主，前燕景昭帝慕容儁的女儿，西燕烈文帝慕容泓的姐妹。容貌美丽，嫁给前秦宣昭帝苻坚。二人没有子嗣，不知所终。"});
  外域美人.push({id:24,_code:5024,名称:"野利都兰",家族:"野利",地位:0,性格:[7,29],党:0,跳:24,统帅:28,武力:36,智力:80,政治:88,魅力:89,清廉:58,野心:63,性别:1,文化:16,介绍:"野利氏出身于党项族野利部人。她最初只是李元昊的妾室，因家族辅佐有功，加上其容貌美丽，有智谋，成为李元昊称帝后的第一任皇后。靠着这些优势，野利氏宠冠后宫，元昊与她的感情很深，对她又爱又怕。"});
  外域美人.push({id:25,_code:5025,名称:"没藏黑云",家族:"没藏",地位:3,性格:[33,37],党:0,跳:25,统帅:12,武力:12,智力:56,政治:56,魅力:85,清廉:68,野心:82,性别:1,文化:16,介绍:"没藏氏，西夏景宗李元昊之情妇，西夏毅宗李谅祚之母，权臣没藏讹庞之妹。曾为西夏大将野利遇乞之妻，野利遇乞被杀后入宫，得到元昊宠幸，皇后野利氏逐她出宫为尼，仍与元昊幽会，生子谅祚。在元昊遇弑后被尊为太后，辅佐儿子。后与情夫宝保吃多已一起被暗杀。"});
  外域美人.push({id:26,_code:5026,名称:"陈容",家族:"陈",地位:0,性格:[25,38],党:0,跳:26,统帅:28,武力:23,智力:85,政治:78,魅力:88,清廉:25,野心:83,性别:1,文化:17,介绍:"越南李朝惠宗李旵的皇后，昭皇李天馨之母。李惠宗为皇太子时因郭卜造反，随父皇出逃至即墨乡，对美貌的豪族千金陈容一见钟情，通过不合法的方式和她结婚。陈容生下了长女后被立为皇后，两年后又生下次女昭圣公主李天馨。陈容之兄去世后，他的族弟陈守度成为李氏家长，不满足于替李惠宗处理朝政，将其逼退位，立公主李天馨为女皇。第二年李朝灭亡，陈朝建立。陈容在其中扮演了不光彩的角色，逼退李惠宗以及陈朝开国，有她和堂哥陈守度日夜商谋的功劳，李氏被灭族也是她默许的。"});
  外域美人.push({id:27,_code:5027,名称:"李天馨",家族:"李",地位:1,性格:[14,15],党:0,跳:27,统帅:12,武力:12,智力:56,政治:56,魅力:89,清廉:68,野心:26,性别:1,文化:17,介绍:"越南历史上唯一的女皇帝。因其父惠宗长女已嫁，又无男嗣，乃立其为皇太女。同年权臣陈守度废惠宗，立其为帝，时年仅七岁。后嫁陈日煚并禅位于夫君，降为皇后，因无子被废后位。后太子陈晃继位，又娶其为皇后，为乱伦之举，同年生子陈昑。她做过女皇，又成为父子两代皇帝的皇后，儿子也是皇帝，是越南史上的传奇女性。"});
  外域美人.push({id:28,_code:5028,名称:"纥石烈",家族:undefined,地位:0,性格:[0,17],党:0,跳:28,统帅:34,武力:12,智力:90,政治:75,魅力:97,清廉:86,野心:10,性别:1,文化:18,介绍:"金太祖完颜旻皇后。金太祖起兵抗辽的时候，她是金太祖的正室之一（女真旧俗多妻制），成为完颜阿骨打的好帮手，贤内助。她的人品，受到了金国上下一致的好评。以致在后来太祖辞世，弟太宗完颜晟（吴乞买）请皇嫂仍居庆元宫，再后来熙宗完颜亶掌政。 天会十三年（公元1135年）尊纥石烈氏为庆元宫太皇太后"});
  外域美人.push({id:29,_code:5029,名称:"完颜兀鲁",家族:"完颜",地位:2,性格:[18,19],党:0,跳:29,统帅:44,武力:24,智力:83,政治:92,魅力:88,清廉:90,野心:33,性别:1,文化:18,介绍:"完颜兀鲁，金国公主，金太祖完颜阿骨打长女。完颜兀鲁嫁给了徒单定哥，定哥死后无子，以幼弟之子徒单查剌为后。徒单定哥的弟弟徒单斜也谋取其兄家财，强娶完颜兀鲁为妻室而不相能。徒单恭妾忽挞与完颜兀鲁不和，向完颜亮皇后徒单氏说完颜兀鲁的坏话。天德四年，正好韩王完颜亨改广宁尹，公主宗妇去向其母（兀术的妻子）道贺，完颜兀鲁宽慰其母，忽挞这时以怨望之罪指斥诬兀鲁。完颜亮使萧裕将兀鲁拿问，忽挞被徒单后信任，调查的官员都不敢言，九月甲申，遂杀死兀鲁，完颜斜也因而尽夺完颜查剌家财。"});
  外域美人.push({id:30,_code:5030,名称:"李婼",家族:"李",地位:0,性格:[5,4],党:0,跳:30,统帅:15,武力:25,智力:84,政治:93,魅力:89,清廉:91,野心:34,性别:1,文化:8,介绍:"宁国公主，嬴姓李氏，唐朝时期公主，唐肃宗李亨次女。唐肃宗即位，册封彭原公主，先后嫁给荥阳郑巽、河东薛康衡，很快做了寡妇。乾元元年(公元759年)，册封宁国公主，嫁给参与平定安史之乱有功的回纥英武威远可汗，成为可敦（王后）。第二年，可汗去世后，返回长安。"});
  外域美人.push({id:31,_code:5031,名称:"毗伽",家族:"药罗葛",地位:2,性格:[15,14],党:0,跳:31,统帅:56,武力:26,智力:85,政治:64,魅力:90,清廉:92,野心:31,性别:1,文化:19,介绍:"毗伽公主，药罗葛氏，回纥的公主。“安史之乱”爆发，唐肃宗在灵武即位两个月后，派遣雍王之子敦煌王李承寀出使回纥，以图借兵。回纥英武可汗磨延啜也有同唐朝交好、联姻的心愿，于是提出将女儿嫁给李承寀。李承寀答应了这个要求，唐肃宗对回纥可汗的拔刀相助非常感激，当即将可汗的女儿封为“毗伽公主”，又册为敦煌王妃。英武可汗随即派长子叶护太子率领四千骑兵助唐平叛。"});
  外域美人.push({id:32,_code:5032,名称:"玛依娜",家族:"药罗葛",地位:2,性格:[7,25],党:0,跳:32,统帅:78,武力:96,智力:90,政治:88,魅力:91,清廉:88,野心:5,性别:1,文化:19,介绍:"回鹘公主玛依娜，战场上看得见摸不着的美丽死神。"});
  外域美人.push({id:33,_code:5033,名称:"花蕊夫人",家族:"徐",地位:3,性格:[1,4],党:0,跳:33,武力:11,智力:90,政治:78,魅力:92,清廉:98,野心:30,性别:1,文化:20,介绍:"后蜀皇帝孟昶的贵妃，五代十国时期女诗人，青城（今都江堰市东南）人，姓徐，一说姓费，幼能文，尤长于宫词，得幸蜀主孟昶，赐号花蕊夫人。"});
  外域美人.push({id:34,_code:5034,名称:"李艳娘",家族:"李",地位:6,性格:[6,13],党:0,跳:34,统帅:96,武力:23,智力:85,政治:75,魅力:92,清廉:41,野心:68,性别:1,文化:20,介绍:"李艳娘，后蜀后主孟昶妃子，‘朝天髻’此发式的由来者。后蜀末代皇帝后主孟昶时期的舞娼，因献舞而入宫为妃，传封为昭容。李艳娘治发为高髻，号朝天髻，据说是因孟昶曾谱《万里朝天曲》因其备受孟昶宠爱，宫人民妇争相效仿。"});
  外域美人.push({id:35,_code:5035,名称:"周娥皇",家族:"周",地位:0,性格:[17,5],党:0,跳:35,统帅:17,武力:11,智力:77,政治:77,魅力:87,清廉:89,野心:30,性别:1,文化:21,介绍:"南唐司徒周宗长女，南唐后主李煜国后。精通音律，能歌善舞，尤工琵琶，曾搜寻五代时已失传的《霓裳羽衣曲》，改订为新曲。"});
  外域美人.push({id:36,_code:5036,名称:"周嘉敏",家族:"周",地位:3,性格:[10,12],党:0,跳:36,统帅:56,武力:88,智力:67,政治:32,魅力:92,清廉:73,野心:11,性别:1,文化:21,介绍:"五代十国时期南唐后主李煜的第二任皇后，史称“小周后”。其姊周娥皇重病沉疴时思念母家，李煜故召其妹入侍。她神彩端静，机敏有才思，与姐夫日久生情，故有“花明月暗笼轻雾，今宵好向郎边去”。大周后觉察后，面壁而卧，至死不愿复见二人一面。"});
  外域美人.push({id:37,_code:5037,名称:"宋明容",家族:"宋",地位:0,性格:[0,2],党:0,跳:37,统帅:50,武力:28,智力:89,政治:82,魅力:94,清廉:86,野心:24,性别:1,文化:22,介绍:"宋太祖赵匡胤的皇后，生母为后汉永宁公主，祖母为后唐义宁公主。出生于显贵之家的宋氏自幼出入宫廷，因而见多识广，进退有度。性情柔顺好礼，史称她每当太祖退朝，「常具冠帔候接，佐御馔」，足见夫妻情深。"});
  外域美人.push({id:38,_code:5038,名称:"闵兹映",家族:"闵",性格:[0,5],党:0,跳:38,统帅:78,武力:55,智力:90,政治:90,魅力:89,清廉:78,野心:60,性别:1,文化:0,介绍:"明成皇后，朝鲜近代史上的女政治家，本名闵兹映，通称闵妃。她是朝鲜王朝高宗李熙的王妃，骊兴闵氏外戚集团的核心人物，19世纪末朝鲜的实际统治者。由于明成皇后早期主张开放、后期力抗日本并身死殉难，故深受后世韩国人民的尊崇。"});
  外域美人.push({id:39,_code:5039,名称:"金德曼",家族:"金",性格:[40,7],党:0,跳:39,统帅:79,武力:56,智力:91,政治:81,魅力:88,清廉:79,野心:61,性别:1,文化:0,介绍:"金德曼，号圣祖皇姑，亦称善德王、善德女王，真平王金白净长女，母王妃摩耶夫人金氏，新罗国第27位君主。金德曼性格宽厚仁慈，聪明机敏。真平王五十四年（632年），其父真平王去世，因真平王无子，国人于是拥立金德曼继位，上尊号为圣祖皇姑，成为新罗国第一位女性君主。"});
  外域美人.push({id:40,_code:5040,名称:"张绿水",家族:"张",性格:[16,37],党:0,跳:40,统帅:80,武力:57,智力:82,政治:92,魅力:91,清廉:10,野心:62,性别:1,文化:0,介绍:"张绿水，李氏朝鲜中期的暴君燕山君宠妃。初为燕山君堂叔齐安大君)的家妓，一次宴会中得燕山君宠爱，初封淑媛，再封淑容，生燕山君庶长女李宁寿，中宗反正后与淑容田妃、淑媛金贵妃一同被处以斩首。 "});
  外域美人.push({id:41,_code:5041,名称:"张玉贞",家族:"张",性格:[40,37],党:0,跳:41,统帅:81,武力:58,智力:73,政治:93,魅力:92,清廉:11,野心:83,性别:1,文化:0,介绍:"张禧嫔，本名张玉贞，朝鲜肃宗的宠妃，朝鲜景宗李昀的生母。张玉贞出身中人，最早是身份卑微的普通宫女，因容貌出众而蒙受肃宗宠爱，诞下世子李昀，并于1689年取代仁显王后闵氏而成为朝鲜王妃，5年后降为禧嫔。1701年因被指控使用巫蛊诅咒仁显王后而被赐死。张禧嫔是朝鲜史上最具争议的女性：她美貌绝伦，聪明机敏，独宠于后宫，赢尽君王之心；她广植党羽，排斥异己，被称为朝鲜史上第一“妖妇”；从宫女到王妃，几度波折荣辱，却最终在宫斗中付出了生命的代价。 "});
  外域美人.push({id:42,_code:5042,名称:"玉漱",家族:undefined,性格:[1,3],党:0,跳:42,统帅:55,武力:45,智力:76,政治:78,魅力:91,清廉:72,野心:77,性别:1,文化:0,介绍:"玉漱，一名远离故乡的朝鲜图安国公主。"});
  外域美人.push({id:43,_code:5043,名称:"出云阿国",家族:"出云",性格:[5,4],党:0,跳:43,统帅:34,武力:12,智力:76,政治:34,魅力:95,清廉:80,野心:9,性别:1,文化:1,介绍:"日本古代著名女性歌舞伎表演者，同时是公认的歌舞伎的创始者。本为出云大社巫女，天生丽质，能歌善舞。"});
  外域美人.push({id:44,_code:5044,名称:"额田部",家族:undefined,性格:[0,17],党:0,跳:44,统帅:56,武力:12,智力:83,政治:96,魅力:85,清廉:90,野心:80,性别:1,文化:1,介绍:"日本推古天皇。钦明天皇之女，敏达天皇妹、皇后，崇峻天皇妹，日本历史上第33代天皇、第一位女天皇。即位初立侄儿圣德太子为皇太子。"});
  外域美人.push({id:45,_code:5045,名称:"清少纳言",家族:"清",性格:[5,24],党:0,跳:45,统帅:57,武力:13,智力:84,政治:97,魅力:86,清廉:71,野心:81,性别:1,文化:1,介绍:"清少纳言，日本平安时期著名的女作家，“王朝文学三才媛”之一。她出身贵族文官之家，晓畅和风，精通汉学，高雅自持，才华不凡。正历年间，她受选为皇后藤原定子身边的女房，协理后殿诸事，感怀倾慕之情。长保二年，定子难产去世，其罢职出宫，有和歌“我身孤寂远行，从此与君别；我心悲哀不舍，匆匆向远方”。她后将自己十年间宫廷生活执笔写著《枕草子》，被誉为“日本散文鼻祖”。"});
  外域美人.push({id:46,_code:5046,名称:"紫式部",家族:"藤原",性格:[16,29],党:0,跳:46,统帅:10,武力:10,智力:95,政治:55,魅力:81,清廉:66,野心:11,性别:1,文化:1,介绍:"紫式部，本姓藤原，日本平安时期著名女文学家，中古三十六歌仙之一。她出身于贵族文人世家，幼时从父学习汉学，通晓音律和佛典。父兄都擅长汉诗、和歌。主要作品有长篇小说《源氏物语》，作品描写人物心理细腻，文字典雅，情节曲折，被认为是世界最早的长篇小说，对往后日本文学之影响极大。1004年4月，紫式部丧夫寡居，同年秋开始创作《源氏物语》。35岁那年冬天，紫式部受召入宫侍奉一条天皇的中宫藤原彰子。"});
  外域美人.push({id:47,_code:5047,名称:"和泉式部",家族:"大江",性格:[16,37],党:0,跳:47,统帅:11,武力:11,智力:96,政治:56,魅力:82,清廉:97,野心:12,性别:1,文化:1,介绍:"和泉式部，日本平安时期的女诗人，位列中古三十六歌仙，日本平安京时代“王朝文学三才媛”之一。她的诗歌直抒胸怀，构思奇特，充满了新颖别致的魅力。她不仅是天才的诗人，而且是个热情奔放的绝代佳人。她风流多情，尚在婚内，罔顾名节，攀附皇族，与敦道亲王私通。其夫橘道贞愤而决裂，其父重义、亦与她公然断绝父女之名。和泉式部只身投奔亲王府上，为主母所不容，素日以仆妇视之。敦道身故后，她倚仗才名投效中宫彰子，为女房紫式部所耻，退返民间。"});
  外域美人.push({id:48,_code:5048,名称:"小野小町",家族:"小野",性格:[40,26],党:0,跳:48,统帅:55,武力:45,智力:86,政治:78,魅力:91,清廉:82,野心:77,性别:1,文化:1,介绍:"小野小町是日本平安京时代女诗人，世誉“六歌仙”之一。文德天皇继位，性好风雅，尤赏饱学之士，一时之间崇文之风盛行。她奉宣入宫，封作更衣，曾献和歌云“好花转瞬即飘零，此生虚度空余恨。泪眼终日何所以？连绵细雨不能晴”凄婉哀绵，文思轻灵。她少时成名，心比天高，却晚景凄凉，时有载称“因恃才色而骄慢"});
  外域美人.push({id:49,_code:5049,名称:"静御前",家族:"源",性格:[7,27],党:0,跳:49,统帅:20,武力:28,智力:70,政治:65,魅力:94,清廉:70,野心:10,性别:1,文化:1,介绍:"静御前，日本平安时代末期的人物，源义经之爱妾。日本古典三大美女之一。静御前的母亲是名白拍子，天资聪颖的她从小就跟着母亲学习舞蹈，14岁时为祈雨而舞，大雨倾盆而降，从此她以绝世舞女而闻名。15岁时成为了日本传奇英雄源义经的爱妾，但源义经因谋反的嫌疑被哥哥源赖朝追捕。静御前跟随义经逃亡来时被赖朝的兵抓获， 而后她受到严酷的审讯，但静御前坚决不供出丈夫的去向。源义经被杀害后，她被释放，回到京城削发为尼，并在不久后去世，年仅20岁。 "});
  外域美人.push({id:50,_code:5050,名称:"织田市",家族:"织田",性格:[0,7],党:0,跳:50,统帅:12,武力:12,智力:66,政治:78,魅力:96,清廉:64,野心:16,性别:1,文化:1,介绍:"日本战国时代女性，日本“古典三大美女”之一。父亲是织田信秀，长兄为织田信长。一般通称她为阿市夫人，或是小谷夫人。阿市16岁时，因为织田家的政治需求，信长将其嫁给浅井长政。八年后，因织田家与浅井家决裂，织田军攻陷浅井家居城小谷城，阿市回到了织田家。“本能寺之变”后，阿市痛恨杀死自己两个儿子的丰臣秀吉，并改嫁到处于秀吉对立面的柴田胜家。但在一年后，因羽柴秀吉攻陷北之庄城，阿市与丈夫一同在天守阁自尽。"});
  外域美人.push({id:51,_code:5051,名称:"明智玉子",家族:"明智",性格:[5,7],党:0,跳:51,统帅:55,武力:45,智力:76,政治:78,魅力:92,清廉:72,野心:77,性别:1,文化:1,介绍:"明智玉子，又名细川玉子，洗礼名：伽罗奢，日本“古典三大美女”之一。其父明智光秀勇冠三军，是“织田四天王”之一。玉子十六岁时嫁入细川家，因其父于本能寺叛变被杀而受到幽禁，在这期间接触了基督教，成为一名基督徒。玉子获释后因信仰问题与丈夫矛盾重重。在数年后爆发的关原大战中，丈夫忠兴随家康奔赴关东，石田三成想抓住玉子来胁迫忠兴投靠自己，玉子在双方对峙时自尽了。关原之战后，明智玉子作为贞女获得很高声誉，在近代后又被称赞为“基督教的忠实信徒”。"});
  外域美人.push({id:52,_code:5052,名称:"斋藤归蝶",家族:"斋藤",性格:[0,17],党:0,跳:52,统帅:55,武力:45,智力:86,政治:78,魅力:91,清廉:82,野心:77,性别:1,文化:1,介绍:"斋藤归蝶是日本战国时代大名织田信长的正室，“战国三夫人”之一。她聪慧绝艳，颇具魄力，为信长所娶，有号“浓姬”。"});
  外域美人.push({id:53,_code:5053,名称:"宁宁",家族:"杉原",性格:[1,2],党:0,跳:53,统帅:27,武力:16,智力:87,政治:82,魅力:80,清廉:95,野心:20,性别:1,文化:1,介绍:"丰臣秀吉的妻子，也叫“於祢”或“祢祢”，宁宁一直被视为丰臣家武断派精神领袖，虽终身未育，但却一直作为母亲照顾着秀吉培养的年轻武士们，支持着秀吉的霸业。秀吉成为关白后，被称为“北政所”。过世后，就葬在京都的高台寺，法名高台院湖月尼。"});
  外域美人.push({id:54,_code:5054,名称:"笃姬",家族:"近卫",性格:[0,6],党:0,跳:54,统帅:28,武力:17,智力:88,政治:83,魅力:81,清廉:96,野心:21,性别:1,文化:1,介绍:"笃姬，日本江户时代后期到明治时期的女性，出生于萨摩藩岛津家的一门，成为岛津本家的养女。作为五摄家笔头・近卫家的女儿嫁入德川家，成为江户幕府第13代将军・德川家定御台所。在幕府末年骚乱和明治维新初期发挥了很大的斡旋作用，是19世纪后半叶一名优秀的政治家，被史家目为一个秀外慧中、视界高远、多谋善断的杰出女性，在日本近代史上影响重大也极受推崇的一人。"});
  外域美人.push({id:55,_code:5055,名称:"和宫亲子",家族:"和宫",性格:[14,12],党:0,跳:55,统帅:29,武力:18,智力:79,政治:64,魅力:88,清廉:67,野心:22,性别:1,文化:1,介绍:"和宫亲子内亲王，出生于京都，仁孝天皇第八皇女，桂宫淑子内亲王和孝明天皇的异母妹，明治天皇的姑姑，生母为典侍观行院。和宫内亲王之父仁孝天皇于她出生前数月已驾崩，故为遗腹女。1862年下嫁德川家茂，史称和宫降嫁，孝明天皇希望借此结合朝廷和幕府力量以达攘。倒幕运动中，和宫应15代将军德川庆喜之请，向朝廷游说，在德川家的存续问题上出力甚多。"});
  外域美人.push({id:56,_code:5056,名称:"拔速儿",家族:undefined,性格:[24,25],党:0,跳:56,统帅:34,武力:43,智力:53,政治:43,魅力:93,清廉:67,野心:13,性别:1,文化:2,介绍:"复姓皋兰,芳名拔速儿。是九姓铁勒当中的第七姓大酋长之女。"});
  外域美人.push({id:57,_code:5057,名称:"阿史那冰",家族:"阿史那",性格:[12,10],党:0,跳:57,统帅:32,武力:55,智力:63,政治:43,魅力:92,清廉:45,野心:10,性别:1,文化:2,介绍:"突厥贵族之女，突厥部落的著名美女。阿史那·冰。"});
  外域美人.push({id:58,_code:5058,名称:"阿史那颂",家族:"阿史那",性格:[8,9],党:0,跳:58,统帅:33,武力:66,智力:74,政治:44,魅力:90,清廉:46,野心:41,性别:1,文化:2,介绍:"阿史那皇后，突厥族，北周武帝宇文邕皇后，突厥木杆可汗阿史那燕都之女。有姿貌，美容止。天和三年（568年），嫁给北周武帝宇文邕，册立为皇后。宣政元年（578年），北周宣帝宇文贇即位，尊为皇太后。大象元年（579年），北周静帝宇文阐即位后，尊为天元上皇太后。大象二年（580年），尊为太皇太后。"});
  外域美人.push({id:59,_code:5059,名称:"弟史",家族:undefined,性格:[4,6],党:0,跳:59,统帅:22,武力:46,智力:56,政治:43,魅力:89,清廉:67,野心:52,性别:1,文化:2,介绍:"汉解忧公主与乌孙王翁归靡之女，龟兹年轻的国王绛宾之妻。"});
  外域美人.push({id:60,_code:5060,名称:"阿姬曼",家族:undefined,性格:[1,5],党:0,跳:60,统帅:12,武力:12,智力:52,政治:42,魅力:98,清廉:23,野心:78,性别:1,文化:3,介绍:"阿姬曼·芭奴，沙贾汗库拉姆的宠妃，一位具有波斯血统的绝世美女，泰姬陵的主人。阿姬曼性情温柔，擅诗琴书画。她婚后与库拉姆同甘共苦，行影相随，足迹遍布疆场。库拉姆经过一场血战继承王位，给自己取名沙贾汗，意为世界之王。阿姬曼也因此得到宫中最高头衔——泰姬·马哈尔。但是好景不长，阿姬曼、在跟随沙贾汗南征时因难产而死，年仅39岁。沙贾汗伤心欲绝，他决定为宠妃建造泰姬陵，以表达他对宠妃的思念之情。"});
  外域美人.push({id:61,_code:5061,名称:"耶输陀罗",家族:undefined,性格:[0,4],党:0,跳:61,统帅:34,武力:12,智力:90,政治:75,魅力:97,清廉:86,野心:10,性别:1,文化:3,介绍:"中印度迦毗罗城释种执杖之女，悉达多太子之正妃，罗侯罗之生母。为婆私吒族释种大臣摩诃那摩之女。相好端严，姝妙第一，具诸德貌。悉达多悟道五年后，与悉达多之姨母摩诃波阇波提等五百名释迦族女，跟随佛陀出家剃染受具足戒为比丘尼。后证阿罗汉果。"});
  外域美人.push({id:62,_code:5062,名称:"善无续",家族:undefined,性格:[17,8],党:0,跳:62,统帅:74,武力:24,智力:83,政治:92,魅力:88,清廉:90,野心:33,性别:1,文化:3,介绍:"阿育王首席王后，温顺善良，信奉佛法，全身心的扶助阿育王。"});
  外域美人.push({id:63,_code:5063,名称:"摩诃摩耶",家族:undefined,性格:[0,2],党:0,跳:63,统帅:23,武力:23,智力:90,政治:96,魅力:91,清廉:88,野心:56,性别:1,文化:3,介绍:"释迦牟尼生母。原为中印度天臂城善觉王之女，迦毗罗卫国净饭王之妻。生下佛陀后的第七天就逝世了，当佛陀涅盘时，摩耶夫人特地从上天赶到火葬场，佛陀听说母亲来，便从金棺中坐起，为母亲说法，以尽孝道。"});
  外域美人.push({id:64,_code:5064,名称:"龙弭祢",家族:undefined,性格:[10,29],党:0,跳:64,统帅:25,武力:32,智力:45,政治:56,魅力:94,清廉:67,野心:13,性别:1,文化:3,介绍:"印度迦毗罗卫国附近之天臂城主善觉王之妃。"});
  外域美人.push({id:65,_code:5065,名称:"拉娔诗米",家族:undefined,性格:[1,19],党:0,跳:65,统帅:25,武力:32,智力:45,政治:56,魅力:96,清廉:67,野心:13,性别:1,文化:3,介绍:"吉祥天女，婆罗门教-印度教的幸福与财富女神，传统上被认为是毗湿奴的妻子。她的像多为丰满美女，面带慈祥微笑。坐骑为白色猫头鹰、金翅鸟。 有“大功德”于众，因而旧称功德天。"});
  外域美人.push({id:66,_code:5066,名称:"帝失罗叉",家族:undefined,性格:[33,36],党:0,跳:66,统帅:34,武力:28,智力:67,政治:52,魅力:90,清廉:37,野心:68,性别:1,文化:3,介绍:"古印度摩羯陀国孔雀王朝阿育王的王后，原为善无续的女仆。阿育王崇信佛教，爱敬菩提树，帝失罗叉嫉恨之，乃令咒术师咒杀该树，令其枯死。此外，又爱恋王子鸠那罗，但王子宁守净法而死，不肯行非法之事，帝失罗叉大怒，乃伺求其过错而加以中伤，王子因此遭受放逐。后又假造王命抉出王子双眼。其后，阿育王知悉全事始末，遂将帝失罗叉处死。"});
  外域美人.push({id:67,_code:5067,名称:"帕凡提",家族:undefined,性格:[8,7],党:0,跳:67,统帅:23,武力:23,智力:90,政治:96,魅力:92,清廉:88,野心:56,性别:1,文化:3,介绍:"湿婆的神妃之一，喜马拉雅山的雪山女神，有着绝世的美貌。她与湿婆之间的爱情故事是印度古文化里最动人的篇章之一。在战场上也会变化为狞猛的战神。"});
  外域美人.push({id:68,_code:5068,名称:"萧观音",家族:"萧",性格:[1,5],党:0,跳:68,统帅:28,武力:31,智力:90,政治:67,魅力:93,清廉:83,野心:40,性别:1,文化:4,介绍:"辽道宗耶律洪基的第一任皇后。辽代著名女诗人。相貌颖慧秀逸，娇艳动人，个性内向纤柔，很有才华，常常自制歌词，精通诗词、音律，善于谈论。她弹得一手好琵琶，也有诗作，被辽道宗誉为女中才子。"});
  外域美人.push({id:69,_code:5069,名称:"萧耨斤",家族:"萧",性格:[30,38],党:0,跳:69,统帅:73,武力:31,智力:87,政治:87,魅力:92,清廉:25,野心:86,性别:1,文化:4,介绍:"出身后族萧氏，辽圣宗耶律隆绪的宠妃，兴宗耶律宗真的生母。她虽为后族女子，母家却非族中显贵，又为庶出，送入后宫为婢。其初侍奉太后萧绰，萧太后以她面相贵子故命圣宗与其同房，生子名宗真。其借己子投靠中宫，跃居正一品元妃，巧邀帝宠，长伴圣驾，协理奏疏。圣宗崩，她乘机窃取军政大权，伪诏自立圣母皇太后，两宫太后并尊自此而始，。她冤杀菩萨哥，垂帘听政，称法天皇太后。公元1034年，兴宗夺权，其撤帘归政，退居庆州行宫。"});
  外域美人.push({id:70,_code:5070,名称:"萧菩萨哥",家族:"萧",性格:[1,2],党:0,跳:70,统帅:33,武力:31,智力:85,政治:67,魅力:92,清廉:83,野心:43,性别:1,文化:4,介绍:"出身后族萧氏，辽圣宗耶律隆绪的皇后，兴宗耶律宗真的养母。其秉性良善，婉约谦顺。帝后恩爱，龙凤和鸣，但所生二嫡子早夭。宫人萧耨斤有宠一夜得孕生子，藉助此子投好皇后。她自宗真尚在襁褓时便抚育身边，事无巨细，亲力亲为。耶律宗真继位后，其受尊母后皇太后，东西两宫权争愈烈。萧耨斤诬害她与宰相谋反，在帝春猎离宫时逼令菩萨哥自杀。西宫摄政三年，兴宗宫变夺权，幽囚生母，终得亲政。追谥仁德皇后，安葬庆陵。"});
  外域美人.push({id:71,_code:5071,名称:"萧坦思",家族:"萧",性格:[5,17],党:0,跳:71,统帅:74,武力:32,智力:88,政治:88,魅力:93,清廉:66,野心:87,性别:1,文化:4,介绍:"萧坦思，辽道宗耶律洪基第二任皇后，驸马都尉萧霞抹的妹妹。大康二年（1076年），在宰相耶律乙辛推荐下，选入掖庭，六月立为皇后。几年后，无子嗣，又将其妹、与耶律乙辛子耶律绥离婚的萧斡特懒，纳入宫中。大康八年（1082年），皇孙耶律延禧（天祚帝）封梁王，十二月萧坦思降为惠妃，徙至乾陵。不久因其母燕国夫人诅咒梁王，获罪伏诛，而贬萧坦思为庶人，幽居宜州。天庆六年（1116年）萧坦思被天祚帝召还，封太皇太妃。"});
  外域美人.push({id:72,_code:5072,名称:"述律月理朵",家族:"述律",性格:[0,7],党:0,跳:72,统帅:75,武力:33,智力:89,政治:89,魅力:94,清廉:67,野心:88,性别:1,文化:4,介绍:"述律平，字月理朵，辽太祖耶律阿保机皇后。果断有智谋，多权变。辽太祖灭亡渤海后，尊号“地皇后”。辽太祖率军攻击党项时，奉命留守汗帐。室韦部落趁机偷袭契丹，为述律皇后所得知，亲帅大军击破敌军，从此威震四方。天显元年（926年），辽太祖崩逝，述律平临朝称制摄政，掌理军国大事。辽太祖即将下葬时，她砍下右手装入棺木里，作为陪葬，世称“断腕太后”。"});
