  外域美人.push({id:75,_code:5075,名称:"柏洁",家族:undefined,性格:[17,5],党:0,跳:75,统帅:51,武力:13,智力:84,政治:74,魅力:85,清廉:81,野心:45,性别:1,文化:5,介绍:"柏洁夫人，相传为唐代云南邆赕诏女英雄。亦称柏节圣妃、慈善夫人、宁北妃。白族先民。六诏之一邆赕诏主皮罗邆妻。"});
  外域美人.push({id:76,_code:5076,名称:"紫萱",家族:undefined,性格:[1,17],党:0,跳:76,统帅:12,武力:16,智力:70,政治:70,魅力:86,清廉:90,野心:30,性别:1,文化:5,介绍:"紫萱，为女娲后裔，徐长卿的三世恋人。饱受情爱煎熬三生三世。"});
  外域美人.push({id:77,_code:5077,名称:"抛容女",家族:undefined,性格:[25,27],党:0,跳:77,统帅:34,武力:34,智力:80,政治:65,魅力:96,清廉:64,野心:69,性别:1,文化:6,介绍:"弃松德赞之妻。弃松德赞退位时，将其赐给牟尼赞晋。在弃松德赞丧事期间，抛容女仍然浓装艳抹，毫无悲伤之情。"});
  外域美人.push({id:78,_code:5078,名称:"赛玛噶",家族:undefined,性格:[18,19],党:0,跳:78,统帅:12,武力:11,智力:45,政治:56,魅力:87,清廉:72,野心:12,性别:1,文化:6,介绍:"松赞干布的妹妹。嫁给了象雄王，象雄王宠爱另一个妃子而冷待赛玛噶。最后象雄被松赞干布灭了。"});
  外域美人.push({id:79,_code:5079,名称:"赤玛洛",家族:undefined,性格:[29,35],党:0,跳:79,统帅:51,武力:13,智力:84,政治:74,魅力:85,清廉:20,野心:45,性别:1,文化:6,介绍:"赤玛洛是吐蕃王朝第三十四代赞普芒松芒赞的王后。公元676年，芒松芒赞去世，新王赤都松赞年仅十四，王太后赤玛洛全力辅佐儿子理政。国中有噶尔家族，自禄东赞入唐经六试婚使、为先王松赞干布求得婚诏后，因功显贵，传至其子论钦陵。彼时赞普年幼，论钦陵拥势自重。她扶植自己的亲信重臣，诛除论钦陵，驱逐噶尔一族"});
  外域美人.push({id:80,_code:5080,名称:"托米丽丝",家族:undefined,性格:[7,25],党:0,跳:80,统帅:78,武力:80,智力:34,政治:23,魅力:81,清廉:93,野心:33,性别:1,文化:7,介绍:"一位领军对抗波斯的为子报仇的年轻妃子。"});
  外域美人.push({id:81,_code:5081,名称:"西尔维娅",家族:undefined,性格:[17,8],党:0,跳:81,统帅:21,武力:12,智力:36,政治:35,魅力:96,清廉:56,野心:67,性别:1,文化:7,介绍:"古罗马神话，战神马耳斯的妻子，埃涅阿斯的后代阿尔巴·隆伽城国王努弥托耳的女儿，罗马的奠基人罗穆路斯和瑞穆斯的母亲。"});
  外域美人.push({id:82,_code:5082,名称:"海伦",家族:undefined,性格:[4,5],党:0,跳:82,统帅:21,武力:12,智力:36,政治:35,魅力:100,清廉:50,野心:50,性别:1,文化:7,介绍:"海伦是宙斯跟勒达所生的女儿，在她的后父斯巴达国王廷达瑞俄斯的宫里长大。她是在人间里最漂亮的女人。"});
  外域美人.push({id:83,_code:5083,名称:"雅典娜",家族:undefined,性格:[40,5],党:0,跳:83,统帅:99,武力:99,智力:99,政治:78,魅力:99,清廉:85,野心:20,性别:1,文化:7,介绍:"希腊神话中的奥林波斯十二神之一，智慧女神，女战神。"});
  外域美人.push({id:84,_code:5084,名称:"玛丽娅",家族:"特蕾莎",性格:[0,25],党:0,跳:84,统帅:67,武力:34,智力:88,政治:57,魅力:92,清廉:45,野心:88,性别:1,文化:7,介绍:"玛丽娅·特蕾莎，奥地利国母和女大公，匈牙利和波希米亚女王。神圣罗马帝国皇帝查理六世之女，出生在奥地利的霍夫堡皇宫，凭借尊贵的血统得到了奥地利、匈牙利、波希米亚三顶王冠。"});
  外域美人.push({id:85,_code:5085,名称:"赫西俄涅",家族:undefined,性格:[3,19],党:0,跳:85,统帅:33,武力:33,智力:63,政治:31,魅力:97,清廉:55,野心:55,性别:1,文化:7,介绍:"特洛伊国王拉俄墨冬之女。传说太阳神阿波罗和海神波塞冬为特洛伊筑起防御城墙和堡垒，但拉俄墨冬却拒绝回礼。于是波塞冬便引发了洪水，拉俄墨冬无奈将公主作为海怪祭品以平神怒。"});
  外域美人.push({id:86,_code:5086,名称:"潘多拉",家族:undefined,性格:[39,34],党:0,跳:86,统帅:11,武力:11,智力:11,政治:11,魅力:99,清廉:22,野心:88,性别:1,文化:7,介绍:"希腊神话中赫淮斯托斯用粘土做成的第一个女人，作为对普罗米修斯盗火的惩罚，送给人类的第一个女人。众神赠予使她拥有更诱人的魅力的礼物，唯独雅典娜拒绝给予她智慧，所以潘多拉的行动都是不经思考的。"});
  外域美人.push({id:87,_code:5087,名称:"安托瓦内特",家族:undefined,性格:[35,36],党:0,跳:87,统帅:12,武力:12,智力:12,政治:12,魅力:90,清廉:23,野心:89,性别:1,文化:7,介绍:"玛丽·安托瓦内特，法国王后，法国国王路易十六的妻子。安托瓦内特在政治上毫无建树，从进入法国宫廷后每天只是热衷于舞会、玩乐、乔装打扮，修饰花园，奢侈无度，有“赤字夫人”之称。法国大革命时，她却意外地表现得比路易十六更有主见和顽固。法国对奥地利宣战后她继续勾结奥地利，并把作战计划提供给外国，企图借外部势力镇压革命。叛国的事情败露后激怒了法国人民，导致8月巴黎人民起义，彻底推翻了君主制。次年10月，被安托瓦内特交付给革命法庭审判，判处死刑，送上断头台。"});
  外域美人.push({id:88,_code:5088,名称:"凯瑟琳",家族:undefined,性格:[19,27],党:0,跳:88,统帅:13,武力:13,智力:13,政治:13,魅力:91,清廉:24,野心:90,性别:1,文化:7,介绍:"凯瑟琳，卡斯蒂利亚女王伊莎贝尔一世和阿拉贡国王费尔南多二世的女儿，英格兰国王亨利八世的王后。凯瑟琳生育了几次，其中幸存下来的只有病弱的威尔士公主玛丽，亨利认定凯瑟琳不能为他生下男性继承人，于是便向教皇申请离婚。但教皇克雷芒七世迟迟不批准离婚。1533年2月，亨利秘密与安妮·博林结婚。此后，凯瑟琳在金博尔顿城堡内度过了余生。"});
  外域美人.push({id:89,_code:5089,名称:"博林",家族:undefined,性格:[30,36],党:0,跳:89,统帅:14,武力:14,智力:14,政治:14,魅力:92,清廉:25,野心:91,性别:1,文化:7,介绍:"安妮·博林，英格兰国王亨利八世的王后，女王伊丽莎白一世之母。安妮·博林原本是亨利八世的王后凯瑟琳的侍从女官，但两人在暗中偷情。为了与安妮结婚，亨利八世发动了宗教改革，永远地改变了英国的历史。安妮·博林在1533年1月与亨利八世秘密结婚，几个月后亨利八世对她的热情消退，直到9月生下伊丽莎白一世后才稍和缓。但两人关系在1536年1月安妮·博林流产时更加恶化，5月安妮·博林以通奸罪被捕入狱，囚禁在伦敦塔，19日被斩首。"});
  外域美人.push({id:90,_code:5090,名称:"西摩",家族:undefined,性格:[29,35],党:0,跳:90,统帅:15,武力:15,智力:15,政治:15,魅力:93,清廉:26,野心:92,性别:1,文化:7,介绍:"珍·西摩，英格兰国王亨利八世的王后，爱德华六世之母。她是威尔特郡约翰爵士之女，被送入宫廷成为新晋王后博林的女官。亨利八世在博林怀孕待产期间，与西摩发生私情，此事极大地刺激了王后的精神状态，并最终导致流产。1536年，亨利在将博林王后斩首的第二天，就与她结婚。1537年10月，王后难产，分娩持续了两天三夜，才生下爱德华王子。同日，西摩死于产褥热。亨利此后三年未立新后，宣称西摩是此生的至爱，并将她葬在自己的墓旁。"});
  外域美人.push({id:91,_code:5091,名称:"阿佛洛狄忒",家族:undefined,性格:[16,13],党:0,跳:91,统帅:56,武力:16,智力:86,政治:66,魅力:90,清廉:67,野心:73,性别:1,文化:7,介绍:"古希腊神话中爱与美的女神，奥林匹斯十二主神之一。在英雄佩琉斯与海洋女神忒提丝婚礼上，灾厄女神厄里斯是唯一未受邀请的神明，出于报复送来“献给最美神”的金苹果，引发赫拉、雅典娜和阿佛洛狄忒的争斗。三女神请帕里斯王子评判，赫拉许以万人之上的富贵权势，雅典娜许以战无不胜的军神荣耀，她许以倾国倾城的绝世红颜，赢得苹果。此事成为特洛伊战争的发端。"});
  外域美人.push({id:92,_code:5092,名称:"卢克雷齐娅",家族:"博尔吉亚",性格:[13,16],党:0,跳:92,统帅:55,武力:45,智力:76,政治:78,魅力:96,清廉:42,野心:77,性别:1,文化:7,介绍:"卢克雷齐娅Lucrezia是费拉拉、摩德纳和雷吉奥公爵夫人，罗马教皇亚历山大六世私生女，瓦伦蒂诺大公爵西泽尔·博尔吉亚的妹妹。出身为贵族的她，长期赞助艺术家从事美术等相关事务，是欧洲文艺复兴时期的幕后支持者之一。她的父兄为了满足自己的政治野心，前后为她安排了三次与重要的有权势的男人联姻。 传言与兄长西泽尔有不伦之恋。"});
  外域美人.push({id:93,_code:5093,名称:"希尔芙",家族:undefined,性格:[18,19],党:0,跳:93,统帅:66,武力:74,智力:83,政治:79,魅力:93,清廉:45,野心:85,性别:1,文化:7,介绍:"希尔芙是风的精灵，微风就是精灵的低语，凡是心灵纯洁的人最终都会变为希尔芙。"});
  外域美人.push({id:94,_code:5094,名称:"温蒂妮",家族:undefined,性格:[10,12],党:0,跳:94,统帅:67,武力:75,智力:84,政治:80,魅力:94,清廉:46,野心:86,性别:1,文化:7,介绍:"温蒂妮是居于水边的美丽女性精灵，是一切水元素的主宰。她们多在森林中的湖泊及瀑布附近出没，拥有甜美的嗓音，有时会盖过流水的声音。"});
  外域美人.push({id:95,_code:5095,名称:"萧唤云",家族:"萧",性格:[32,29],党:0,跳:95,统帅:23,武力:23,智力:70,政治:58,魅力:94,清廉:77,野心:49,性别:1,文化:8,介绍:"萧唤云是孝昭帝的贵妃，高湛的初恋情人，梁国的永世公主。她聪明而有心计，一直喜欢着储君高湛，因为家仇国恨却嫁给了自己不爱的高演，目睹着陆贞和高湛的心心相印，嫉妒和无奈充斥着她的内心，她不容许自己的初恋心中最后留下的却是她的背影，她迫害陆贞，伤害高湛。后来，她被高演感动，与他和好，并怀有一子高纬，后难产而死。"});
  外域美人.push({id:96,_code:5096,名称:"李祖娥",家族:"李",性格:[17,21],党:0,跳:96,统帅:22,武力:22,智力:85,政治:90,魅力:94,清廉:90,野心:22,性别:1,文化:8,介绍:"齐昭信皇后，李希宗之女。容德甚美，温婉可爱，才貌双全，十几岁时，倾国倾城，成为太原公夫人，之后更是步步高升，高洋称帝，李祖娥变成了可贺敦皇后。高洋死后，长子高殷既位，尊母为皇太后。乾明政变后，高殷被废为济南王，李祖娥迁居昭信宫。武成帝高湛继位后，遭武成帝高湛淫乱，并怀有身孕。后又生女不举，因此遭到高湛严重鞭笞，儿子也为高湛杀害，遂入妙胜尼寺为尼。"});
  外域美人.push({id:97,_code:5097,名称:"阴丽华",家族:"阴",性格:[5,8],党:0,跳:97,统帅:45,武力:34,智力:90,政治:83,魅力:92,清廉:86,野心:20,性别:1,文化:8,介绍:"光武帝刘秀原配 ，东汉第二任皇后，春秋时期名相管仲后裔，汉明帝刘庄的生母。阴丽华在历史上以美貌著称。"});
  外域美人.push({id:98,_code:5098,名称:"骊姬",家族:"骊",性格:[29,35],党:0,跳:98,统帅:12,武力:10,智力:53,政治:60,魅力:94,清廉:19,野心:80,性别:1,文化:8,介绍:"春秋时代女性，骊戎国君的女儿，骊戎的公主，奚齐生母，申生、重耳、夷吾、穆姬后母，因姿色艳美，后被晋献公掳去，而成为宠妃。"});
  外域美人.push({id:99,_code:5099,名称:"妺喜",家族:"有施",性格:[37,35],党:0,跳:99,统帅:33,武力:18,智力:44,政治:44,魅力:90,清廉:22,野心:88,性别:1,文化:8,介绍:"有施氏之女，夏桀的王后。“有施妺喜，眉目清兮。妆霓彩衣，袅娜飞兮。晶莹雨露，人之怜兮。”"});
  外域美人.push({id:100,_code:5100,名称:"妫翟",家族:"妫",性格:[16,6],党:0,跳:100,统帅:11,武力:11,智力:75,政治:78,魅力:92,清廉:78,野心:16,性别:1,文化:8,介绍:"亦称息夫人，人称“桃花夫人”。生卒年不详，春秋初期陈国公主。本系息侯夫人，楚文王灭掉息国后掠其为宠妾。也有说法称埋葬地遍植桃花，所以被称为桃花夫人。"});
  外域美人.push({id:101,_code:5101,名称:"栗姬",家族:"栗",性格:[32,34],党:0,跳:101,统帅:22,武力:11,智力:56,政治:34,魅力:97,清廉:77,野心:17,性别:1,文化:8,介绍:"栗姬艳冠京城，能歌善舞。一次刘启来到民间，将栗姬带回宫，封栗姬为孺子。而后栗姬为刘启生下儿子，地位如同侧妃。"});
  外域美人.push({id:102,_code:5102,名称:"芈月",家族:"芈",性格:[0,29],党:0,跳:102,统帅:45,武力:34,智力:90,政治:83,魅力:92,清廉:86,野心:20,性别:1,文化:8,介绍:"芈姓，又称芈八子、秦宣太后。战国时期秦国王太后，秦惠文王之妾，秦昭襄王之母。秦昭襄王即 位之初，宣太后以太后之位主政，执政期间，攻灭义渠国，一举灭亡了秦国的西部大患。"});
  外域美人.push({id:103,_code:5103,名称:"李裹儿",家族:"李",性格:[39,36],党:0,跳:103,统帅:43,武力:21,智力:91,政治:67,魅力:94,清廉:12,野心:96,性别:1,文化:8,介绍:"李裹儿，唐安乐公主，唐中宗李显之女，韦氏所生，有唐朝第一美人之称。她先嫁给武三思之子武崇训，后又嫁给武承嗣之子武延秀。在唐中宗统治时期，她大肆开府设官，干预朝政，贿买官爵，宰相以下的官员多出其门。她曾向中宗请求立她为皇太女，权力欲望极强。她的生活非常奢侈，为了大兴土木工程，抢占民田民房。为做皇太女，与母亲韦后毒杀中宗。后李隆基发动政变，诛杀安乐公主，追废为“悖逆庶人”。"});
  外域美人.push({id:104,_code:5104,名称:"刘伯姬",家族:"刘",性格:[5,7],党:0,跳:104,统帅:83,武力:67,智力:88,政治:72,魅力:95,清廉:81,野心:46,性别:1,文化:8,介绍:"东汉光武帝刘秀的幼妹，封宁平长公主。她性情聪慧，深明大义，英姿飒爽，不让须眉。刘秀从军时，其亦在后方支持兄长，常往来奔走劳军。棘阳一战，面对王莽新朝军奇袭，她在城内兵防空虚的情况下，组织妇老残兵坚守棘阳，成功等到汉军主力回师合围，全歼敌兵，士气大振，奠定东汉一统天下之基。"});
  外域美人.push({id:105,_code:5105,名称:"唆鲁禾帖尼",家族:"克烈",性格:[0,7],党:0,跳:105,统帅:48,武力:63,智力:82,政治:35,魅力:89,清廉:54,野心:42,性别:1,文化:10,介绍:"蒙古克烈部人，元睿宗孛儿只斤·拖雷的皇后，其性情果决，深谋远虑，定宗贵由崩后，皇后海迷失摄政乱权，她笼络各方势力，终在库里台大会政变拥立己子蒙哥，并严令儿子必杀海迷失。其幼子旭烈兀吞并西辽契丹，建伊利汗国。"});
  外域美人.push({id:106,_code:5106,名称:"海迷失",家族:"斡兀立",性格:[30,39],党:0,跳:106,统帅:45,武力:47,智力:79,政治:78,魅力:88,清廉:28,野心:82,性别:1,文化:10,介绍:"海迷失后。1248年贵由汗卒，海迷失在拔都等诸王拥立下垂帘听政，称制三年。在她统治期间，诸王争权，连遭天灾，国内一片混乱，1251年蒙哥（元宪宗）被推举为大汗。海迷失因暗中从事反对蒙哥的活动，被投入河中溺死。"});
