  外域美人.push({id:112,_code:5112,名称:"安美依迪丝",家族:"米底",性格:[2,6],党:0,跳:112,统帅:12,武力:12,智力:52,政治:42,魅力:98,清廉:23,野心:78,性别:1,文化:11,介绍:"巴比伦王国的尼布甲尼撒二世王妃，巴比伦空中花园就是为她而建造的。"});
  外域美人.push({id:113,_code:5113,名称:"以斯帖",家族:undefined,性格:[0,29],党:0,跳:113,统帅:23,武力:23,智力:90,政治:96,魅力:97,清廉:88,野心:56,性别:1,文化:11,介绍:"《圣经·旧约·以斯帖记》中的女主角，古代波斯的王后，她运用自己的智慧，在当时波斯王的面前揭露了阴谋家，粉碎了哈曼阴谋消灭波斯境内犹太人的罪恶计划。"});
  外域美人.push({id:114,_code:5114,名称:"玛那特",家族:undefined,性格:[2,3],党:0,跳:114,统帅:25,武力:32,智力:45,政治:56,魅力:98,清廉:67,野心:13,性别:1,文化:11,介绍:"阿拉伯司命运女神。玛那特的偶像被塑立在麦加与麦地那之间的海滩，邻近库戴德的穆沙勒，所有的阿拉伯人都曾经敬拜玛那特，并向她献祭。"});
  外域美人.push({id:115,_code:5115,名称:"茉莉",家族:undefined,性格:[30,6],党:0,跳:115,统帅:23,武力:23,智力:70,政治:65,魅力:98,清廉:78,野心:53,性别:1,文化:11,介绍:"故事《阿拉丁神灯》中的主人公。茉莉公主是苏丹王的女儿，一个聪明，有主见，勇敢却有点孤独的美丽公主。"});
  外域美人.push({id:116,_code:5116,名称:"雅思敏",家族:undefined,性格:[7,25],党:0,跳:116,统帅:24,武力:85,智力:63,政治:68,魅力:96,清廉:68,野心:54,性别:1,文化:11,介绍:"一名经波斯大臣在贵族间精挑细选，联姻中原的秀女。雅思敏冷傲绝丽，曾与波斯王子卑路斯缔结有婚约。"});
  外域美人.push({id:117,_code:5117,名称:"阿莱克莎",家族:undefined,性格:[5,24],党:0,跳:117,统帅:64,武力:82,智力:76,政治:79,魅力:90,清廉:58,野心:34,性别:1,文化:11,介绍:"阿莱克莎灵动飘逸，本是雪山一族献给波斯皇帝的圣女。"});
  外域美人.push({id:118,_code:5118,名称:"罗克珊娜",家族:undefined,性格:[16,13],党:0,跳:118,统帅:42,武力:23,智力:63,政治:81,魅力:86,清廉:76,野心:44,性别:1,文化:11,介绍:"粟特族人，古巴比伦王国著名美女。马其顿帝国亚历山大三世亲征巴比伦，广袤的底格里斯河、富饶的美索不达米亚，尽皆臣服于这位传奇霸主之下。罗克珊娜是王国贵族之女，俘献于亚历山大，其惊人的美貌获得了大帝的垂怜，产下的男婴、取名为艾古斯。他继而挥师强盛的波斯帝国，大流士三世兵败逃亡。亚历山大爱上了以“波斯第一美女”之名响彻世间的斯妲忒拉，将罗克珊娜母子抛忘脑后。"});
  外域美人.push({id:119,_code:5119,名称:"斯妲忒拉",家族:undefined,性格:[10,29],党:0,跳:119,统帅:35,武力:43,智力:64,政治:57,魅力:90,清廉:74,野心:43,性别:1,文化:11,介绍:"斯妲忒拉一世，波斯帝国阿契美尼德王朝公主，最后一个沙阿大流士三世的姐妹、妻子和王后。大流士三世战败后被俘于希腊军中，斯妲忒拉一世难产而死。"});
  外域美人.push({id:120,_code:5120,名称:"纳菲泰莉",家族:undefined,性格:[10,5],党:0,跳:120,统帅:11,武力:11,智力:36,政治:27,魅力:96,清廉:53,野心:50,性别:1,文化:12,介绍:"拉美西斯二世钟爱的王妃。法老王不但深爱着她，而且无论到哪里都有影皆双，还专门为王妃建立了一座神殿，人们称者是当时埃及最大的情人礼物，也是古代一个动人的爱情故事。"});
  外域美人.push({id:121,_code:5121,名称:"伊丝塔尔",家族:undefined,性格:[16,37],党:0,跳:121,统帅:23,武力:23,智力:44,政治:33,魅力:99,清廉:23,野心:97,性别:1,文化:12,介绍:"爱神伊丝塔尔与农神恩奇都一见钟情，但哥哥乌图却让她与牧神结合，从此伊丝塔尔变得放荡且喜欢虐待情人。英雄吉尔伽美什打败了怪物，救出了伊丝塔尔。伊丝塔尔因感恩而向他求爱，但因水性杨花，且不善待男友，遭到后者的严厉拒绝。（伯爵：其实是因为恩奇都吧!哈哈哈）"});
  外域美人.push({id:122,_code:5122,名称:"奈费尔提提",家族:undefined,性格:[0,7],党:0,跳:122,统帅:43,武力:42,智力:88,政治:83,魅力:85,清廉:67,野心:67,性别:1,文化:12,介绍:"埃及历史上最有名的美人之一。十八王朝赫阿那顿法老的王妃。图坦卡蒙的母亲。她聪明贤慧，通晓天文地理，辅助丈夫统治古埃及，被人民尊称为“尼罗河的统治者”、“真主之女”、“地中海女王”。"});
  外域美人.push({id:123,_code:5123,名称:"哈谢普苏",家族:undefined,性格:[8,7],党:0,跳:123,统帅:23,武力:23,智力:44,政治:33,魅力:95,清廉:23,野心:97,性别:1,文化:12,介绍:"埃及历史上一位女王，为了在男人世界里受到尊重，她要求工匠为自己的雕像加上胡子，而且不准有胸部，还盖了自己的神庙，立起了代表战功的方尖碑，而且还是历来最高大的方尖碑。"});
  外域美人.push({id:124,_code:5124,名称:"伊西斯",家族:undefined,性格:[2,17],党:0,跳:124,统帅:35,武力:24,智力:82,政治:71,魅力:90,清廉:81,野心:41,性别:1,文化:12,介绍:"古埃及神话中的生命、魔法、婚姻和生育女神，赫里奥波里斯九柱神之一。"});
