  外域美人.push({id:127,_code:5127,名称:"月野兔",家族:undefined,性格:[11,12],党:0,跳:127,统帅:86,武力:55,智力:92,政治:88,魅力:89,清廉:72,野心:90,性别:1,文化:13,介绍:"前世是月亮上的不老王国银千年王国的公主倩妮迪，转生后成为十番中学的初二学生以及水手月亮，未来是水晶东京的新·倩妮迪女王。"});
  外域美人.push({id:128,_code:5128,名称:"伊丽莎白",家族:"彼得罗芙娜",性格:[8,7],党:0,跳:128,统帅:55,武力:55,智力:76,政治:78,魅力:90,清廉:72,野心:77,性别:1,文化:13,介绍:"伊丽莎白·彼得罗芙娜，俄罗斯帝国皇帝彼得一世和女皇叶卡捷琳娜一世之女，1741年发动宫廷政变，推翻其甥孙伊凡六世，自立为女皇，以彼得大帝合法继承人自居。"});
  外域美人.push({id:129,_code:5129,名称:"阿纳斯塔西娅",家族:"尼古拉耶芙娜",性格:[18,27],党:0,跳:129,统帅:17,武力:16,智力:53,政治:59,魅力:90,清廉:73,野心:22,性别:1,文化:13,介绍:"阿纳斯塔西娅·尼古拉耶芙娜，俄罗斯帝国末代皇帝尼古拉二世与妻子亚历山德拉·费奥多萝芙娜最小的女儿。"});
  外域美人.push({id:130,_code:5130,名称:"柳叶",家族:"柳",性格:[0,17],党:0,跳:130,统帅:88,武力:23,智力:85,政治:78,魅力:88,清廉:85,野心:23,性别:1,文化:14,介绍:"母系氏族时期，柬埔寨扶南社会的女王。也是柬埔寨历史上第一位国王。"});
  外域美人.push({id:131,_code:5131,名称:"安眉",家族:"安",性格:[19,27],党:0,跳:131,统帅:34,武力:42,智力:82,政治:73,魅力:91,清廉:75,野心:34,性别:1,文化:14,介绍:"柬埔寨女王。安赞二世死后无子，越南阮朝皇帝明命帝派大将张明讲扶持安眉公主为柬埔寨女王。安眉女王即位后被幽禁在宫中，越南人不准她参与政事，成为事实上的傀儡女王。"});
  外域美人.push({id:132,_code:5132,名称:"尔朱英娥",家族:"尔朱",性格:[9,7],党:0,跳:132,统帅:12,武力:87,智力:67,政治:34,魅力:87,清廉:88,野心:8,性别:1,文化:15,介绍:"尔朱英娥，北秀容人，北魏孝庄帝元子攸的皇后，尔朱荣的长女，美姿色，爽直有武艺。"});
  外域美人.push({id:133,_code:5133,名称:"独孤般若",家族:"独孤",性格:[40,17],党:0,跳:133,统帅:29,武力:23,智力:90,政治:69,魅力:90,清廉:76,野心:29,性别:1,文化:15,介绍:"明敬皇后独孤氏，鲜卑族，北周明帝皇后，大司马独孤信长女，隋文献皇后独孤伽罗的姐姐。适婚的年纪，嫁给太师宇文泰庶长子宇文毓。随着权臣宇文护废黜孝闵帝宇文觉、拥戴宇文毓即位成为天王，受封为王后。"});
  外域美人.push({id:134,_code:5134,名称:"独孤曼陀",家族:"独孤",性格:[13,29],党:0,跳:134,统帅:30,武力:24,智力:90,政治:70,魅力:91,清廉:77,野心:30,性别:1,文化:15,介绍:"元贞皇后独孤氏，鲜卑族，西魏、北周时期重要将领、八柱国之一独孤信第四女，北周明敬皇后独孤氏之妹，隋朝文献皇后独孤伽罗之姊。嫁唐国公李昞，育有梁王李澄、蜀王李湛、汉王李洪、唐高祖李渊和同安长公主。"});
  外域美人.push({id:135,_code:5135,名称:"独孤伽罗",家族:"独孤",性格:[0,8],党:0,跳:135,统帅:31,武力:25,智力:91,政治:71,魅力:92,清廉:78,野心:31,性别:1,文化:15,介绍:"文献皇后独孤氏，鲜卑族，北周卫国公、关陇集团重要成员独孤信嫡女，母清河崔氏。独孤伽罗十四岁嫁给大将军杨忠的嫡长子杨坚。不久，父亲在政争中失败被杀，家道中落。她对外低调谦恭，对内夫妻恩爱，育有十个儿女，并辅助杨坚建功立业。隋朝开国后，册封皇后。她“雅好读书、识达今古”，参预朝政，对于“开皇之治”功不可没，与杨坚并称“二圣”。"});
  外域美人.push({id:136,_code:5136,名称:"乙弗",家族:undefined,性格:[5,17],党:0,跳:136,统帅:24,武力:18,智力:73,政治:35,魅力:86,清廉:74,野心:12,性别:1,文化:15,介绍:"吐谷浑鲜卑族人，北朝西魏文帝元宝炬的元皇后，生废帝元钦。她是青海王后裔，自祖父莫瓌归顺北魏，举家迁居中土。其节俭朴素，仁慈宽宏，宝炬为南阳王时媒娶正妃，情笃敦睦，有子女十二人。"});
  外域美人.push({id:137,_code:5137,名称:"普思卡",家族:"耶律",性格:[1,21],党:0,跳:137,统帅:12,武力:12,智力:56,政治:56,魅力:85,清廉:68,野心:56,性别:1,文化:16,介绍:"西辽古儿汗王妃。"});
  外域美人.push({id:138,_code:5138,名称:"胡仙真",家族:"胡",性格:[36,37],党:0,跳:138,统帅:88,武力:88,智力:88,政治:88,魅力:83,清廉:78,野心:60,性别:1,文化:16,介绍:"宣武灵皇后。曾临朝听政13年，武艺高强，好射箭，爱登山。临朝听政初期，颇有政绩。后大肆崇佛、荒淫无节制等，导致了河阴之变，被沉入黄河溺死。"});
