  外域美人.push({id:140,_code:5140,名称:"玳瓒",家族:undefined,性格:[9,24],党:0,跳:140,统帅:68,武力:87,智力:82,政治:75,魅力:91,清廉:73,野心:74,性别:1,文化:16,介绍:"西凉公主，一个美丽、聪慧的巾帼英雄。"});
  外域美人.push({id:141,_code:5141,名称:"小枫",家族:undefined,性格:[3,12],党:0,跳:141,统帅:34,武力:42,智力:82,政治:73,魅力:91,清廉:75,野心:34,性别:1,文化:16,介绍:"西洲九公主，原名玛尔其玛，天真活泼，率真洒脱。"});
  外域美人.push({id:142,_code:5142,名称:"卫慕双羊",家族:"卫慕",性格:[2,19],党:0,跳:142,统帅:54,武力:35,智力:57,政治:57,魅力:90,清廉:71,野心:38,性别:1,文化:16,介绍:"党项族人，西夏太宗李德明的皇后，景宗李元昊的母亲。她出身党项大族，嫁定难军节度使李德明为妻，恩爱相谐，夫唱妇随。"});
  外域美人.push({id:143,_code:5143,名称:"阮友兰",家族:"阮",性格:[18,6],党:0,跳:143,统帅:24,武力:31,智力:44,政治:55,魅力:94,清廉:66,野心:12,性别:1,文化:17,介绍:"南芳皇后，安南国王、越南皇帝保大 (阮福晪)的正妻，第一位君主在位时就受封的王后。阮朝的惯例是，在位君主的妻子只能封为妃嫔，由最高级的一阶妃至第九级的才人，只有在丈夫去世后，在位君主的母亲或祖母才能追封为王后。但是保大在1934年迎娶南芳时，就破例封她为王后。1945年当保大改称越南皇帝时，南芳也改称为皇后。"});
  外域美人.push({id:144,_code:5144,名称:"杨云娥",家族:"杨",性格:[37,35],党:0,跳:144,统帅:25,武力:32,智力:45,政治:56,魅力:95,清廉:27,野心:13,性别:1,文化:17,介绍:"杨云娥，越南丁朝唯一一位皇太后，也是前黎朝的第一位皇后。杨云娥最早是丁朝皇帝丁部领的五位皇后之一，979年丁部领被暗杀后，丁璇即位，杨云娥成为皇太后。在此期间，杨云娥与十道将军黎桓私通，并一起代理年仅6岁的皇帝执掌朝政。后来在宋朝南下进攻时，杨云娥指使范巨俩拥立黎桓为皇帝，建立前黎朝；随后杨云娥被黎桓立为皇后，成为越南历史上第一位嫁给两个皇帝的人。"});
  外域美人.push({id:145,_code:5145,名称:"乌云珠",家族:"董鄂",性格:[4,26],党:0,跳:145,统帅:34,武力:21,智力:78,政治:56,魅力:95,清廉:75,野心:24,性别:1,文化:18,介绍:"董鄂氏，满洲正白旗人，内大臣鄂硕之女，大将军费扬古之姐。清世祖爱新觉罗·福临宠妃。年十八入侍，上眷之特厚，宠冠后宫。顺治十三年八月，立为贤妃，十二月，进皇贵妃，十四年十月生四阿哥，顺治欣喜称颁诏“此乃朕第一子”，次年正月夭折，追封荣亲王，丧葬逾制。"});
  外域美人.push({id:146,_code:5146,名称:"蓝齐儿",家族:"爱新觉罗",性格:[14,18],党:0,跳:146,统帅:56,武力:13,智力:78,政治:78,魅力:90,清廉:78,野心:70,性别:1,文化:18,介绍:"蓝齐格格是皇家格格，她与所有少女一样有甜蜜青涩的初恋，但就因她是一个满族皇家格格，才失去选择的自由，她不得不为“家”为国而献身和亲远嫁草原。"});
  外域美人.push({id:147,_code:5147,名称:"孟古哲哲",家族:"叶赫那拉",性格:[5,5],党:0,跳:147,统帅:40,武力:17,智力:89,政治:76,魅力:94,清廉:86,野心:35,性别:1,文化:8,介绍:"孝慈高皇后，叶赫那拉氏，名孟古哲哲，叶赫部贝勒杨吉砮（杨吉努）女儿，清太祖努尔哈赤侧妃，清太宗皇太极生母，清朝第一位被追封的皇后。1629年，孟古哲哲与努尔哈赤合葬在福陵。崇德元年，皇太极为其上谥号为“孝慈昭宪纯德真顺承天育圣武皇后”，经康熙、雍正、乾隆累加谥、改谥，最终谥号为“孝慈昭宪敬顺仁徽懿德庆显承天辅圣高皇后”。"});
  外域美人.push({id:148,_code:5148,名称:"哈哈纳扎青",家族:"佟佳",性格:[36,15],党:0,跳:148,统帅:14,武力:11,智力:80,政治:45,魅力:90,清廉:27,野心:4,性别:1,文化:18,介绍:"建州女真佟佳氏，清太祖爱新觉罗·努尔哈赤的大妃。她辅佐太祖开国立业，生长子褚英、次子代善及女儿东果，病逝于明万历二十年，享年三十三。其子褚英以嫡长之身，初被视为努尔哈赤的继承人，曾获赐号“阿尔哈图”、高赞为英雄，后多行悖妄，在万历四十三年被努尔哈赤处死。太祖建后金，太宗立清朝。皇太极为自己的生母孟古追谥后号，却并未追尊哈哈纳扎青。她终以“太祖元妃”之名垂史册。"});
  外域美人.push({id:147,_code:5149,名称:"衮代",家族:"富察",性格:[1,14],党:0,跳:149,统帅:40,武力:17,智力:89,政治:76,魅力:94,清廉:86,野心:35,性别:1,文化:8,介绍:"建州女真富察氏，清太祖爱新觉罗·努尔哈赤的继妃。明万历二十年，元妃佟佳·哈哈纳扎青病逝，努尔哈赤续娶富察部贝勒莽色督珠乎之女衮代为大福晋，生二子一女。"});
