      _all_mingji.push({id:2,_code:14002,名称:"关盼盼",家族:"关",标:0,头像:15,统帅:25,武力:28,智力:70,政治:70,魅力:94,清廉:60,野心:40,性别:1,文化:8,介绍:"唐代名伎，徐州守帅张愔之妾，曾被白居易盛赞：“醉娇胜不得，风袅牡丹花”夫死守节于燕子楼十余年，白居易作诗批评她只能守节不能殉节，于是绝食而死。"});
      _all_mingji.push({id:3,_code:14003,名称:"陈圆圆",家族:"陈",标:0,头像:16,统帅:26,武力:29,智力:60,政治:60,魅力:98,清廉:45,野心:20,性别:1,文化:8,介绍:"原姓邢，名沅，字圆圆，又字畹芳，幼从养母陈氏，故改姓陈，色艺双绝，名动江左，吴中名优，“秦淮八艳”之一，后嫁吴三桂为妾。"});
      _all_mingji.push({id:4,_code:14004,名称:"杜十娘",家族:"杜",标:0,头像:30,统帅:15,武力:18,智力:77,政治:77,魅力:90,清廉:45,野心:60,性别:1,文化:8,介绍:"曾为青楼女子，深受压迫却坚贞不屈，为摆脱逆境而顽强挣扎，遭李甲后，万念俱灰之下，把多年珍藏的百宝箱中的一件件宝物抛向江中，最后纵身跃入滚滚波涛之中。"});
      _all_mingji.push({id:5,_code:14005,名称:"马湘兰",家族:"马",标:0,头像:36,统帅:21,武力:15,智力:70,政治:70,魅力:92,清廉:45,野心:60,性别:1,文化:8,介绍:"秦淮八艳之一，生于金陵，自幼不幸沦落风尘，但她为人旷达，性望轻侠，常挥金以济少年，是秦淮八艳之一，70大寿盛宴归后一病不起，最后强撑沐以礼佛端坐而逝。"});
      _all_mingji.push({id:6,_code:14006,名称:"裴兴奴",家族:"裴",标:0,头像:84,统帅:26,武力:11,智力:62,政治:62,魅力:91,清廉:45,野心:60,性别:1,文化:8,介绍:"长安城著名的琵琶女，儿时从师学艺，弹得一手好琵琶，是长安城里第一个有名的歌女，不少富贵子弟都曾被她的美貌和歌技所倾倒。"});
      _all_mingji.push({id:7,_code:14007,名称:"霍小玉",家族:"霍",标:0,头像:89,统帅:11,武力:16,智力:67,政治:67,魅力:90,清廉:78,野心:40,性别:1,文化:8,介绍:"唐代传奇小说《霍小玉传》女主角，长得明丽可人，通诗文、善歌舞，为了维持生活干了歌舞妓这个行当，卖艺不卖身，才貌俱佳，颇有声誉。"});
      _all_mingji.push({id:8,_code:14008,名称:"寇白门",家族:"寇",标:0,头像:105,统帅:21,武力:25,智力:83,政治:83,魅力:92,清廉:67,野心:40,性别:1,文化:8,介绍:"寇白门，名湄，字白门，1624年出生于金陵，与马湘兰、卞玉京、李香君、董小宛、顾横波、柳如是、陈圆圆同称“秦淮八艳”。人称“女侠”十八岁时嫁给明朝声势显赫的功臣保国公朱国弼。"});
      _all_mingji.push({id:9,_code:14009,名称:"赛金花",家族:"赛",标:0,头像:206,统帅:16,武力:14,智力:77,政治:77,魅力:97,清廉:39,野心:60,性别:1,文化:8,介绍:"清末民初名妓，其初名为赵彩云，又名傅彩云，安徽黟县人，幼年被卖到苏州所谓的“花船”上为妓。"});
      _all_mingji.push({id:10,_code:14010,名称:"卞玉京",家族:"卞",标:0,头像:164,统帅:11,武力:17,智力:90,政治:90,魅力:90,清廉:67,野心:60,性别:1,文化:8,介绍:"卞玉京（约1623——1665年），又名卞赛，字云装，后自号“玉京道人”，习称玉京，应天府上元县（今江苏省南京市）人。“秦淮八艳”之一。 卞赛诗琴书画无所不能，尤擅小楷，还通文史。她的绘画艺技娴熟，落笔如行云，“一落笔尽十余纸”喜画风枝袅娜，尤善画兰。作有《题扇送志衍入蜀》。"});
      _all_mingji.push({id:11,_code:14011,名称:"顾横波",家族:"顾",标:0,头像:163,统帅:12,武力:16,智力:91,政治:91,魅力:90,清廉:67,野心:60,性别:1,文化:8,介绍:"顾横波原名顾媚，又名眉，字眉生，别字后生，号横波，应天府上元县（今江苏省南京市）人。“秦淮八艳”之一。工诗善画，善音律，尤擅画兰，能出己意，所画丛兰笔墨飘洒秀逸。作有《海月楼夜坐》、《花深深·闺坐》、《虞美人·答远山夫人寄梦》、《千秋岁·送远山夫人南归》等诗词，收入所著《柳花阁集》。受诰封为“一品夫人”。"});
      _all_mingji.push({id:12,_code:14012,名称:"柳如是",家族:"柳",标:0,头像:924,统帅:11,武力:11,智力:95,政治:56,魅力:96,清廉:67,野心:40,性别:1,文化:8,介绍:"柳如是，是明末清初秦淮河畔如云佳丽中的一朵奇葩。天生丽质，书画双绝，然而她气格孤傲，心怀天下，多情重义，非一般青楼女子可比。"});
      _all_mingji.push({id:13,_code:14013,名称:"李师师",家族:"李",标:0,头像:990,统帅:10,武力:27,智力:95,政治:62,魅力:93,清廉:78,野心:40,性别:1,文化:8,介绍:"芳迹依稀记汴梁，当年韵事久传扬；紫宫有道通香窟，红粉多情恋上皇。孰料胡儿驱铁马，竟教佳丽死红羊；靖康奇耻谁为雪，黄河滔滔万古殇。"});
      _all_mingji.push({id:14,_code:14014,名称:"李香君",家族:"李",标:0,头像:4838,统帅:11,武力:11,智力:90,政治:75,魅力:95,清廉:65,野心:60,性别:1,文化:8,介绍:"秦淮河畔媚香楼里的名妓，又是一个诗书琴画歌舞样样精通的角儿。"});
      _all_mingji.push({id:15,_code:14015,名称:"李娇儿",家族:"李",标:0,头像:116,统帅:14,武力:16,智力:36,政治:36,魅力:80,清廉:39,野心:60,性别:1,文化:8,介绍:"本是勾栏里唱曲儿的妓女，西门庆一时兴起娶回家中做小老婆，额尖鼻小，房事技巧平平。"});
      _all_mingji.push({id:16,_code:14016,名称:"赵丽娘",家族:"赵",标:0,头像:51,统帅:12,武力:12,智力:70,政治:70,魅力:90,清廉:39,野心:80,性别:1,文化:8,介绍:"赵丽妃，唐玄宗后宫嫔妃之一，原本是潞州的倡伎，出身卑微，后遇身为临淄王的唐玄宗，被纳为侧室，后成为三妃之一的“丽妃”。"});
      _all_mingji.push({id:17,_code:14017,名称:"杨九红",家族:"杨",标:0,头像:189,统帅:14,武力:15,智力:77,政治:37,魅力:90,清廉:39,野心:70,性别:1,文化:8,介绍:"《大宅门》中人物，自幼被长兄卖入青楼，后被白景琦收为二姨太，在封建礼教的摧残下，心思日渐恶毒，是一个敢于和封建礼教抗争的可敬，可爱，可怜，可悲的女性。"});
      _all_mingji.push({id:18,_code:14018,名称:"谭文婉",家族:"谭",标:0,头像:9,统帅:19,武力:11,智力:80,政治:80,魅力:94,清廉:78,野心:40,性别:1,文化:8,介绍:"原名意歌，小字英奴，晚唐名士谭从道的女儿，面貌姣美，文采名播长沙，魏公赐名“文婉”，并字“才姬”；刘相戏称她为“千古诗妖”。"});
      _all_mingji.push({id:19,_code:14019,名称:"章台柳",家族:"章",标:0,头像:93,统帅:15,武力:10,智力:71,政治:71,魅力:91,清廉:65,野心:60,性别:1,文化:8,介绍:"唐韩翃有姬柳氏﹐以艳丽称。韩获选上第归家省亲;柳留居长安﹐安史乱起﹐出家为尼。后韩为平卢节度使侯希逸书记﹐使人寄柳诗曰:“章台柳﹐章台柳﹐往日依依今在否？纵使长条似旧垂﹐也应攀折他人手。”柳为蕃将沙咤利所劫﹐侯希逸部将许俊以计夺还归韩。见唐许尧佐《柳氏传》。后以“章台柳”形容窈窕美丽的女子。"});
      _all_mingji.push({id:20,_code:14020,名称:"王朝云",家族:"王",标:0,头像:53,统帅:14,武力:14,智力:70,政治:70,魅力:89,清廉:78,野心:40,性别:1,文化:8,介绍:"字子霞，大文豪苏东坡侍妾，文学家苏轼之妾，原本不识字，后来学会写字，还跟从泗上比丘尼义冲学佛，1095年亡故并葬于惠州西湖。"});
      _all_mingji.push({id:21,_code:14021,名称:"蔡琴操",家族:"蔡",标:0,头像:1000,统帅:2,武力:1,智力:80,政治:60,魅力:90,清廉:50,野心:55,性别:1,文化:8,介绍:"琴操（1073年-1098年），姓蔡，名云英，艺名琴操，北宋钱塘人艺名人。原系官宦大家闺秀，从小聪明伶俐，琴棋书画、歌舞诗词都有一定的造诣。13岁那年父亲受宫廷牵诛，家遭藉没而为杭州歌唱院艺人。不到三年，因其学习刻苦，加上天资陪颖，才华出众，16岁那年改了北宋诗人秦观《满庭芳》词而在杭红极一时。后受到大诗人苏东坡的赏识，引为红颜知己。据闻后因与苏对答后，遁入空门。"});
      _all_mingji.push({id:22,_code:14022,名称:"杜秋娘",家族:"杜",标:0,头像:1001,统帅:2,武力:2,智力:80,政治:60,魅力:90,清廉:50,野心:55,性别:1,文化:8,介绍:"唐代的南京名妓，曾入宫，后被遣回金陵。"});
      _all_mingji.push({id:23,_code:14023,名称:"敫桂英",家族:"敫",标:0,头像:1002,统帅:2,武力:2,智力:80,政治:60,魅力:90,清廉:50,野心:55,性别:1,文化:8,介绍:"唐朝蓬莱名妓，秀外惠中，颇有才能。 "});
      _all_mingji.push({id:24,_code:14024,名称:"灼灼",家族:undefined,标:0,头像:1003,统帅:2,武力:2,智力:80,政治:60,魅力:90,清廉:50,野心:55,性别:1,文化:8,介绍:"晚唐的歌舞名妓，蜀之丽人也，年老贫落于成都酒市之中。诗人韦庄有诗伤咏。 "});
      _all_mingji.push({id:25,_code:14025,名称:"李娃",家族:"李",标:0,头像:1004,统帅:2,武力:2,智力:80,政治:60,魅力:90,清廉:50,野心:55,性别:1,文化:8,介绍:"李娃是《李娃传》虚构的一个娼妓与所爱士人荥阳公子历经磨难，终于圆满结合。原名李亚仙，唐代天宝年间京都长安的一位风尘女子，以重情仗义而被人们誉为“义妓”。"});
      _all_mingji.push({id:26,_code:14026,名称:"李念奴",家族:"李",标:0,头像:1005,统帅:2,武力:2,智力:80,政治:60,魅力:90,清廉:50,野心:55,性别:1,文化:8,介绍:"北宋时杭州名妓，苏东坡在任时，劝他以脱藉而救出所有杭州妓女。"});
      _all_mingji.push({id:27,_code:14027,名称:"刘婆惜",家族:"刘",标:0,头像:1006,统帅:2,武力:2,智力:80,政治:60,魅力:90,清廉:50,野心:70,性别:1,文化:8,介绍:"刘婆惜，生活于元末明初时代，江西抚州临川人。散曲家，歌舞名伎。乐人李四之妻。颇通文墨，滑稽歌舞，迥出其流。先与抚州常推官之子三舍交好，为其夫间阻，遂私奔。事觉，被杖决。"});
      _all_mingji.push({id:28,_code:14028,名称:"沈九娘",家族:"沈",标:0,头像:1007,统帅:2,武力:2,智力:80,政治:60,魅力:90,清廉:50,野心:55,性别:1,文化:8,介绍:"沈九娘（1475～1512），明朝弘治年间苏州名妓，长相端庄文雅，琴棋书画样样精通，才艺过人。后为唐伯虎之妻，是唐伯虎的第三位妻子和红颜知己。"});
      _all_mingji.push({id:29,_code:14029,名称:"卞敏",家族:"卞",标:0,头像:1008,统帅:40,武力:40,智力:80,政治:60,魅力:90,清廉:50,野心:55,性别:1,文化:8,介绍:"明末秦淮爱国名妓，卞玉京的妹妹，抗清时血洒沙场。"});
