var _all_doctor = [];
  _all_doctor.push({id:0,_code:12000,名称:"王耀辰",治疗:9,预防:9,保胎:9,研制:9,宫:undefined,任务中:0,开启:1,头像:0,介绍:"御用太医，医术了得，但性格乖张，一般人请不动。外表看起来是翩翩少年，实际年龄却无人知晓，也许是保养得太好的缘故。"});
  _all_doctor.push({id:1,_code:12001,名称:"章弥",治疗:5,预防:6,保胎:2,研制:8,宫:undefined,任务中:0,开启:1,头像:1,介绍:"先帝在位时便入宫做了院判，是太医院的老人了。行医多年，做事稳妥。"});
  _all_doctor.push({id:2,_code:12002,名称:"扁鹊",治疗:9,预防:6,保胎:5,研制:8,宫:undefined,任务中:0,开启:0,头像:2,介绍:"战国时医学家，其真实姓名是秦越人，又号卢医。据人考证，约生于周威烈王十九年，卒于赧王五年。善用“针石”、“服汤”、“熨”等治病，所著《扁鹊内经》、《外经》早佚。他为什么被称为“扁鹊”呢？这是他的绰号。扁鹊善于运用四诊，尤其是脉诊和望诊来诊断疾病。《史记·扁鹊仓公列传》中记述了与他有关的两个医案：一个是用脉诊的方法诊断赵子简的病，一个是用望诊的方法诊断齐桓侯的病。因此被称为“脉学之宗”。"});
  _all_doctor.push({id:3,_code:12003,名称:"李时珍",治疗:8,预防:6,保胎:4,研制:8,宫:undefined,任务中:0,开启:0,头像:3,介绍:"明朝医学家。其父李言闻世当地名医。李时珍继承家学，尤其重视本草，并富有实践精神，肯于向劳动人民群众学习。李时珍曾参考历代有关医药及其学术书籍八百余种，结合自身经验和调查研究，穷搜博采，历三十年，三次易稿而成《本草纲目》，为我国医学史上一大巨著。是我国明以前药物学的总结性巨著。在国内外均有很高的评价，已有几种文字的译本或节译本。另著有《濒湖脉学》、《奇经八脉考》等书。"});
  _all_doctor.push({id:4,_code:12004,名称:"孙思邈",治疗:8,预防:6,保胎:5,研制:8,宫:undefined,任务中:0,开启:0,头像:4,介绍:"出生于隋开皇元年，卒于唐永淳元年。活了102岁（也有说他活了141岁），他是我国乃至世界历史上著名的医学家和药物学家。历史上，被人们尊为“药王”。一生致力于医药研究工作，著有《千金方》，创立脏病、腑病分类系统，在医学上有较大贡献。"});
  _all_doctor.push({id:5,_code:12005,名称:"张仲景",治疗:8,预防:6,保胎:5,研制:8,宫:undefined,任务中:0,开启:0,头像:5,介绍:"东汉医学家，辞官业医，博采众方，著《伤寒杂病论》。《伤寒杂病论》确立了祖国医学“辨证论治”的规律，它奠定了中医治疗学的基础，是我国最早的一部理法方药具备的经典著作，开创了祖国医学辨证论治的先河；同时在制剂学方面也有独到之处，对后世也有深远的影响。因此，历代医家无不尊张仲景为“医圣”，故有“医圣者，即医中之尧舜也，荣膺此誉者，唯仲景先师。”"});
  _all_doctor.push({id:6,_code:12006,名称:"皇甫谧",治疗:8,预防:6,保胎:4,研制:8,宫:undefined,任务中:0,开启:0,头像:6,介绍:"魏晋医学家。西晋安定朝那（今甘肃灵台人县朝那镇）人。著名医家，其著作《针灸甲乙经》是我国第一部针灸学的专著，总结了晋以前的针炙学成就，在针灸学史上，占有很高的学术地位。 另著有《帝王世纪》等。"});
  _all_doctor.push({id:7,_code:12007,名称:"葛洪",治疗:8,预防:6,保胎:4,研制:8,宫:undefined,任务中:0,开启:0,头像:7,介绍:"西晋思想家、医药学家。他还是古代一位鼎鼎有名科学家，在医学和制药化学上有许多重要的发现和创造，在文学上也有许多卓越的见解。他的著作，约有五百三十卷。不过，大多已经散佚，流传至今的，主要有《抱朴子》和《肘后救卒方》葛洪的医学著作，据史籍记载，尚有《金匮药方》一百卷，《神仙服食方》十卷，《服食方》四卷，《玉函煎方》五卷。"});
  _all_doctor.push({id:8,_code:12008,名称:"钱乙",治疗:8,预防:6,保胎:4,研制:8,宫:undefined,任务中:0,开启:0,头像:8,介绍:"北宋医学家，始以儿科著名，后擢太医丞，为公卿宗戚看病，名声大著。其所著《小儿药证直诀》，是我国现存的第一部儿科专著。它第一次系统地总结了对小儿的辨证施治法，使儿科自此发展成为独立的一门学科。后人视之为儿科的经典著作，把钱乙尊称为“儿科之圣”，“幼科之鼻祖”。 另有《伤寒指徵》、《婴孩论》等。"});
  _all_doctor.push({id:9,_code:12009,名称:"温实初",治疗:6,预防:6,保胎:3,研制:8,宫:undefined,任务中:0,开启:1,头像:9,介绍:"小说《后宫·甄嬛传》中的人物。宫中太医，从小一直爱慕甄嬛，但求亲无果。自甄嬛入宫后，一直帮助甄嬛，后和眉庄相好，生下一女静和（小说中为四皇子予润）。被祺嫔诬陷与甄嬛有染，为保甄嬛和眉庄清白而自宫。沈眉庄死后，自请为眉庄守灵三年。"});
  _all_doctor.push({id:10,_code:12010,名称:"鲍姑",治疗:7,预防:6,保胎:6,研制:8,宫:undefined,任务中:0,开启:0,头像:10,介绍:"鲍姑，名潜光（约公元309－363年）是中国古代4位（晋代鲍姑、西汉义妁、宋代张小娘子、明代谈允贤）女名医之一。她是晋代著名炼丹术家、精通灸法，是我国医学史上第一位女灸学家。"});
  _all_doctor.push({id:11,_code:12011,名称:"张小娘子",治疗:7,预防:6,保胎:6,研制:8,宫:undefined,任务中:0,开启:0,头像:11,介绍:"在张小娘子年轻的时候，有一天，一位云游郎中路过门前，向她讨杯水喝。张小娘子见是一位银髯老人，气度不凡，便将他请进屋里，让座沏茶，还热情地招待饭菜。那位老郎中见她聪明贤慧、手脚勤快，便将开刀和制膏等外科秘方传授给她，还赠她一部秘而不传的《痈疽异方》。后来，经过不断实践，张小娘子终于成了一位精通外科的女医生。凡是疮疡痈肿的病人前来求医，经她诊治，无一不见奇效。—时名声大噪，病人应接不暇。她又把外科技术传给丈夫，于是，夫妇俩都成了当地名医。"});
  _all_doctor.push({id:12,_code:12012,名称:"谈允贤",治疗:7,预防:6,保胎:6,研制:8,宫:undefined,任务中:0,开启:0,头像:12,介绍:"谈允贤 (1461年－1556年) ，中国古代4位（晋代鲍姑、西汉义妁、宋代张小娘子、明代谈允贤）女名医之一。明代南直隶无锡（今江苏无锡）人。出生于医学世家，其祖父曾任南京刑部郎中，是当地的名医，其祖母对医药也十分精通。秉承家学，从十来岁时即“昼夜不辍”地攻读各种医学典籍。著作有《女医杂言》一书传于世。"});
  _all_doctor.push({id:13,_code:12013,名称:"义妁",治疗:7,预防:6,保胎:6,研制:8,宫:undefined,任务中:0,开启:0,头像:13,介绍:"义妁，汉武帝时河东人，今永济人。是我国历史上第一个有记载的女医生，被誉为巾帼医家第一人。因医术高超被召入宫，专为皇太后治病。是中国古代4位（晋代鲍姑、西汉义妁、宋代张小娘子、明代谈允贤）女名医之首。"});
