所有隐士 = [];
     所有隐士.push({id:0,_code:11000,名称:"介子推",家族:"介",地区:6,头像:1012,统帅:45,武力:54,智力:98,政治:95,魅力:88,清廉:96,野心:10,性别:0,文化:8,介绍:"介子推，又名介之推，后人尊为介子，春秋时期晋国人，生于闻喜户头村，长在夏县裴介村，因“割股奉君”，隐居“不言禄”之壮举，深得世人怀念。死后葬于介休绵山。晋文公重耳深为愧疚，遂改绵山为介山，并立庙祭祀，由此产生了（清明节前一天）“寒食节”，历代诗家文人留有大量吟咏缅怀诗篇。"});
     所有隐士.push({id:1,_code:11001,名称:"许由",家族:"许",地区:9,头像:1035,统帅:80,武力:80,智力:95,政治:85,魅力:66,清廉:90,野心:10,性别:0,文化:8,介绍:"许由是尧舜时代的贤人。帝尧在位的时候，据说曾想把君位传给他，遭到了他的严词拒绝。他逃到了箕山隐居起来，帝尧想请他出任九州长官，他跑到颍水边洗耳，表示不愿意听这种话。以自己淡泊名利的崇高节操赢得了后世的尊敬，从而被奉为隐士的鼻祖。巢父也是同时期的隐士。是阳城的大贤。山居不营世利，在树上筑巢而居，时人号曰巢父。传说尧帝以天下让给巢父，巢父不肯受。"});
     所有隐士.push({id:2,_code:11002,名称:"伯夷",家族:"墨胎",地区:6,头像:1058,统帅:92,武力:77,智力:94,政治:92,魅力:65,清廉:92,野心:15,性别:0,文化:8,介绍:"伯夷为商末孤竹君之长子，姓墨胎氏。初，孤竹君欲以次子叔齐为继承人，及父卒，叔齐让位于伯夷。伯夷以为逆父命，遂逃之，而叔齐亦不肯立，亦逃之。后来武王克商后，天下宗周，而伯夷、叔齐耻食周粟，逃隐于首阳山，采集野菜而食之，饿死于首阳山。"});
     所有隐士.push({id:3,_code:11003,名称:"鬼谷子",家族:"王",地区:6,头像:1081,统帅:97,武力:48,智力:97,政治:88,魅力:98,清廉:88,野心:12,性别:0,文化:8,介绍:"鬼谷子，姓王名诩，卫国人。常入云梦山采药修道。因隐居清溪之鬼谷，故自称鬼谷子。鬼谷子为纵横家之鼻祖，苏秦与张仪为其最杰出的两个弟子。另有孙膑与庞涓亦为其弟子之说。鬼谷子的主要著作有《鬼谷子》及《本经阴符》。"});
     所有隐士.push({id:4,_code:11004,名称:"颜回",家族:"颜",地区:12,头像:1104,统帅:56,武力:34,智力:98,政治:95,魅力:80,清廉:99,野心:30,性别:0,文化:8,介绍:"春秋末鲁国人。字子渊，亦颜渊， 孔子最得意弟子。《雍也》说他“一箪食，一瓢饮，在陋巷，人不堪其忧，回也不改其乐”。为人谦逊好学，“不迁怒，不贰过”。他异常尊重老师，对孔子无事不从无言不悦。以德行著称，孔子称赞他“贤哉回也”，“回也，其心三月不违反、仁”。不幸早死。自汉代起，颜回被列为七十二贤之首，有时祭孔时独以颜回配享。此后历代统治者不断追加谥号。"});
     所有隐士.push({id:5,_code:11005,名称:"周术",家族:"周",地区:12,头像:1127,统帅:56,武力:64,智力:96,政治:94,魅力:80,清廉:99,野心:30,性别:0,文化:8,介绍:"甪里先生，名周术，是汉代的一位著名隐士，“商山四皓”之一，他曾力谏汉高祖刘邦废太子之事。甪里与东园公唐秉、绮里季吴实、夏黄公崔广，这四位饱学之士先后为避秦乱而结茅山林。四人德高望重，汉高祖刘邦多次请他们出山为官，不至。后刘邦宠幸戚夫人，打算另立太子，吕后急找张良商量，张良便请出商山四皓出面。后来商山四皓被太子刘盈请去，成为太子上宾。刘邦见太子有四位大贤辅佐，消除了改立赵王如意为太子的念头。"});
     所有隐士.push({id:6,_code:11006,名称:"东园公",家族:"唐",地区:12,头像:1150,统帅:45,武力:24,智力:97,政治:93,魅力:80,清廉:99,野心:30,性别:0,文化:8,介绍:"东园公,姓唐（一说姓庾、园），名秉，字宣明。是秦末汉初的一位著名隐士，是“商山四皓”之一，居园中，因以东园公为号。他曾力谏汉高祖刘邦废太子之事。东园公与绮里季、夏黄公、甪里先生这四位饱学之士先后为避秦乱而结茅山林。四人德高望重，汉代立国以后，刘邦一直想要网罗德高望重的四人，却被拒绝。他们过著清贫而安乐的生活，写《紫芝歌》以明志。"});
     所有隐士.push({id:7,_code:11007,名称:"绮里季",家族:"吴",地区:12,头像:1173,统帅:26,武力:54,智力:98,政治:93,魅力:80,清廉:99,野心:30,性别:0,文化:8,介绍:"绮里季，古人名，姓吴名实。汉初隐士，“商山四皓”之一。典出《史记》卷五十五〈留侯世家〉。秦末东园公、绮里季、夏黄公、甪里先生 ，避秦乱，隐商山 ，年皆八十有馀，须眉皓白，时称“商山四皓”。后高祖欲废太子， 吕后用留侯计，迎四皓，辅太子，遂使高祖辍废太子之议。绮里季为其中之一，后亦以“绮里季”泛指隐士。"});
     所有隐士.push({id:8,_code:11008,名称:"夏黄公",家族:"崔",地区:12,头像:1196,统帅:57,武力:33,智力:95,政治:94,魅力:80,清廉:99,野心:30,性别:0,文化:8,介绍:"夏黄公，又称黄石公，原来姓崔名广，字少通，鄞县（今浙江宁波）人。一说本是齐国人，因隐居夏里修道而得名。秦汉之际一位著名隐士，与隐士绮里季，东园公，甪里先生并称为“商山四皓”。秦末天下大乱，四位老人为躲避战乱而隐居商山。汉高祖曾召夏黄公入廷为官，辅佐太子（即后来的汉惠帝刘盈）。 传说张良年轻时曾得到黄石公的指点。张良在圯桥替黄石公“三次进履”，得黄石公送的一部《太公兵法》。"});
     所有隐士.push({id:9,_code:11009,名称:"严光",家族:"严",地区:13,头像:1219,统帅:78,武力:43,智力:95,政治:96,魅力:80,清廉:99,野心:30,性别:0,文化:8,介绍:"东汉隐士严光(生卒年未详)，一名遵，字子陵，余姚人。东汉建武元年(25)，刘秀即位为光武帝，严光乃隐名换姓，避至他乡。刘秀思贤念旧，令绘形貌寻访。遣使备车，三聘而始至京都洛阳。刘秀至授谏议大夫，不从，归隐富春山(今桐庐县境内)耕读垂钓。80岁卒于家。诏郡县赐钱百万、谷千斛安葬，墓在陈山(客星山)。以“高风亮节”名闻后世。"});
     所有隐士.push({id:10,_code:11010,名称:"陶弘景",家族:"陶",地区:8,头像:1242,统帅:33,武力:43,智力:98,政治:91,魅力:80,清廉:99,野心:30,性别:0,文化:8,介绍:"陶弘景(456年～536年)，字通明，号华阳隐居，人称“山中宰相”，南朝梁时丹阳秣陵(今江苏南京)人。中国南朝齐、梁时期的道教思想家、医药家、炼丹家、文学家，晚号华阳隐居，卒谥贞白先生。南朝南齐南梁时期的道教茅山派代表人物之一。"});
     所有隐士.push({id:11,_code:11011,名称:"诸葛孔明",家族:"诸葛",地区:11,头像:1265,统帅:99,武力:70,智力:99,政治:99,魅力:90,清廉:95,野心:18,性别:0,文化:8,介绍:"字孔明，号卧龙（也作伏龙），三国时期蜀汉丞相，杰出的政治家、军事家、散文家、书法家、发明家。在世时被封为武乡侯，东晋政权因其军事才能特追封他为武兴王。"});
     所有隐士.push({id:12,_code:11012,名称:"拔都",家族:"孛尔只斤",地区:14,头像:1288,统帅:98,武力:98,智力:86,政治:78,魅力:80,清廉:58,野心:32,性别:0,文化:10,介绍:"钦察汗国的创建者，蒙古历史上最杰出的军事统帅之一，曾与速不台等横扫东欧与北亚，为钦察汗国的建立奠定基础，蒙古人因他对部下宽大，称他为撒因汗（意为好汗）。"});
     所有隐士.push({id:13,_code:11013,名称:"刘罗锅",家族:"刘",地区:8,头像:1311,统帅:51,武力:18,智力:93,政治:96,魅力:11,清廉:90,野心:20,性别:0,文化:8,介绍:"字崇如，号石庵，清朝政治家、书法家，以奉公守法、清正廉洁闻名于世。刘墉的书法造诣深厚，是清代著名的帖学大家，被世人称为“浓墨宰相”。"});
     所有隐士.push({id:14,_code:11014,名称:"明珠",家族:"纳兰",地区:4,头像:1334,统帅:34,武力:78,智力:90,政治:91,魅力:84,清廉:77,野心:62,性别:0,文化:18,介绍:"叶赫那拉氏，字端范，太子太傅等要职。纳兰明珠对康熙议撤三藩、统一台湾以及抗御外敌等重大事件中起到积极作用。"});
     所有隐士.push({id:15,_code:11015,名称:"鳌拜",家族:"瓜尔佳",地区:4,头像:1357,统帅:88,武力:91,智力:55,政治:65,魅力:44,清廉:50,野心:99,性别:0,文化:18,介绍:"中国清初权臣，出身瓜尔佳氏。以战功封公爵。鳌拜前半生军功赫赫，号称“满洲第一勇士”，后半生则操握权柄、结党营私。"});
     所有隐士.push({id:16,_code:11016,名称:"尉迟迥",家族:"尉迟",地区:7,头像:1380,统帅:89,武力:85,智力:89,政治:20,魅力:20,清廉:70,野心:60,性别:0,文化:15,介绍:"尉迟迥，字薄居罗，代地人，鲜卑族，西魏、北周将领，。尉迟迥能征善战，好施爱士，位望崇重。初为宇文泰帐内都督，跟随宇文泰收复弘农，攻克沙苑，累有军功，任尚书右仆射、大将军。事，镇守蜀地。宣帝死后，杨坚独揽天下兵马事，他起兵讨伐坚，兵败自杀。"});
     所有隐士.push({id:17,_code:11017,名称:"尔朱荣",家族:"尔朱",地区:7,头像:1403,统帅:90,武力:80,智力:80,政治:30,魅力:30,清廉:20,野心:90,性别:0,文化:15,介绍:"尔朱荣，字天宝，北秀容人，契胡族，北魏末年将领、权臣。尔朱荣于乱世中南征北战，逐渐弄清北魏的虚弱，加之自己势力的不断强大，最终得以挟帝自重、权倾天下。最终由于骄横跋扈，为北魏孝庄帝所杀，年仅三十八岁。历史上尔朱荣骂名滚滚，被归入奸雄行列，但其卓越的军事才能得到了肯定。"});
     所有隐士.push({id:18,_code:11018,名称:"哲别",家族:"别速",地区:15,头像:1426,统帅:90,武力:95,智力:60,政治:40,魅力:50,清廉:70,野心:20,性别:0,文化:10,介绍:"哲别，原名只儿豁阿歹，蒙古别速部人，蒙古帝国名将。最初臣服泰赤乌部，后投降成吉思汗，赐名哲别。哲别骁勇善战，由十户长屡升至千户长。1211年，随成吉思汗南下攻金，破乌沙堡、乌月营，拔德兴府，入居庸关，直抵中都。"});
     所有隐士.push({id:19,_code:11019,名称:"庞统",家族:"庞",地区:11,头像:1449,统帅:89,武力:50,智力:95,政治:88,魅力:1,清廉:90,野心:60,性别:0,文化:8,介绍:"字士元，号凤雏，三国时刘备手下的重要谋士，与诸葛亮同拜为军师中郎将。"});
     所有隐士.push({id:20,_code:11020,名称:"管仲",家族:"管",地区:10,头像:1472,统帅:78,武力:65,智力:95,政治:99,魅力:88,清廉:82,野心:42,性别:0,文化:8,介绍:"姬姓，管氏，名夷吾，字仲，谥敬，春秋时期法家代表人物。 管仲在任内大兴改革，即管仲改革，富国强兵，重视商业，并因开创国营娼妓制度而曾被中国性服务业供奉为保护神。"});
     所有隐士.push({id:21,_code:11021,名称:"石韬",家族:"石",地区:11,头像:1495,统帅:78,武力:34,智力:90,政治:94,魅力:81,清廉:86,野心:20,性别:0,文化:8,介绍:"石韬，字广元，颍川人，仕魏，官拜典农校尉、郡守。初平年间，石韬与徐庶一同来到荆州，在荆州时与诸葛亮和庞统相交甚笃。后来诸葛亮伐魏时获悉徐庶任御史中丞，石韬任郡守时，不由感慨道：“魏殊多士邪，何彼二人不见用乎”，为徐、石二人仕途不畅而鸣不平。"});
     所有隐士.push({id:22,_code:11022,名称:"速不台",家族:"兀良哈",地区:16,头像:1518,统帅:88,武力:90,智力:63,政治:22,魅力:65,清廉:80,野心:36,性别:0,文化:10,介绍:"速不台，蒙古兀良哈部人，蒙元帝国名将，成吉思汗的“四獒”之一。早年辅佐成吉思汗统一诸部，常任先锋，以骁勇善战著称，享有“巴特尔”（勇士）称号。蒙古建国时，封千户长，为十大功臣之一。曾参与第一、第二次西征，令大蒙古国版图扩展至俄罗斯一带。其征战所及东至高丽，西达波兰、匈牙利，北到西伯利亚，南抵开封。是古代世界征战范围最广的将领之一。死后追封为河南王，谥忠定。"});
     所有隐士.push({id:23,_code:11023,名称:"耶律楚材",家族:"耶律",地区:5,头像:1541,统帅:88,武力:27,智力:95,政治:95,魅力:80,清廉:94,野心:38,性别:0,文化:4,介绍:"耶律楚材，字晋卿，号玉泉老人，法号湛然居士，蒙古名吾图撒合里，契丹族，蒙古帝国时期杰出的政治家、宰相。金国尚书右丞耶律履之子。1215年，成吉思汗的蒙古大军攻占燕京时候，听说他才华横溢、满腹经纶，遂向他询问治国大计。而耶律楚材也因对金朝失去信心，决心转投成吉思汗帐下他的到来，对成吉思汗及其子孙产生深远影响，他采取的各种措施为元朝的建立奠定基础。乃马真后称制时，渐失信任，抑郁而死。"});
     所有隐士.push({id:24,_code:11024,名称:"完颜陈和尚",家族:"完颜",地区:4,头像:1564,统帅:96,武力:97,智力:72,政治:56,魅力:67,清廉:83,野心:42,性别:0,文化:18,介绍:"完颜陈和尚，本名彝，字良佐，金末名将。贞祐初，为蒙古军所俘，年余后逃归金朝，任宣差提控。1225年，随军屯驻方城，因处理军中相殴事被控入狱，后获释，任忠孝军提控。忠孝军勇悍善战，但难控制，他严于治军，信赏明罚，使令行禁止。蒙古军攻金，自请为前锋，率400骑于大昌原破蒙古军8000之众，名震天下，以功授定远大将军、平凉府判官、世袭谋克。后相继在卫州、倒回谷等地击败蒙古军，以功迁御侮中郎将。"});
     所有隐士.push({id:25,_code:11025,名称:"木华黎",家族:"札剌亦儿",地区:14,头像:1587,统帅:90,武力:89,智力:90,政治:86,魅力:80,清廉:77,野心:49,性别:0,文化:10,介绍:"木华黎，蒙古国磊将、开国功臣，与博尔术最受器重，被铁木真誉为“犹车之有辕，身之有臂。”以沉毅多智、雄勇善战著称，三十年间追随铁木真，无役不从。辅佐成吉思汗统一蒙古诸部，战功卓著，被称誉为“四杰”之一。成吉思汗曾对木华黎说：“国内平定，汝等之力居多。我之与汝犹车之有辕，身之有臂也（《元史。木华黎传》）。成吉思汗元年（公元1206年），与博尔术被成吉思汗分别命为左、右万户。"});
     所有隐士.push({id:26,_code:11026,名称:"苏格拉底",家族:undefined,地区:37,头像:1610,统帅:33,武力:43,智力:98,政治:91,魅力:80,清廉:99,野心:30,性别:0,文化:7,介绍:"苏格拉底，古希腊著名的思想家、哲学家、教育家、公民陪审员，他和他的学生柏拉图，以及柏拉图的学生亚里士多德被并称为“古希腊三贤”，更被后人广泛地认为是西方哲学的奠基者。他身为雅典的公民，据记载，苏格拉底最后被雅典法庭以侮辱雅典神和腐蚀雅典青年思想之罪名判处死刑。尽管苏格拉底曾获得逃亡的机会，但他仍选择饮下毒堇汁而死，因为他认为逃亡只会进一步破坏雅典法律的权威，同时也是因为担心他逃亡后雅典将再没有好的导师可以教育人们了。"});
     所有隐士.push({id:27,_code:11027,名称:"柏拉图",家族:undefined,地区:37,头像:1633,统帅:33,武力:43,智力:98,政治:91,魅力:80,清廉:99,野心:30,性别:0,文化:7,介绍:"柏拉图，古希腊伟大的哲学家，也是全部西方哲学乃至整个西方文化最伟大的哲学家和思想家之一，他和老师苏格拉底，学生亚里士多德并称为希腊三贤另有其创造或发展的概念包括：柏拉图思想、柏拉图主义、柏拉图式爱情等。柏拉图的主要作品为对话录，其中绝大部分对话都有苏格拉底出场。但学术界普遍认为，其中的苏格拉底形象并不完全是历史上的苏格拉底。"});
     所有隐士.push({id:28,_code:11028,名称:"亚里士多德",家族:undefined,地区:37,头像:1656,统帅:33,武力:43,智力:98,政治:91,魅力:80,清廉:99,野心:30,性别:0,文化:7,介绍:"亚里士多德，古代先哲，古希腊人，世界古代史上伟大的哲学家、科学家和教育家之一，堪称希腊哲学的集大成者。他是柏拉图的学生，亚历山大的老师。"});
     所有隐士.push({id:29,_code:11029,名称:"阿基米德",家族:undefined,地区:37,头像:1679,统帅:33,武力:43,智力:98,政治:91,魅力:80,清廉:99,野心:30,性别:0,文化:7,介绍:"阿基米德，伟大的古希腊哲学家、百科式科学家、数学家、物理学家、力学家，静态力学和流体静力学的奠基人，并且享有“力学之父”的美称，阿基米德和高斯、牛顿并列为世界三大数学家。阿基米德曾说过：“给我一个支点，我就能撬起整个地球。”"});
     所有隐士.push({id:30,_code:11030,名称:"荷马",家族:undefined,地区:37,头像:1702,统帅:33,武力:43,智力:98,政治:91,魅力:80,清廉:99,野心:30,性别:0,文化:7,介绍:"荷马，古希腊盲诗人。公元前873年生。约前9世纪－前8世纪。相传记述公元前12～前11世纪特洛伊战争，以及关海上冒险故事的古希腊长篇叙事代表作史诗《伊利亚特》和《奥德赛》，即是他根据民间流传的短歌综合编写而成。他生活的年代，当在公元前10～前9、8世纪之间。他的杰作《荷马史诗》，在很长时间里影响了西方的宗教、文化和伦理观。"});
     所有隐士.push({id:31,_code:11031,名称:"慕容三藏",家族:"慕容",地区:4,头像:1725,统帅:61,武力:59,智力:81,政治:85,魅力:78,清廉:80,野心:21,性别:0,文化:15,介绍:"慕容三藏（公元544～611年待考），燕人。著名隋朝大臣。先后掌管府库、图籍诸事，任青州刺史、御史中丞、徐州刺史、尚书左仆射、东南道行台（为击讨侯景而设）、南道行台（为抗击西魏王思政设）等职。"});
     所有隐士.push({id:32,_code:11032,名称:"慕容延钊",家族:"慕容",地区:5,头像:1748,统帅:88,武力:89,智力:73,政治:44,魅力:73,清廉:69,野心:8,性别:0,文化:15,介绍:"慕容延钊（公元908～964年），字化龙；山西太原人。著名五代、宋初将领。慕容延钊戎马一生，他善于攻伐，南征北战，以军事统帅的身份参加了后周和北宋几次主要的统一战争，并立下显赫战功。"});
     所有隐士.push({id:33,_code:11033,名称:"慕容绍宗",家族:"慕容",地区:6,头像:1771,统帅:78,武力:84,智力:75,政治:72,魅力:86,清廉:85,野心:29,性别:0,文化:15,介绍:"东魏名将，鲜卑族。前燕太原王慕容恪之后，北魏恒州刺史慕容远之子。后来归顺高欢，历任青州刺史、晋州刺史、徐州刺史等职，封燕郡公。"});
     所有隐士.push({id:34,_code:11034,名称:"宇文肱",家族:"宇文",地区:7,头像:1794,统帅:88,武力:91,智力:71,政治:71,魅力:53,清廉:80,野心:33,性别:0,文化:15,介绍:"北朝北魏将领。武川（今属内蒙）人。鲜卑族，宇文泰父。魏明帝时，破六韩拔陵起义，宇文肱聚兵攻杀破六韩拔陵部将卫可孤。迁居中山。后率众归鲜于修礼军，被魏军击败，战死。北周追尊为德皇帝。"});
     所有隐士.push({id:35,_code:11035,名称:"慕容恪",家族:"慕容",地区:7,头像:1817,统帅:80,武力:85,智力:81,政治:85,魅力:93,清廉:74,野心:56,性别:0,文化:15,介绍:"慕容恪（321年—367年），昌黎棘城人，鲜卑族，前燕文明帝慕容皝第四子，前燕景昭帝慕容儁之弟，十六国时期前燕杰出的政治家、军事家，被后世誉为十六国十大名将之一。"});
     所有隐士.push({id:36,_code:11036,名称:"李白",家族:"李",地区:12,头像:1840,统帅:20,武力:76,智力:90,政治:25,魅力:94,清廉:90,野心:19,性别:0,文化:8,介绍:"李白（701年2月8日—762年12月） ，字太白，号青莲居士，又号“谪仙人”。是唐代伟大的浪漫主义诗人，被后人誉为“诗仙”。与杜甫并称为“李杜”，为了与另两位诗人李商隐与杜牧即“小李杜”区别，杜甫与李白又合称“大李杜”。其人爽朗大方，爱饮酒作诗，喜交友。"});
     所有隐士.push({id:37,_code:11037,名称:"杜甫",家族:"杜",地区:12,头像:1863,统帅:45,武力:36,智力:90,政治:68,魅力:65,清廉:88,野心:5,性别:0,文化:8,介绍:"杜甫（公元712年－公元770年），字子美，汉族，本襄阳人，后徙河南巩县。 自号少陵野老，唐代伟大的现实主义诗人，与李白合称“李杜”。为了与另两位诗人李商隐与杜牧即“小李杜”区别，杜甫与李白又合称“大李杜”，杜甫也常被称为“老杜”。杜甫在中国古典诗歌中的影响非常深远，被后人称为“诗圣”，他的诗被称为“诗史”。后世称其杜拾遗、杜工部，也称他杜少陵、杜草堂。"});
